package com.hdworldmarkers;

import com.google.common.base.Strings;
import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.awt.Color;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;

/** The objects marked with Mark object, saved per region of the map. */
@Singleton
final class ObjectMarkerSource
{
    /** Config key prefix of a region's marked objects. */
    static final String KEY = "objects_";
    static final int HF_HULL = 0x1, HF_OUTLINE = 0x2, HF_CLICKBOX = 0x4, HF_TILE = 0x8;

    private final Client client;
    private final ConfigManager configs;
    private final Gson gson;
    private final HdWorldMarkersConfig config;
    private final Map<Integer, List<ObjectPoint>> points = new HashMap<>();
    private final List<Marked> objects = new ArrayList<>();

    @Inject
    ObjectMarkerSource(Client client, ConfigManager configs, Gson gson, HdWorldMarkersConfig config)
    {
        this.client = client; this.configs = configs; this.gson = gson; this.config = config;
    }

    /** A marked object in the scene, with its own colors and styles (flags; 0 for the options'). */
    static final class Marked
    {
        final TileObject object;
        final ObjectComposition composition;
        final String name;
        final Color borderColor, fillColor;
        final int flags;

        Marked(TileObject object, ObjectComposition composition, ObjectPoint p)
        {
            this.object = object; this.composition = composition; name = p.name; borderColor = p.borderColor; fillColor = p.fillColor;
            flags = (p.hull == Boolean.TRUE ? HF_HULL : 0) | (p.outline == Boolean.TRUE ? HF_OUTLINE : 0)
                | (p.clickbox == Boolean.TRUE ? HF_CLICKBOX : 0) | (p.tile == Boolean.TRUE ? HF_TILE : 0);
        }
    }

    /**
     * A marked object as saved, in Object Markers' format: the object on this tile, its name, and its own colors and
     * styles (null: the options').
     */
    static final class ObjectPoint
    {
        int id;
        String name;
        int regionX, regionY, z;
        @SerializedName("color")
        Color borderColor;
        Color fillColor;
        Boolean hull, outline, clickbox, tile;

        ObjectPoint(int id, String name, int regionX, int regionY, int z)
        {
            this.id = id; this.name = name; this.regionX = regionX; this.regionY = regionY; this.z = z;
        }

        boolean same(ObjectPoint o) { return id == o.id && regionX == o.regionX && regionY == o.regionY && z == o.z; }

        /** Whether it has a color or style of its own. */
        boolean hasLook() { return borderColor != null || fillColor != null || hull != null || outline != null || clickbox != null || tile != null; }
    }

    /** The marked objects; their saved points stay parsed (per region) until they change. */
    void clear() { objects.clear(); }

    /** The saved points changed: they are read again. */
    void clearPoints() { points.clear(); }

    /** A region's saved points, read once. */
    List<ObjectPoint> points(int region) { return points.computeIfAbsent(region, this::saved); }

    /** A region's saved points, read now: what a change starts from. */
    List<ObjectPoint> saved(int region) { return parse(gson, configs.getConfiguration(HdWorldMarkersConfig.GROUP, KEY + region)); }

    /** Marked objects in Object Markers' format (or this plugin's, its id, name and place); those without a name are left out. */
    static List<ObjectPoint> parse(Gson gson, String json)
    {
        List<ObjectPoint> list = new ArrayList<>();
        if (Strings.isNullOrEmpty(json)) { return list; }
        try
        {
            for (ObjectPoint p : gson.fromJson(json, ObjectPoint[].class))
            {
                if (p != null && p.name != null && !p.name.equals("null")) { list.add(p); }
            }
        }
        catch (RuntimeException ex) { list.clear(); }
        return list;
    }

    /** Loads the points of every loaded region; objects are matched as the scene is visited. */
    void load(WorldView wv)
    {
        if (wv == null || wv.getMapRegions() == null) { return; }
        for (int region : wv.getMapRegions()) { points(region); }
    }

    /** As Object Markers' checkObjectPoints. */
    void check(TileObject object)
    {
        // No saved points loaded (as during a scene load, before the rebuild): nothing to match.
        if (object == null || object.getPlane() < 0 || points.isEmpty()) { return; }
        WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, object.getLocalLocation(), object.getPlane());
        List<ObjectPoint> regionPoints = points.get(worldPoint.getRegionID());
        if (regionPoints == null || regionPoints.isEmpty()) { return; }
        ObjectComposition composition = client.getObjectDefinition(object.getId());
        if (composition == null) { return; }
        if (composition.getImpostorIds() == null)
        {
            // Multiloc names are instead checked when drawing.
            String name = composition.getName();
            if (Strings.isNullOrEmpty(name) || name.equals("null")) { return; }
        }
        for (ObjectPoint p : regionPoints)
        {
            if (worldPoint.getRegionX() == p.regionX && worldPoint.getRegionY() == p.regionY
                && worldPoint.getPlane() == p.z && p.id == object.getId())
            {
                remove(object);
                objects.add(new Marked(object, composition, p));
                break;
            }
        }
    }

    void remove(TileObject object) { objects.removeIf(o -> o.object == object); }

    /** The mark of this object as found in the scene, or null. */
    Marked find(TileObject object)
    {
        for (Marked m : objects) { if (m.object == object) { return m; } }
        return null;
    }

    /** The colors in use in these regions' marks (up to five), for the color menus. */
    List<Color> usedColors(int[] regions, boolean fill)
    {
        List<Color> colors = new ArrayList<>();
        for (int region : regions == null ? new int[0] : regions)
        {
            for (ObjectPoint p : points(region))
            {
                Marking.offer(colors, fill ? p.fillColor : p.borderColor);
            }
        }
        return colors;
    }

    void removeWorldView(WorldView wv) { objects.removeIf(o -> o.object.getWorldView() == wv); }

    /** Marks to draw now, in the styles chosen in the settings, as ObjectIndicatorsOverlay.render resolves them. */
    List<Resolved> visible()
    {
        if (objects.isEmpty()) { return Collections.emptyList(); }
        WorldView top = client.getTopLevelWorldView();
        int defaultFlags = (config.objectHull() ? HF_HULL : 0) | (config.objectOutline() ? HF_OUTLINE : 0)
            | (config.objectClickbox() ? HF_CLICKBOX : 0) | (config.objectTile() ? HF_TILE : 0);
        // The options once, not per object: each is a call through the config proxy.
        Color color = config.objectColor(), fillColor = config.objectFillColor();
        double width = config.objectBorderWidth();
        Color defaultOther = fillColor != null ? fillColor : twelfth(color);
        List<Resolved> result = new ArrayList<>();
        for (Marked m : objects)
        {
            WorldView wv = m.object.getWorldView();
            if (wv == null || m.object.getPlane() != wv.getPlane()) { continue; }
            WorldEntity entity = top == null ? null : top.worldEntities().byIndex(wv.getId());
            if (entity != null && entity.isHiddenForOverlap()) { continue; }
            ObjectComposition composition = m.composition;
            if (composition.getImpostorIds() != null)
            {
                // A multiloc: only mark it while the name still matches.
                composition = composition.getImpostor();
                if (composition == null || Strings.isNullOrEmpty(composition.getName())
                    || "null".equals(composition.getName()) || !composition.getName().equals(m.name)) { continue; }
            }
            Color border = m.borderColor != null ? m.borderColor : color;
            Color fill = m.fillColor != null ? m.fillColor : fillColor;
            // Without a fill the hull's is Object Markers' default (a=50); clickbox and tile use the border color at a/12.
            Color hullFill = fill != null ? fill : Marker.BLACK_FILL;
            Color otherFill = fill != null ? fill : border == color ? defaultOther : twelfth(border);
            result.add(new Resolved(m.object, m.flags != 0 ? m.flags : defaultFlags, border, hullFill, otherFill, width));
        }
        return result;
    }

    /** A color at a twelfth of its alpha: Object Markers' clickbox and tile fill without a fill color. */
    private static Color twelfth(Color c) { return new Color(c.getRed(), c.getGreen(), c.getBlue(), c.getAlpha() / 12); }

    static final class Resolved
    {
        final TileObject object;
        final int flags;
        final Color border, hullFill, otherFill;
        final double borderWidth;

        Resolved(TileObject object, int flags, Color border, Color hullFill, Color otherFill, double borderWidth)
        {
            this.object = object; this.flags = flags; this.border = border; this.hullFill = hullFill;
            this.otherFill = otherFill; this.borderWidth = borderWidth;
        }
    }
}

package com.hdworldmarkers;

import java.util.*;
import java.util.function.BooleanSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.util.Text;

/**
 * Warns in the chat box when other plugins that are on draw what HD World Markers draws too, so it is drawn twice,
 * naming them; the Double drawing warning option turns this off. Other plugins' settings are only read.
 */
@Singleton
final class OverlapWarnings
{
    static final String TILE_INDICATORS = "net.runelite.client.plugins.tileindicators.TileIndicatorsPlugin";
    static final String BETTER_NPC_HIGHLIGHT = "com.betternpchighlight.BetterNpcHighlightPlugin";

    /** A plugin that can draw the same: its class, its name, and whether it does now. */
    private static final class Overlap
    {
        final String type, name;
        final BooleanSupplier now;

        Overlap(String type, String name, BooleanSupplier now) { this.type = type; this.name = name; this.now = now; }
    }

    private final PluginManager plugins;
    private final ConfigManager configs;
    private final HdWorldMarkersConfig config;
    private final ChatMessageManager chat;
    private final List<Overlap> overlaps;
    /** Plugins named this session; one turned off is named again when it is turned back on. */
    private final Set<String> warned = new HashSet<>();

    @Inject
    OverlapWarnings(PluginManager plugins, ConfigManager configs, HdWorldMarkersConfig config, ChatMessageManager chat,
        TilePackSource tilePacks, AgilitySource agility, MarkerSources sources)
    {
        this.plugins = plugins; this.configs = configs; this.config = config; this.chat = chat;
        BooleanSupplier always = () -> true;
        BooleanSupplier tileIndicators = () -> config.highlightDestinationTile() || config.highlightHoveredTile() || config.highlightCurrentTile();
        overlaps = Arrays.asList(
            new Overlap("net.runelite.client.plugins.groundmarkers.GroundMarkerPlugin", "Ground Markers", always),
            new Overlap("net.runelite.client.plugins.objectindicators.ObjectIndicatorsPlugin", "Object Markers", always),
            new Overlap("net.runelite.client.plugins.npchighlight.NpcIndicatorsPlugin", "NPC Indicators", always),
            new Overlap(TILE_INDICATORS, "Tile Indicators", tileIndicators),
            new Overlap("com.cornertileindicators.CornerTileIndicatorsPlugin", "Corner Tile Indicators", tileIndicators),
            new Overlap("io.leikvolle.tileindicators.ImprovedTileIndicatorsPlugin", "Improved Tile Indicators", tileIndicators),
            new Overlap("com.pathmarker.PathMarkerPlugin", "Path Marker",
                () -> config.activePathDisplaySetting() != HdWorldMarkersConfig.PathDisplaySetting.NEVER
                    || config.hoverPathDisplaySetting() != HdWorldMarkersConfig.PathDisplaySetting.NEVER),
            new Overlap(BETTER_NPC_HIGHLIGHT, "Better NPC Highlight", this::sameNpcs),
            new Overlap("net.runelite.client.plugins.agility.AgilityPlugin", "Agility", () -> agility.any()
                && (config.agilityObstacles() && on("agility", "showClickboxes") || config.agilityShortcuts() && on("agility", "highlightShortcuts")
                    || config.agilityMarks() && on("agility", "highlightMarks") || config.agilityPortals() && on("agility", "highlightPortals")
                    || config.agilityTraps() && on("agility", "trapOverlay") || config.agilityStick() && on("agility", "highlightStick")
                    || config.agilitySepulchreObstacles() && on("agility", "highlightSepulchreObstacles")
                    || config.agilitySepulchreSkilling() && on("agility", "highlightSepulchreSkilling"))),
            new Overlap("com.tilepacks.TilePacksPlugin", "Tile Packs", () -> config.tilePacks() && tilePacks.any()),
            new Overlap("com.linemarkers.LineMarkerPlugin", "Line Markers", sources::anyLines),
            // The Slayer plugin's own highlight of your task, off unless chosen there.
            new Overlap("net.runelite.client.plugins.slayer.SlayerPlugin", "Slayer", () -> config.npcSlayerTask()
                && (chosen("slayer", "highlightHull") || chosen("slayer", "highlightTile") || chosen("slayer", "highlightOutline"))));
    }

    /** A boolean option of another plugin, on unless saved as off. */
    private boolean on(String group, String key) { return !"false".equals(configs.getConfiguration(group, key)); }

    /** A boolean option of another plugin, off unless saved as on. */
    private boolean chosen(String group, String key) { return "true".equals(configs.getConfiguration(group, key)); }

    /** Whether Better NPC Highlight highlights a name tagged here too (its lists: names, an escaped comma, ":preset"), or your Slayer task as here. */
    private boolean sameNpcs()
    {
        // Both highlighting your Slayer task.
        if (config.npcSlayerTask() && chosen("BetterNpcHighlight", "slayerHighlight")) { return true; }
        Set<String> ours = new HashSet<>();
        for (HdWorldMarkersConfig.NpcStyle style : HdWorldMarkersConfig.NpcStyle.values())
        {
            for (String name : MarkerSources.names(configs, style)) { ours.add(Text.standardize(name)); }
        }
        if (ours.isEmpty()) { return false; }
        for (String style : new String[]{"tile", "trueTile", "swTile", "swTrueTile", "hull", "area", "outline", "clickbox"})
        {
            String list = configs.getConfiguration("BetterNpcHighlight", style + "Names");
            for (String entry : list == null ? new String[0] : list.split("(?<!\\\\),"))
            {
                if (ours.contains(entry.replace("\\,", ",").trim().toLowerCase().split(":")[0])) { return true; }
            }
        }
        return false;
    }

    /** Warns about the plugins that draw the same now, when one of them was not warned about yet. */
    void check()
    {
        if (!config.warnDoubleDrawing()) { return; }
        // Every plugin that draws the same now, named whenever one of them was not named yet: a message naming only the
        // new one read as if the others no longer counted.
        List<String> names = new ArrayList<>();
        boolean any = false;
        for (Overlap o : overlaps)
        {
            if (!enabled(o.type)) { warned.remove(o.type); continue; }
            if (!o.now.getAsBoolean()) { continue; }
            names.add(o.name);
            any |= warned.add(o.type);
        }
        if (!any) { return; }
        boolean one = names.size() == 1;
        Chat.send(chat, Chat.list(names) + (one ? " draws" : " draw") + " the same marks, so they show twice. Turn " + (one ? "it" : "them")
            + " off, or this message with the option Double drawing warning.", true);
    }

    private boolean enabled(String type) { Plugin p = plugin(plugins, type); return p != null && plugins.isPluginEnabled(p); }

    /** The plugin of this class, or null when it is not installed. */
    static Plugin plugin(PluginManager plugins, String type)
    {
        for (Plugin p : plugins.getPlugins()) { if (p.getClass().getName().equals(type)) { return p; } }
        return null;
    }
}

