/**
 * The walking paths, with Path Marker's options: the active path, where your last click makes you walk, and the hover
 * path, where a left click would. Routes come from RouteFinder; every game tick the active path is checked against
 * where you are. The plugin draws the paths' scene tiles (markers); the minimap is drawn here.
 */
@Singleton
final class PathTracker extends Overlay implements KeyListener
{
    /** Options that are never the left click (they can sit above it) and options that never walk. */
    private static final Set<MenuAction> NOT_LEFT_CLICK = EnumSet.of(EXAMINE_ITEM_GROUND, EXAMINE_NPC, EXAMINE_OBJECT, RUNELITE,
        RUNELITE_HIGH_PRIORITY, RUNELITE_INFOBOX, RUNELITE_OVERLAY, RUNELITE_OVERLAY_CONFIG, RUNELITE_PLAYER), NOT_WALKING = EnumSet.of(CANCEL,
        CC_OP, CC_OP_LOW_PRIORITY, PLAYER_EIGHTH_OPTION, WIDGET_CLOSE, WIDGET_CONTINUE, WIDGET_FIRST_OPTION, WIDGET_SECOND_OPTION,
        WIDGET_THIRD_OPTION, WIDGET_FOURTH_OPTION, WIDGET_FIFTH_OPTION, WIDGET_TARGET, WIDGET_TARGET_ON_WIDGET, WIDGET_TYPE_1,
        WIDGET_TYPE_4, WIDGET_TYPE_5);
    /** Options on objects: where they walk, the client's destination tells best (see watching). */
    private static final Set<MenuAction> OBJECT_OPTIONS = EnumSet.of(GAME_OBJECT_FIRST_OPTION, GAME_OBJECT_SECOND_OPTION,
        GAME_OBJECT_THIRD_OPTION, GAME_OBJECT_FOURTH_OPTION, GAME_OBJECT_FIFTH_OPTION, WIDGET_TARGET_ON_GAME_OBJECT);
    /** Tiles a predicted path has at most. */
    static final int MAX_PREDICTED = 300;
    @Inject private Client client;
    @Inject private HdWorldMarkersConfig config;
    @Inject private OverlayManager overlays;
    @Inject private KeyManager keys;
    @Inject private MouseManager mouse;
    RouteFinder routes = new RouteFinder();
    /** The active and hover paths, and a predicted one to a walk target beyond what the client routes. */
    private final Path activePath = new Path(), hoverPath = new Path(), predictedPath = new Path();
    /**
     * Your tile at the last game tick; a click waiting for the next client tick, with the tile under an open menu. The
     * click is copied: RuneLite's menu entries show the menu as it is now, rebuilt by then.
     */
    private WorldPoint lastTile;
    private Click click;
    private Tile clickTile, lastHovered;
    /** A click found no route of its own: the active path follows where the client walks instead. */
    private boolean toDestination;
    /**
     * Client ticks (a game tick's worth) after a click on an object in which the active path takes the client's
     * destination once the click changes it: which side of an obstacle the game walks to, its own rules decide, and the
     * route found here first could lead around it until the next game tick. The destination before the click.
     */
    private int watching;
    private LocalPoint clickDestination;

    /** A clicked option: its kind, its parameters (scene x and y), its id and its character. */
    private static final class Click
    {
        final MenuAction type;
        final int x, y, id;
        final Actor actor;
        Click(MenuEntry e) { type = e.getType(); x = e.getParam0(); y = e.getParam1(); id = e.getIdentifier(); actor = e.getActor(); }
    }
    private Point mouseAt;
    /**
     * A route found at a click may start a tick late (fresh until found again once); mismatch: last tick you were not
     * where the active path put you. pressed: a left press, which may be a minimap click (it has no menu option).
     */
    private boolean fresh, mismatch, clickInMenu, clickRunning, ctrl, keyActive, keyHover, pressed;
    private final MouseAdapter mouseListener = new MouseAdapter()
    {
        @Override public MouseEvent mousePressed(MouseEvent e)
        {
            if (e.getButton() == MouseEvent.BUTTON1) { pressed = true; mouseAt = client.getMouseCanvasPosition(); }
            return e;
        }
    };

    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    /** A route on show: what it leads to and from where, its turns, and the tiles a walk along it stands on or runs past. */
    static final class Path
    {
        Target target;
        WorldPoint from;
        List<WorldPoint> turns = Collections.emptyList();
        boolean running;
        final List<WorldPoint> main = new ArrayList<>(), passed = new ArrayList<>();

        void clear()
        {
            target = null; from = null; turns = Collections.emptyList();
            main.clear(); passed.clear();
        }
    }

    void startUp()
    {
        // Beyond the loaded area an object blocks walking when it is a thing with a name (the client's own flag is not known there).
        routes.blocking = id -> { ObjectComposition d = client.getObjectDefinition(id); return d != null && d.getName() != null && !"null".equals(d.getName()); };
        activePath.clear(); hoverPath.clear(); predictedPath.clear();
        click = null;
        ctrl = keyActive = keyHover = pressed = false;
        overlays.add(this);
        keys.registerKeyListener(this);
        mouse.registerMouseListener(mouseListener);
    }

    void shutDown()
    {
        overlays.remove(this);
        keys.unregisterKeyListener(this);
        mouse.unregisterMouseListener(mouseListener);
    }

    @Override public void keyTyped(KeyEvent e) { }
    @Override public void keyPressed(KeyEvent e) { key(e, true); }
    @Override public void keyReleased(KeyEvent e) { key(e, false); }

    /** Ctrl changes running; a path's keybind shows it while held, or toggles it, as its display option says. */
    private void key(KeyEvent e, boolean down)
    {
        if (e.getKeyCode() == KeyEvent.VK_CONTROL) { ctrl = down; }
        if (config.displayKeybindActivePath().matches(e)) { keyActive = keyed(config.activePathDisplaySetting(), keyActive, down); }
        if (config.displayKeybindHoverPath().matches(e)) { keyHover = keyed(config.hoverPathDisplaySetting(), keyHover, down); }
    }

    private static boolean keyed(PathDisplaySetting display, boolean shown, boolean down)
    {
        return display == PathDisplaySetting.WHILE_KEY_PRESSED ? down : display == PathDisplaySetting.TOGGLE_ON_KEYPRESS && down ? !shown : shown;
    }

    /** Whether a click now runs: the run option, which holding Ctrl inverts or overrides as the game's Ctrl option says. */
    private boolean runOnClick()
    {
        boolean run = client.getVarpValue(VarPlayerID.OPTION_RUN) == 1;
        switch (ctrl ? client.getVarbitValue(VarbitID.RUNINVERT_MODE) : 0)
        {
            case 1: return true;
            case 2: return false;
            case 3: return !run;
            default: return run;
        }
    }

    /** Running on the active path, or for a click now when there is none. */
    boolean running() { return activePath.turns.isEmpty() ? runOnClick() : activePath.running; }

    /** A key released while the client had no focus never arrives: Ctrl would stay held. */
    @Subscribe public void onFocusChanged(FocusChanged e) { if (!e.isFocused()) { ctrl = false; } }

    @Subscribe public void onVarbitChanged(VarbitChanged e)
    {
        if (e.getVarpId() == VarPlayerID.OPTION_RUN) { activePath.running = e.getValue() == 1; }
    }

    @Subscribe public void onGameStateChanged(GameStateChanged e)
    {
        if (e.getGameState() == GameState.HOPPING || e.getGameState() == GameState.LOGGING_IN) { activePath.clear(); }
    }

    /**
     * Found on the next client tick, when the game knows the tile a left-click Walk here goes to; an open menu keeps
     * the tile it was opened on.
     */
    @Subscribe public void onMenuOptionClicked(MenuOptionClicked e)
    {
        click = new Click(e.getMenuEntry());
        clickDestination = client.getLocalDestinationLocation();
        clickInMenu = client.isMenuOpen();
        clickTile = lastHovered;
        clickRunning = runOnClick();
    }

    @Subscribe public void onClientTick(ClientTick e)
    {
        Player me = client.getLocalPlayer();
        if (me == null || !routes.load(me.getWorldView())) { return; }
        Tile hovered = me.getWorldView().getSelectedSceneTile();
        if (click != null)
        {
            Click c = click;
            toDestination = !start(target(c.type, c.x, c.y, c.id, c.actor, clickInMenu ? clickTile : hovered, null), clickRunning)
                && !NOT_WALKING.contains(c.type) && !NOT_LEFT_CLICK.contains(c.type);
            watching = OBJECT_OPTIONS.contains(c.type) ? 30 : 0;
        }
        click = null;
        if (watching > 0)
        {
            watching--;
            LocalPoint destination = client.getLocalDestinationLocation();
            if (destination != null && !destination.equals(clickDestination))
            {
                watching = 0;
                WorldPoint to = WorldPoint.fromLocal(client, destination);
                if (activePath.turns.isEmpty() || !to.equals(last(activePath.turns))) { start(Target.tile(to), clickRunning); }
            }
        }
        // With only Cancel in the menu the mouse can be on the minimap, where a left press walks.
        MenuEntry[] entries = client.getMenu().getMenuEntries();
        WorldPoint minimap = entries.length == 1 && !client.isMenuOpen()
            && (pressed || config.hoverPathDisplaySetting() != PathDisplaySetting.NEVER) ? minimapTile(me) : null;
        // The hover path keeps its target while the mouse is on no tile.
        MenuEntry option = entries.length == 0 ? null : chosen(entries);
        Target t = minimap != null ? Target.tile(minimap) : hovered == null || option == null ? hoverPath.target
            : target(option.getType(), option.getParam0(), option.getParam1(), option.getIdentifier(), option.getActor(), hovered, hoverPath.target);
        if (minimap != null && pressed) { start(t, runOnClick()); }
        pressed = false;
        mouseAt = client.getMouseCanvasPosition();
        lastHovered = hovered;
        hoverTo(t, me.getWorldLocation(), false);
    }

    @Subscribe public void onGameTick(GameTick e)
    {
        Player me = client.getLocalPlayer();
        if (me == null || !routes.load(me.getWorldView())) { return; }
        routes.loadBlockers(me.getWorldView());
        WorldPoint now = me.getWorldLocation();
        LocalPoint destination = client.getLocalDestinationLocation();
        if (toDestination && activePath.turns.isEmpty() && destination != null) { start(Target.tile(WorldPoint.fromLocal(client, destination)), runOnClick()); }
        toDestination = false;
        if (!activePath.turns.isEmpty()) { follow(now); }
        walk(activePath, now, false);
        hoverTo(hoverPath.target, now, true);
        lastTile = now;
    }

    /** The hover path to t from your tile: found again when either changes, walked again also when running changes. */
    private void hoverTo(Target t, WorldPoint from, boolean walk)
    {
        // Shown nowhere (by default): no route search every time the mouse moves; found again once it is shown.
        if (!shows(false, false) && !shows(false, true)) { hoverPath.clear(); return; }
        if (t == null ? hoverPath.target != null : !t.same(hoverPath.target) || !from.equals(hoverPath.from))
        {
            List<WorldPoint> turns = t == null ? null : routes.find(from, t);
            hoverPath.turns = turns == null ? Collections.emptyList() : turns;
            hoverPath.target = t;
            hoverPath.from = from;
            walk = true;
        }
        boolean run = runOnClick();
        if (walk || run != hoverPath.running)
        {
            hoverPath.running = run;
            walk(hoverPath, from, false);
        }
    }

    /**
     * A click's route becomes the active path; when nothing near its target can be reached, the active path stays.
     * Returns whether there is a route.
     */
    private boolean start(Target t, boolean running)
    {
        WorldPoint from = client.getLocalPlayer().getWorldLocation();
        List<WorldPoint> turns = t == null ? null : routes.find(from, t);
        if (turns == null) { return false; }
        activePath.target = t;
        activePath.turns = turns;
        activePath.running = running;
        fresh = true;
        mismatch = false;
        lastTile = from;
        walk(activePath, from, false);
        return true;
    }

    /** Each game tick: the active path against where you are; it ends, or is found again where you left it or its target moved. */
    private void follow(WorldPoint now)
    {
        // The client walks elsewhere than this route ends: to its destination then.
        LocalPoint destination = client.getLocalDestinationLocation();
        WorldPoint to = destination == null ? null : WorldPoint.fromLocal(client, destination);
        if (to != null && !to.equals(last(activePath.turns))) { reroute(Target.tile(to), now); }
        // Arrived, or moved more than two tiles (teleported, or another level).
        if (activePath.turns.isEmpty() || now.equals(last(activePath.turns)) || now.distanceTo(lastTile) > 2) { activePath.clear(); return; }
        // Where the route puts you now: a step on from your last tile walking, two running; a blocked step stays put.
        WorldPoint at = lastTile, end = last(activePath.turns);
        int passed = 0, steps = 0;
        for (; steps < (activePath.running ? 2 : 1) && (at.getX() != end.getX() || at.getY() != end.getY()); steps++)
        {
            if (at.equals(activePath.turns.get(passed))) { passed++; }
            WorldPoint next = routes.step(at, activePath.turns.get(passed));
            at = next == null ? at : next;
        }
        boolean elsewhere = !at.equals(now);
        // You already stood at its end, or were elsewhere two ticks in a row: it is not what you walk.
        if (steps == 0 || elsewhere && !fresh && mismatch) { activePath.clear(); return; }
        // The first time you are elsewhere after a click, the route is found again from where you are.
        if (elsewhere && fresh) { reroute(activePath.target, now); }
        else { activePath.turns.subList(0, Math.min(passed, activePath.turns.size() - 1)).clear(); }
        mismatch = elsewhere;
        // To a character: on the last stretch, found again for where it stands now.
        if (activePath.target.actor != null && activePath.turns.size() < 2) { reroute(Target.of(activePath.target.actor), now); }
    }

    private void reroute(Target t, WorldPoint from)
    {
        List<WorldPoint> turns = routes.find(from, t);
        if (turns != null) { activePath.turns = turns; fresh = false; }
    }

    private static WorldPoint last(List<WorldPoint> points) { return points.get(points.size() - 1); }

    /**
     * Fills a path's tiles: from `from` through its turns, a step at a time as the game moves you, up to a blocked step;
     * blind (a predicted walk beyond the loaded area) through the border and the extended view where it is known, and
     * straight on where nothing is known or a step is blocked, up to MAX_PREDICTED tiles. Running, every other tile is
     * only run past; the last tile is always stood on.
     */
    void walk(Path p, WorldPoint from, boolean blind)
    {
        p.main.clear();
        p.passed.clear();
        if (p.turns.isEmpty() || from.getPlane() != p.turns.get(0).getPlane()) { return; }
        WorldPoint at = from, end = last(p.turns);
        boolean pass = p.running;
        for (WorldPoint turn : p.turns)
        {
            while ((at.getX() != turn.getX() || at.getY() != turn.getY()) && (!blind || p.main.size() + p.passed.size() < MAX_PREDICTED))
            {
                WorldPoint next = blind ? routes.known(at) ? routes.stepBeyond(at, turn) : null : routes.step(at, turn);
                if (next == null)
                {
                    if (!blind) { return; }
                    next = at.dx(Integer.signum(turn.getX() - at.getX())).dy(Integer.signum(turn.getY() - at.getY()));
                }
                at = next;
                (pass && !at.equals(end) ? p.passed : p.main).add(at);
                pass = p.running && !pass;
            }
        }
    }

    /** The menu option a click chooses: the one under the mouse in an open menu, else the left-click option. */
    private MenuEntry chosen(MenuEntry[] entries)
    {
        Menu menu = client.getMenu();
        Point mouse = client.getMouseCanvasPosition();
        if (client.isMenuOpen())
        {
            // Rows of 15 pixels under a 19 pixel title, the last option at the top.
            int y = mouse.getY() - menu.getMenuY() - 19, i = entries.length - 1 - y / 15;
            return y >= 0 && i >= 0 && mouse.getX() > menu.getMenuX() && mouse.getX() < menu.getMenuX() + menu.getMenuWidth() ? entries[i] : entries[0];
        }
        int i = entries.length - 1;
        while (i > 0 && NOT_LEFT_CLICK.contains(entries[i].getType())) { i--; }
        return entries[i];
    }

    /**
     * Where a menu option walks: to an object, a ground item's tile, a character, or (Walk here, and options not named
     * here) the given tile. Null for options that never walk; keep when the target is not found.
     */
    private Target target(MenuAction type, int x, int y, int id, Actor actor, Tile tile, Target keep)
    {
        switch (type)
        {
            case GAME_OBJECT_FIRST_OPTION: case GAME_OBJECT_SECOND_OPTION: case GAME_OBJECT_THIRD_OPTION: case GAME_OBJECT_FOURTH_OPTION:
            case GAME_OBJECT_FIFTH_OPTION: case WIDGET_TARGET_ON_GAME_OBJECT:
                Target object = object(sceneTile(x, y), id);
                return object == null ? keep : object;
            case GROUND_ITEM_FIRST_OPTION: case GROUND_ITEM_SECOND_OPTION: case GROUND_ITEM_THIRD_OPTION: case GROUND_ITEM_FOURTH_OPTION:
            case GROUND_ITEM_FIFTH_OPTION: case WIDGET_TARGET_ON_GROUND_ITEM:
                Tile on = sceneTile(x, y);
                List<TileItem> items = on == null ? null : on.getGroundItems();
                return items != null && items.stream().anyMatch(i -> i != null && i.getId() == id) ? Target.tile(on.getWorldLocation()) : keep;
            case NPC_FIRST_OPTION: case NPC_SECOND_OPTION: case NPC_THIRD_OPTION: case NPC_FOURTH_OPTION: case NPC_FIFTH_OPTION:
            case WIDGET_TARGET_ON_NPC: case PLAYER_FIRST_OPTION: case PLAYER_SECOND_OPTION: case PLAYER_THIRD_OPTION:
            case PLAYER_FOURTH_OPTION: case PLAYER_FIFTH_OPTION: case PLAYER_SIXTH_OPTION: case PLAYER_SEVENTH_OPTION:
            case WIDGET_TARGET_ON_PLAYER:
                return actor == null ? keep : Target.of(actor);
            default:
                return NOT_LEFT_CLICK.contains(type) || NOT_WALKING.contains(type) ? null
                    : tile == null ? keep : Target.tile(tile.getWorldLocation());
        }
    }

    /** The object with this id on a scene tile, as a target, or null. */
    private static Target object(Tile tile, int id)
    {
        if (tile == null) { return null; }
        for (GameObject o : tile.getGameObjects())
        {
            if (o != null && o.getId() == id) { return Target.object(tile.getWorldLocation(), o.sizeX(), o.sizeY(), o.getConfig(), id); }
        }
        WallObject wall = tile.getWallObject();
        DecorativeObject decoration = tile.getDecorativeObject();
        GroundObject ground = tile.getGroundObject();
        int config = wall != null && wall.getId() == id ? wall.getConfig() : decoration != null && decoration.getId() == id
            ? decoration.getConfig() : ground != null && ground.getId() == id ? ground.getConfig() : -1;
        return config < 0 ? null : Target.object(tile.getWorldLocation(), 1, 1, config, id);
    }

    /** A tile of the scene on your level, or null. */
    private Tile sceneTile(int x, int y)
    {
        WorldView wv = client.getLocalPlayer().getWorldView();
        Tile[][] level = wv.getScene().getTiles()[wv.getPlane()];
        return x >= 0 && y >= 0 && x < level.length && y < level[x].length ? level[x][y] : null;
    }

    private Widget minimap()
    {
        return client.getWidget(!client.isResized() ? InterfaceID.Toplevel.MINIMAP : client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
            ? InterfaceID.ToplevelPreEoc.MINIMAP : InterfaceID.ToplevelOsrsStretch.MINIMAP);
    }

    /** The tile under the mouse on the minimap, as the game maps it: turned with the camera, zoom pixels per tile from you. */
    private WorldPoint minimapTile(Player me)
    {
        Widget map = minimap();
        if (mouseAt == null || map == null || map.isHidden() || !map.contains(mouseAt)) { return null; }
        double a = client.getCameraYawTarget() * Perspective.UNIT14, k = 128 / client.getMinimapZoom();
        double x = mouseAt.getX() - map.getCanvasLocation().getX() - map.getWidth() / 2, y = mouseAt.getY() - map.getCanvasLocation().getY() - map.getHeight() / 2;
        LocalPoint at = me.getLocalLocation();
        return WorldPoint.fromScene(me.getWorldView(), Math.floorDiv(at.getX() + (int) ((x * Math.cos(a) + y * Math.sin(a)) * k), 128),
            Math.floorDiv(at.getY() + (int) ((x * Math.sin(a) - y * Math.cos(a)) * k), 128), me.getWorldView().getPlane());
    }

    private static boolean shown(PathDisplaySetting display, boolean key)
    {
        return display == PathDisplaySetting.ALWAYS || display != PathDisplaySetting.NEVER && key;
    }

    /** Whether the active or hover path shows on the minimap or in the game world, by its options (the active one if it exists). */
    private boolean shows(boolean active, boolean minimap)
    {
        DrawLocations where = active ? config.activePathDrawLocations() : config.hoverPathDrawLocations();
        if (where != DrawLocations.BOTH && where != (minimap ? DrawLocations.MINIMAP : DrawLocations.GAME_WORLD)) { return false; }
        if (active) { return shown(config.activePathDisplaySetting(), keyActive); }
        return (!minimap || config.hoverPathMinimap()) && shown(config.hoverPathDisplaySetting(), keyHover) && (!config.drawOnlyIfNoActivePath()
            || activePath.turns.isEmpty() || config.activePathDisplaySetting() == PathDisplaySetting.NEVER);
    }

    /** Passes each tile a path shows to draw, with whether it is stood on: all of them, or only the target tile. */
    private void each(Path p, boolean active, BiConsumer<WorldPoint, Boolean> draw)
    {
        if ((active ? config.activePathDrawMode() : config.hoverPathDrawMode()) == DrawMode.TARGET_TILE)
        {
            if (!p.main.isEmpty()) { draw.accept(last(p.main), true); }
            return;
        }
        p.main.forEach(tile -> draw.accept(tile, true));
        p.passed.forEach(tile -> draw.accept(tile, false));
    }

    /** A path's outline or fill colour, for the tiles stood on (main) or run past. */
    private Color color(boolean active, boolean main, boolean fill)
    {
        if (active) { return main ? fill ? config.activePathFill1() : config.activePathStroke1() : fill ? config.activePathFill2() : config.activePathStroke2(); }
        return main ? fill ? config.hoverPathFill1() : config.hoverPathStroke1() : fill ? config.hoverPathFill2() : config.hoverPathStroke2();
    }

    /**
     * The paths' tiles in the game world, hover path first, for the plugin's renderer. With a walk target predicted
     * beyond what the client routes (MarkerSources.predictedTarget), its path too, while no active path exists or the
     * target lies beyond the loaded area.
     */
    List<Marker> markers(WorldPoint guess)
    {
        List<Marker> out = new ArrayList<>();
        Player me = client.getLocalPlayer();
        if (me == null) { return out; }
        WorldView wv = me.getWorldView();
        if (shows(false, false)) { PathLook hover = new PathLook(false, wv); each(hoverPath, false, (tile, main) -> out.add(hover.marker(tile, main))); }
        if (!shows(true, false)) { return out; }
        PathLook active = new PathLook(true, wv);
        each(activePath, true, (tile, main) -> out.add(active.marker(tile, main)));
        if (guess != null && (activePath.turns.isEmpty() || MarkerSources.outside(wv, guess)))
        {
            if (config.activePathDrawMode() == DrawMode.TARGET_TILE) { out.add(active.marker(guess, true)); }
            else { predict(me, guess); each(predictedPath, true, (tile, main) -> out.add(active.marker(tile, main))); }
        }
        return out;
    }

    /** A path's options as its tiles need them, read once per path rather than per tile (a predicted path has hundreds). */
    private final class PathLook
    {
        final boolean active, dot;
        final Color stroke, fill, passedStroke, passedFill;
        final double width;
        final WorldView wv;

        PathLook(boolean active, WorldView wv)
        {
            this.active = active; this.wv = wv;
            dot = (active ? config.activePathMarkerStyle() : config.hoverPathMarkerStyle()) == MarkerStyle.DOT;
            stroke = color(active, true, false); fill = color(active, true, true);
            passedStroke = color(active, false, false); passedFill = color(active, false, true);
            width = dot ? 2 : config.pathBorderWidth();
        }

        /** A path tile, stood on (main) or run past. */
        Marker marker(WorldPoint tile, boolean main)
        {
            Marker m = new Marker((active ? "path:a:" : "path:h:") + tile.getX() + ":" + tile.getY(), MarkerSources.local(wv, tile), wv.getPlane(), 1, 1,
                main ? stroke : passedStroke, main ? fill : passedFill, width, null);
            m.dot = dot;
            m.layer = active ? Marker.PATH_ACTIVE : Marker.PATH_HOVER;
            return m;
        }
    }

    /**
     * The predicted path to a walk target: the route to the known tile nearest it, through the loaded area's border and
     * on through a renderer's extended view where it is loaded (around water, walls and objects), then straight on,
     * since beyond that nothing is known. Found again only when the target, your tile or running changes.
     */
    private void predict(Player me, WorldPoint guess)
    {
        WorldPoint from = me.getWorldLocation();
        if (Target.tile(guess).same(predictedPath.target) && from.equals(predictedPath.from) && predictedPath.running == running()) { return; }
        predictedPath.target = Target.tile(guess);
        predictedPath.from = from;
        predictedPath.running = running();
        WorldView wv = me.getWorldView();
        List<WorldPoint> turns = new ArrayList<>();
        // This runs while every mark is collected: a failure leaves only the straight line.
        try
        {
            List<WorldPoint> route = routes.load(wv) ? routes.findBeyond(from, Target.tile(routes.clampKnown(guess))) : null;
            if (route != null) { turns.addAll(route); }
        }
        catch (RuntimeException ex)
        {
            turns.clear();
        }
        turns.add(guess);
        predictedPath.turns = turns;
        walk(predictedPath, from, true);
    }

    /** The minimap: both paths' tiles in their fill colours, turned with the camera, up to the minimap's edge. */
    @Override public Dimension render(Graphics2D graphics)
    {
        Player me = client.getLocalPlayer();
        Widget map = minimap();
        if (me == null || map == null || map.isHidden()) { return null; }
        double zoom = client.getMinimapZoom() / 128;
        int cx = map.getCanvasLocation().getX() + map.getWidth() / 2, cy = map.getCanvasLocation().getY() + map.getHeight() / 2;
        LocalPoint at = me.getLocalLocation();
        Graphics2D g = (Graphics2D) graphics.create();
        g.rotate(client.getCameraYawTarget() * Perspective.UNIT14, cx, cy);
        for (boolean active : new boolean[]{false, true})
        {
            if (!shows(active, true)) { continue; }
            each(active ? activePath : hoverPath, active, (tile, main) -> {
                LocalPoint p = LocalPoint.fromWorld(me.getWorldView(), tile);
                if (p == null) { return; }
                double x = (p.getX() - at.getX()) * zoom, y = (at.getY() - p.getY()) * zoom;
                // The minimap shows about 74 pixels around its centre.
                if (Math.hypot(x, y) > 74) { return; }
                g.setColor(color(active, main, true));
                g.fill(new Rectangle2D.Double(cx + x - 64 * zoom, cy + y - 64 * zoom, 128 * zoom, 128 * zoom));
            });
        }
        g.dispose();
        return null;
    }
}

package com.hdworldmarkers;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The part of the canvas around the local player that marks drawn through walls may cover: its bounding box minus the
 * player's silhouette, as convex pieces (trapezoids between horizontal lines through the silhouette's points). A mark
 * keeps what lies outside the box and, inside it, only what lies in these pieces, so the player shows in front of it
 * with its exact outline, as Improved Tile Indicators clears the player's triangles from its overlay.
 */
final class PlayerCut
{
    /** The box: left, top, right, bottom. */
    final float minX, minY, maxX, maxY;
    /**
     * Trapezoids {x0, y0, x1, y1, x2, y2, x3, y3} (convex, clockwise on the canvas), and their bounds {minX, maxX}, by
     * their top (y0) ascending; reach[i] is the lowest bottom (y2) of pieces 0..i, so a face's rows are found by search.
     */
    final List<float[]> pieces = new ArrayList<>();
    float[] reach;

    private PlayerCut(float minX, float minY, float maxX, float maxY)
    {
        this.minX = minX; this.minY = minY; this.maxX = maxX; this.maxY = maxY;
    }

    /** From the silhouette's loops (outer boundaries and holes, any winding); null without any. */
    static PlayerCut of(List<float[]> loops)
    {
        if (loops == null || loops.isEmpty()) { return null; }
        int edges = 0;
        float minX = Float.MAX_VALUE, minY = Float.MAX_VALUE, maxX = -Float.MAX_VALUE, maxY = -Float.MAX_VALUE;
        for (float[] loop : loops)
        {
            edges += loop.length / 2;
            for (int i = 0; i < loop.length; i += 2)
            {
                minX = Math.min(minX, loop[i]); maxX = Math.max(maxX, loop[i]);
                minY = Math.min(minY, loop[i + 1]); maxY = Math.max(maxY, loop[i + 1]);
            }
        }
        if (!(minX < maxX) || !(minY < maxY)) { return null; }
        PlayerCut cut = new PlayerCut(minX - 1, minY - 1, maxX + 1, maxY + 1);
        // Edges as {x0, y0, x1, y1} with y0 < y1; horizontal ones bound no band.
        float[] e = new float[edges * 4];
        float[] ys = new float[edges + 2];
        int ne = 0, ny = 0;
        for (float[] loop : loops)
        {
            int n = loop.length / 2;
            for (int i = 0; i < n; i++)
            {
                int j = (i + 1) % n;
                float x0 = loop[i * 2], y0 = loop[i * 2 + 1], x1 = loop[j * 2], y1 = loop[j * 2 + 1];
                ys[ny++] = y0;
                if (y0 == y1) { continue; }
                if (y0 > y1) { float t = x0; x0 = x1; x1 = t; t = y0; y0 = y1; y1 = t; }
                e[ne * 4] = x0; e[ne * 4 + 1] = y0; e[ne * 4 + 2] = x1; e[ne * 4 + 3] = y1;
                ne++;
            }
        }
        ys[ny++] = cut.minY;
        ys[ny++] = cut.maxY;
        Arrays.sort(ys, 0, ny);
        // Open trapezoids by their left and right boundary (edge index, or -1 / -2 for the box's sides).
        Map<Long, float[]> open = new HashMap<>(), next = new HashMap<>();
        float[] cross = new float[ne];
        int[] crossEdge = new int[ne];
        int[] order = new int[ne];
        for (int band = 0; band + 1 < ny; band++)
        {
            float ya = ys[band], yb = ys[band + 1];
            if (!(yb > ya)) { continue; }
            float ym = (ya + yb) / 2;
            int k = 0;
            for (int i = 0; i < ne; i++)
            {
                if (e[i * 4 + 1] <= ya && e[i * 4 + 3] >= yb)
                {
                    cross[k] = x(e, i, ym);
                    crossEdge[k] = i;
                    order[k] = k;
                    k++;
                }
            }
            // By crossing, in place: a few per band, sorted without boxing each index (this runs every frame the camera moves).
            for (int i = 1; i < k; i++)
            {
                int o = order[i], j = i - 1;
                while (j >= 0 && cross[order[j]] > cross[o]) { order[j + 1] = order[j]; j--; }
                order[j + 1] = o;
            }
            // Outside the silhouette (even-odd): from the box's left side to the first crossing, between the second
            // and third, and so on, to the box's right side.
            next.clear();
            for (int i = 0; i <= k; i += 2)
            {
                int left = i == 0 ? -1 : crossEdge[order[i - 1]];
                int right = i >= k ? -2 : crossEdge[order[i]];
                long key = ((long) left << 32) ^ (right & 0xffffffffL);
                float[] t = open.remove(key);
                if (t == null) { t = new float[]{left, right, ya, yb}; }
                else { t[3] = yb; }
                next.put(key, t);
            }
            for (float[] t : open.values()) { cut.add(e, t); }
            Map<Long, float[]> swap = open; open = next; next = swap;
        }
        for (float[] t : open.values()) { cut.add(e, t); }
        cut.pieces.sort((p, q) -> Float.compare(p[1], q[1]));
        cut.reach = new float[cut.pieces.size()];
        float low = -Float.MAX_VALUE;
        for (int i = 0; i < cut.reach.length; i++) { low = Math.max(low, cut.pieces.get(i)[5]); cut.reach[i] = low; }
        return cut;
    }

    /** The first piece that may reach below y: the pieces before it end above it. */
    int firstBelow(float y)
    {
        int lo = 0, hi = reach.length;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (reach[mid] > y) { hi = mid; } else { lo = mid + 1; } }
        return lo;
    }

    private void add(float[] e, float[] t)
    {
        int left = (int) t[0], right = (int) t[1];
        float ya = t[2], yb = t[3];
        float la = boundary(e, left, ya), lb = boundary(e, left, yb), ra = boundary(e, right, ya), rb = boundary(e, right, yb);
        if (ra - la <= 1e-3f && rb - lb <= 1e-3f) { return; }
        pieces.add(new float[]{la, ya, ra, ya, rb, yb, lb, yb, Math.min(la, lb), Math.max(ra, rb)});
    }

    private float boundary(float[] e, int edge, float y)
    {
        return edge == -1 ? minX : edge == -2 ? maxX : x(e, edge, y);
    }

    private static float x(float[] e, int i, float y)
    {
        float y0 = e[i * 4 + 1], y1 = e[i * 4 + 3];
        float t = (y - y0) / (y1 - y0);
        return e[i * 4] + (e[i * 4 + 2] - e[i * 4]) * t;
    }
}

package com.hdworldmarkers;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Model;

/**
 * An actor's model (the local player's, or an NPC's put In front) as the client draws it this frame, copied (the
 * client's models share their arrays), and the part of the canvas it covers with the camera the client draws with: its
 * front faces, as Improved Tile Indicators clears them from its overlay, traced into a silhouette. Marks drawn through
 * walls leave that out, so the actor stands in front of them (SceneShapeRenderer.Bucket.pullToCamera). Where a wall or
 * object nearer the camera covers the actor, the actor is not seen: that part is left out of the silhouette, so the
 * marks show there as everywhere else.
 */
final class PlayerSilhouette
{
    private final Shape body = new Shape();
    /** The walls and objects of this frame that may stand between the camera and the actors, shared by their silhouettes. */
    private Occluders occluders;
    private final Silhouette.Scratch scratch = new Silhouette.Scratch();
    /** Per raster cell, 1 / depth of the player's nearest face there; 0 for none. */
    private float[] near = new float[0];
    private ModelShapes.Camera camera, lastCamera;
    private PlayerCut cut, lastCut;
    /** Faces of walls and objects taken at most: their models are copied every frame and projected for the cut. */
    static final int MAX_OCCLUDER_FACES = 20000;
    /**
     * How much nearer the camera than the actor a wall or object must be to hide it, in local units; the ground, which
     * is no part of any actor, hides what lies under it (a model's soles, a few units down) by a unit.
     */
    private static final float IN_FRONT = 8, GROUND_IN_FRONT = 1;

    /** A model where it stands, copied, and as projected with the last camera. */
    private static final class Shape
    {
        float[] x = new float[0], y = x, z = x, px = x, py = x, pd = x;
        int[] a = new int[0], b = a, c = a;
        boolean[] skip = new boolean[0], hidden = skip;
        int n, faces, localX, localY, height, orientation;
        /** As an occluder: how much nearer than the actor it must be to hide it. */
        float margin = IN_FRONT;

        /** Copies the model; false when it has nothing to draw. */
        boolean take(Model model, int localX, int localY, int height, int orientation)
        {
            n = model.getVerticesCount();
            faces = model.getFaceCount();
            if (n <= 0 || faces <= 0) { return false; }
            if (x.length < n) { x = new float[n * 2]; y = new float[n * 2]; z = new float[n * 2]; px = new float[n * 2]; py = new float[n * 2]; pd = new float[n * 2]; }
            if (a.length < faces) { a = new int[faces * 2]; b = new int[faces * 2]; c = new int[faces * 2]; skip = new boolean[faces * 2]; hidden = new boolean[faces * 2]; }
            System.arraycopy(model.getVerticesX(), 0, x, 0, n);
            System.arraycopy(model.getVerticesY(), 0, y, 0, n);
            System.arraycopy(model.getVerticesZ(), 0, z, 0, n);
            System.arraycopy(model.getFaceIndices1(), 0, a, 0, faces);
            System.arraycopy(model.getFaceIndices2(), 0, b, 0, faces);
            System.arraycopy(model.getFaceIndices3(), 0, c, 0, faces);
            int[] colors = model.getFaceColors3();
            byte[] alpha = model.getFaceTransparencies();
            for (int f = 0; f < faces; f++)
            {
                // Not drawn: hidden faces, and nearly see-through ones, which Improved Tile Indicators leaves too.
                skip[f] = colors != null && f < colors.length && colors[f] == -2 || alpha != null && f < alpha.length && (alpha[f] & 255) >= 254
                    || a[f] < 0 || b[f] < 0 || c[f] < 0 || a[f] >= n || b[f] >= n || c[f] >= n;
                if (skip[f]) { a[f] = b[f] = c[f] = 0; }
            }
            this.localX = localX; this.localY = localY; this.height = height; this.orientation = orientation;
            margin = IN_FRONT;
            return true;
        }

        /** Takes faces given as model points (x, height as y, z) in place, as the ground around an actor; false for none. */
        boolean take(float[] mx, float[] my, float[] mz, int n, int[] fa, int[] fb, int[] fc, int faces)
        {
            this.n = n; this.faces = faces;
            if (n <= 0 || faces <= 0) { return false; }
            if (x.length < n) { x = new float[n * 2]; y = new float[n * 2]; z = new float[n * 2]; px = new float[n * 2]; py = new float[n * 2]; pd = new float[n * 2]; }
            if (a.length < faces) { a = new int[faces * 2]; b = new int[faces * 2]; c = new int[faces * 2]; skip = new boolean[faces * 2]; hidden = new boolean[faces * 2]; }
            System.arraycopy(mx, 0, x, 0, n); System.arraycopy(my, 0, y, 0, n); System.arraycopy(mz, 0, z, 0, n);
            System.arraycopy(fa, 0, a, 0, faces); System.arraycopy(fb, 0, b, 0, faces); System.arraycopy(fc, 0, c, 0, faces);
            Arrays.fill(skip, 0, faces, false);
            localX = 0; localY = 0; height = 0; orientation = 0;
            margin = GROUND_IN_FRONT;
            return true;
        }

        /**
         * Projects it with this camera, vertices nearer than near left out; faces turned away from the camera are not
         * drawn (the renderers cull them).
         */
        void project(ModelShapes.Camera cam, float near)
        {
            ModelShapes.projectModel(cam, x, y, z, n, localX, localY, height, orientation, px, py, pd, near);
            // The ground (margin GROUND_IN_FRONT) hides from either side; a model's faces turned away are not drawn.
            boolean both = margin == GROUND_IN_FRONT;
            for (int f = 0; f < faces; f++)
            {
                int i = a[f], j = b[f], k = c[f];
                hidden[f] = skip[f] || !both && (px[j] - px[i]) * (py[k] - py[i]) - (py[j] - py[i]) * (px[k] - px[i]) >= 0;
            }
        }
    }

    /** The walls and objects that may stand between the camera and the actors this frame, copied and projected once for all of them. */
    static final class Occluders
    {
        private final List<Shape> shapes = new ArrayList<>();
        private int count, faces;
        private ModelShapes.Camera camera;

        /** Leaves out last frame's walls and objects; this frame's come with add, before the actors' models are taken. */
        synchronized void clear() { count = 0; faces = 0; camera = null; }

        /** A wall's or object's model where it stands, which may hide part of an actor; false once there is no room left. */
        synchronized boolean add(Model model, int localX, int localY, int height, int orientation)
        {
            if (faces + model.getFaceCount() > MAX_OCCLUDER_FACES) { return false; }
            if (count == shapes.size()) { shapes.add(new Shape()); }
            if (shapes.get(count).take(model, localX, localY, height, orientation)) { faces += model.getFaceCount(); count++; }
            return true;
        }

        /** The ground's faces (model points: x, height as y, z) around an actor, which hide what lies under it; false once there is no room left. */
        synchronized boolean addGround(float[] mx, float[] my, float[] mz, int n, int[] fa, int[] fb, int[] fc, int faceCount)
        {
            if (faces + faceCount > MAX_OCCLUDER_FACES) { return false; }
            if (count == shapes.size()) { shapes.add(new Shape()); }
            if (shapes.get(count).take(mx, my, mz, n, fa, fb, fc, faceCount)) { faces += faceCount; count++; }
            return true;
        }

        /**
         * Projects them with this camera, once per camera. Walls and objects right at the camera too: a face with a corner
         * nearer than the renderers draw still covers the actor with the rest of it (only corners behind the camera are
         * left out, with their faces).
         */
        synchronized void project(ModelShapes.Camera cam)
        {
            if (cam.same(camera)) { return; }
            camera = cam;
            for (int i = 0; i < count; i++) { shapes.get(i).project(cam, 1); }
        }
    }

    /** Takes the model, standing at this place, with the walls and objects that may hide it; false when it has nothing to draw. */
    synchronized boolean take(Model model, int localX, int localY, int height, int orientation, Occluders occluders)
    {
        if (!body.take(model, localX, localY, height, orientation)) { return false; }
        this.occluders = occluders;
        if (cut != null) { lastCamera = camera; lastCut = cut; }
        camera = null;
        cut = null;
        return true;
    }

    /**
     * The silhouette as last drawn if that was with this camera, else as cut would trace it: to size the marks' cuts. A
     * frame is built with the camera the client drew the last one with, so the pose of a frame before costs no trace.
     */
    synchronized PlayerCut estimate(ModelShapes.Camera cam)
    {
        return cam.same(lastCamera) && cut == null ? lastCut : cut(cam);
    }

    /** The silhouette as drawn with this camera, traced once per camera; null when nothing of it projects. */
    synchronized PlayerCut cut(ModelShapes.Camera cam)
    {
        if (cam.same(camera)) { return cut; }
        camera = cam;
        body.project(cam, SceneShapeRenderer.PARTIAL_NEAR);
        boolean occluded = occluders != null && occluders.count > 0;
        if (occluded) { occluders.project(cam); }
        // The cell staircase, not the exact edge: a cell of precision does not show in the cut, made every frame.
        cut = PlayerCut.of(Silhouette.trace(body.px, body.py, body.a, body.b, body.c, body.faces, body.hidden, scratch, false,
            occluded ? this::unseen : null));
        return cut;
    }

    /** Leaves the actor's cells out where a wall or object nearer the camera covers them. */
    private void unseen(long[] bits, int words, int w, int h, float ox, float oy, float scale)
    {
        int cells = w * h;
        if (near.length < cells) { near = new float[cells]; }
        Arrays.fill(near, 0, cells, 0);
        float nearest = 0;
        for (int i = 0; i < body.n; i++) { if (body.pd[i] > 0 && !Float.isNaN(body.px[i])) { nearest = Math.max(nearest, 1 / body.pd[i]); } }
        cover(body, w, h, ox, oy, scale, (cell, inverse) -> { if (inverse > near[cell]) { near[cell] = inverse; } });
        // A cell of the raster no face centre fell in (an edge) counts as at the actor's nearest point.
        float fallback = nearest;
        for (int i = 0; i < occluders.count; i++)
        {
            Shape s = occluders.shapes.get(i);
            float margin = s.margin;
            cover(s, w, h, ox, oy, scale, (cell, inverse) -> {
                int column = cell % w, word = cell / w * words + (column >>> 6);
                long bit = 1L << (column & 63);
                if ((bits[word] & bit) == 0) { return; }
                float player = near[cell] > 0 ? near[cell] : fallback;
                // At least the margin nearer: 1 / depth beyond 1 / (actor depth - margin).
                if (player > 0 && inverse * (1 - margin * player) > player) { bits[word] &= ~bit; }
            });
        }
    }

    private interface CellVisit { void at(int cell, float inverse); }

    /** Calls back for every raster cell whose centre one of the shape's faces covers, with 1 / depth there (flat faces). */
    private static void cover(Shape s, int w, int h, float ox, float oy, float scale, CellVisit visit)
    {
        for (int f = 0; f < s.faces; f++)
        {
            if (s.hidden[f]) { continue; }
            int i = s.a[f], j = s.b[f], k = s.c[f];
            float x0 = (s.px[i] - ox) * scale, y0 = (s.py[i] - oy) * scale, x1 = (s.px[j] - ox) * scale, y1 = (s.py[j] - oy) * scale;
            float x2 = (s.px[k] - ox) * scale, y2 = (s.py[k] - oy) * scale;
            if (Float.isNaN(x0 + x1 + x2) || !(s.pd[i] > 0 && s.pd[j] > 0 && s.pd[k] > 0)) { continue; }
            float area = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
            if (Math.abs(area) < 1e-6f) { continue; }
            int cx0 = Math.max(0, (int) Math.ceil(Math.min(x0, Math.min(x1, x2)) - 0.5f)), cx1 = Math.min(w - 1, (int) Math.floor(Math.max(x0, Math.max(x1, x2)) - 0.5f));
            int cy0 = Math.max(0, (int) Math.ceil(Math.min(y0, Math.min(y1, y2)) - 0.5f)), cy1 = Math.min(h - 1, (int) Math.floor(Math.max(y0, Math.max(y1, y2)) - 0.5f));
            if (cx0 > cx1 || cy0 > cy1) { continue; }
            // 1 / depth is linear across the canvas for a flat face.
            float w0 = 1 / s.pd[i], w1 = 1 / s.pd[j], w2 = 1 / s.pd[k];
            float dx = ((w1 - w0) * (y2 - y0) - (w2 - w0) * (y1 - y0)) / area, dy = ((x1 - x0) * (w2 - w0) - (x2 - x0) * (w1 - w0)) / area;
            float sign = Math.signum(area);
            for (int cy = cy0; cy <= cy1; cy++)
            {
                float py = cy + 0.5f;
                for (int cx = cx0; cx <= cx1; cx++)
                {
                    float px = cx + 0.5f;
                    if (sign * ((x1 - x0) * (py - y0) - (y1 - y0) * (px - x0)) < 0 || sign * ((x2 - x1) * (py - y1) - (y2 - y1) * (px - x1)) < 0
                        || sign * ((x0 - x2) * (py - y2) - (y0 - y2) * (px - x2)) < 0) { continue; }
                    visit.at(cy * w + cx, w0 + (px - x0) * dx + (py - y0) * dy);
                }
            }
        }
    }
}

package com.hdworldmarkers;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;

/**
 * Routes and steps as the game takes them, on the collision flags of your level. A route is the client's
 * breadth-first search from your tile, at most 64 tiles each way, trying the steps west, east, south, north and then
 * the diagonals, until it stands on a tile from which the target can be used. Without one, it ends on the visited tile
 * within 10 tiles of the target that lies nearest to it, then takes fewest steps, under 100. Of a route the game keeps
 * the tiles where it turns, at most 25, and walks from turn to turn: diagonally where it can, else along x, else y.
 *
 * Beyond the loaded area the client has no collision flags. For a predicted walk there (findBeyond, stepBeyond) they
 * are approximated from what a renderer's extended view shows: water and other blocked floor, walls, and objects.
 */
class RouteFinder
{
    /** Steps in the client's search order: west, east, south, north, south-west, south-east, north-west, north-east. */
    private static final int[] DX = {-1, 1, 0, 0, -1, 1, -1, 1}, DY = {0, 0, -1, 1, -1, -1, 1, 1};
    /**
     * For a step (dx, dy), at 3 * dx + dy + 4: the client's flags of the tile stepped onto that stop it. The tile is
     * blocked, or has a wall (or a wall's corner) on a side the step crosses.
     */
    private static final int[] STOP = {0x124010e, 0x1240108, 0x1240138, 0x1240102, 0, 0x1240120, 0x1240183, 0x1240180, 0x12401e0};
    /** The search window, centred on your tile, as cells x * SIZE + y. */
    private static final int SIZE = 128, CENTRE = 64 * SIZE + 64;
    /**
     * Path Marker's lists (see THIRD_PARTY_NOTICES.md), which the client's API does not offer: per object the sides it
     * cannot be used from (bits north 1, east 2, south 4, west 8, unrotated), and the NPCs that block walking.
     */
    private static final Map<Integer, Integer> BLOCKED_SIDES = read("loc_blocking.txt"), BLOCKING_NPCS = read("npc_blocking.txt");
    private final int[] steps = new int[SIZE * SIZE], via = new int[SIZE * SIZE], queue = new int[SIZE * SIZE];
    private final List<WorldArea> blockers = new ArrayList<>();
    private int[][] flags;
    private int baseX, baseY, plane;
    /**
     * The extended scene as collision flags (ext[sceneX + extOffset][sceneY + extOffset]), approximated from its tiles;
     * EXT_UNKNOWN where no tile is loaded; null without an extended scene. Made again when the scene, area or level
     * changes, and every EXT_AGE loads (doors open and close).
     */
    private int[][] ext;
    private int extOffset, extAge;
    private Object extScene;
    private int extBaseX, extBaseY, extPlane;
    private static final int EXT_UNKNOWN = -2, EXT_AGE = 500;
    /** The client walks nowhere within this many tiles of the loaded area's edge; beyond it, the extended view decides. */
    private static final int BORDER = 6;
    /** While set (findBeyond, stepBeyond), the border and everything beyond take the extended view's flags. */
    private boolean borderless;
    /** Whether an object of this id blocks walking; null: every object does. */
    java.util.function.IntPredicate blocking;

    /** Takes the collision flags of the level you are on; false while there are none. */
    boolean load(WorldView wv)
    {
        CollisionData[] maps = wv.getCollisionMaps();
        if (maps == null) { return false; }
        plane = wv.getPlane();
        flags = maps[plane].getFlags();
        baseX = wv.getBaseX();
        baseY = wv.getBaseY();
        extended(wv);
        return true;
    }

    /** Flags for the extended scene, as the client makes its own: floor, walls and objects (every object blocks here). */
    private void extended(WorldView wv)
    {
        Scene scene = wv.getScene();
        Tile[][][] tiles = scene == null ? null : scene.getExtendedTiles();
        if (tiles == null || plane < 0 || plane >= tiles.length || tiles[plane].length <= flags.length) { ext = null; extScene = null; return; }
        boolean same = scene == extScene && baseX == extBaseX && baseY == extBaseY && plane == extPlane;
        if (same && ++extAge < EXT_AGE) { return; }
        extAge = 0; extScene = scene; extBaseX = baseX; extBaseY = baseY; extPlane = plane;
        byte[][][] settings = scene.getExtendedTileSettings();
        int size = tiles[plane].length;
        extOffset = (size - flags.length) / 2;
        if (ext == null || ext.length != size) { ext = new int[size][size]; }
        for (int[] row : ext) { Arrays.fill(row, EXT_UNKNOWN); }
        for (int x = 0; x < size; x++)
        {
            for (int y = 0; y < size; y++)
            {
                if (tiles[plane][x][y] == null) { continue; }
                ext[x][y] = settings != null && plane < settings.length && (settings[plane][x][y] & 1) != 0 ? 0x200000 : 0;
            }
        }
        Set<Object> seen = Collections.newSetFromMap(new IdentityHashMap<>());
        for (int x = 0; x < size; x++)
        {
            for (int y = 0; y < size; y++)
            {
                Tile t = tiles[plane][x][y];
                if (t == null) { continue; }
                WallObject w = t.getWallObject();
                if (w != null && seen.add(w)) { wall(x, y, w.getConfig() & 0x1F, w.getConfig() >> 6 & 3); }
                for (GameObject o : t.getGameObjects())
                {
                    if (o == null || !seen.add(o) || blocking != null && !blocking.test(o.getId())) { continue; }
                    LocalPoint at = o.getLocalLocation();
                    if (at == null) { continue; }
                    int sw = Math.floorDiv(at.getX() - (o.sizeX() - 1) * 64, 128) + extOffset, sy = Math.floorDiv(at.getY() - (o.sizeY() - 1) * 64, 128) + extOffset;
                    for (int i = 0; i < o.sizeX(); i++) { for (int j = 0; j < o.sizeY(); j++) { block(sw + i, sy + j, 0x100); } }
                }
            }
        }
    }

    /** A wall as the client flags it: shape 0 a straight wall, 1 and 3 a corner, 2 two sides; rotation 0 west, 1 north, 2 east, 3 south. */
    private void wall(int x, int y, int shape, int rotation)
    {
        // Per rotation the flag on the wall's tile and the one on the neighbour it faces, straight walls and corners.
        int[] side = {0x80, 0x2, 0x8, 0x20}, facing = {0x8, 0x20, 0x80, 0x2}, dx = {-1, 0, 1, 0}, dy = {0, 1, 0, -1};
        int[] corner = {0x1, 0x4, 0x10, 0x40}, cornerFacing = {0x10, 0x40, 0x1, 0x4}, cdx = {-1, 1, 1, -1}, cdy = {1, 1, -1, -1};
        if (shape == 0 || shape == 2)
        {
            block(x, y, side[rotation]); block(x + dx[rotation], y + dy[rotation], facing[rotation]);
        }
        if (shape == 2)
        {
            int r = (rotation + 1) & 3;
            block(x, y, side[r]); block(x + dx[r], y + dy[r], facing[r]);
        }
        if (shape == 1 || shape == 3)
        {
            block(x, y, corner[rotation]); block(x + cdx[rotation], y + cdy[rotation], cornerFacing[rotation]);
        }
    }

    private void block(int x, int y, int bits)
    {
        if (x >= 0 && y >= 0 && x < ext.length && y < ext.length && ext[x][y] != EXT_UNKNOWN) { ext[x][y] |= bits; }
    }

    /** How far the extended view reaches beyond the loaded area, in tiles; 0 without one. */
    int extent() { return ext == null ? 0 : extOffset; }

    /** Whether the flags of this tile are known: in the loaded area, or shown by the extended view. */
    boolean known(WorldPoint p)
    {
        int x = p.getX() - baseX, y = p.getY() - baseY;
        if (x >= 0 && y >= 0 && x < flags.length && y < flags[x].length) { return true; }
        int ex = x + extOffset, ey = y + extOffset;
        return ext != null && ex >= 0 && ey >= 0 && ex < ext.length && ey < ext.length && ext[ex][ey] != EXT_UNKNOWN;
    }

    /** The point moved into the area the flags are known for: the loaded area and the extended view around it. */
    WorldPoint clampKnown(WorldPoint p)
    {
        int reach = extent();
        int x = Math.max(baseX - reach, Math.min(baseX + flags.length - 1 + reach, p.getX()));
        int y = Math.max(baseY - reach, Math.min(baseY + flags.length - 1 + reach, p.getY()));
        return new WorldPoint(x, y, p.getPlane());
    }

    /** As find, for a predicted walk: through the loaded area's border and on through the extended view. */
    List<WorldPoint> findBeyond(WorldPoint from, Target target)
    {
        borderless = true;
        try { return find(from, target); }
        finally { borderless = false; }
    }

    /** As step, for a predicted walk: through the loaded area's border and on through the extended view. */
    WorldPoint stepBeyond(WorldPoint at, WorldPoint to)
    {
        borderless = true;
        try { return step(at, to); }
        finally { borderless = false; }
    }

    /** The NPCs that block walking, where they stand now; the collision flags do not hold them. */
    void loadBlockers(WorldView wv)
    {
        blockers.clear();
        for (NPC npc : wv.npcs())
        {
            NPCComposition c = npc.getTransformedComposition();
            if (c != null && BLOCKING_NPCS.containsKey(c.getId())) { blockers.add(npc.getWorldArea()); }
        }
    }

    /**
     * The client's route from `from` to the target: the tiles where it turns, the last where it ends (none when it
     * ends where it starts); null when nothing near the target can be reached.
     */
    List<WorldPoint> find(WorldPoint from, Target target)
    {
        // Scene coordinates of the window's first cell, and the target in scene coordinates.
        int ox = from.getX() - baseX - 64, oy = from.getY() - baseY - 64;
        Target t = target.shifted(-baseX, -baseY);
        int end = search(ox, oy, t, Integer.MAX_VALUE);
        if (end < 0)
        {
            // Out of reach: the visited tile within 10 of the target nearest to it, then with fewest steps, under 100.
            int best = Integer.MAX_VALUE;
            for (int x = t.x - 10; x <= t.x + 10; x++)
            {
                for (int y = t.y - 10; y <= t.y + 10; y++)
                {
                    int wx = x - ox, wy = y - oy, c = wx * SIZE + wy;
                    if (wx < 0 || wy < 0 || wx >= SIZE || wy >= SIZE || steps[c] < 0 || steps[c] >= 100) { continue; }
                    int dx = Math.max(0, Math.max(t.x - x, x - t.x - t.width + 1)), dy = Math.max(0, Math.max(t.y - y, y - t.y - t.height + 1));
                    int score = (dx * dx + dy * dy) * 100 + steps[c];
                    if (score < best) { best = score; end = c; }
                }
            }
            if (end < 0) { return null; }
        }
        // Back from the end: each tile entered in another direction than the one after it is a turn.
        List<WorldPoint> turns = new ArrayList<>();
        for (int c = end, last = -1; c != CENTRE; c -= DX[via[c]] * SIZE + DY[via[c]])
        {
            if (via[c] != last) { turns.add(0, new WorldPoint(c / SIZE + ox + baseX, c % SIZE + oy + baseY, plane)); }
            last = via[c];
        }
        // The game walks the first 25 turns.
        while (turns.size() > 25) { turns.remove(25); }
        return turns;
    }

    /** The scene tiles {x, y} you can walk to from scene tile (x, y) in at most `most` steps, by the collision flags alone. */
    List<int[]> reachable(int x, int y, int most)
    {
        search(x - 64, y - 64, null, most);
        List<int[]> out = new ArrayList<>(tail);
        for (int i = 0; i < tail; i++) { out.add(new int[]{queue[i] / SIZE + x - 64, queue[i] % SIZE + y - 64}); }
        return out;
    }

    /** Cells visited by the last search, in queue. */
    private int tail;

    /**
     * The client's breadth-first search from the window's centre, at most `most` steps: the cell from which t can be
     * used (-1: none, or no t); the cells visited are queue[0, tail).
     */
    private int search(int ox, int oy, Target t, int most)
    {
        Arrays.fill(steps, -1);
        steps[CENTRE] = 0;
        queue[0] = CENTRE;
        tail = 1;
        for (int head = 0; head < tail; head++)
        {
            int c = queue[head], x = c / SIZE + ox, y = c % SIZE + oy;
            if (t != null && t.reachedFrom(x, y, flag(x, y))) { return c; }
            for (int d = 0; d < 8 && steps[c] < most; d++)
            {
                int wx = c / SIZE + DX[d], wy = c % SIZE + DY[d], n = wx * SIZE + wy;
                if (wx >= 0 && wy >= 0 && wx < SIZE && wy < SIZE && steps[n] < 0 && open(x, y, DX[d], DY[d]))
                {
                    steps[n] = steps[c] + 1;
                    via[n] = d;
                    queue[tail++] = n;
                }
            }
        }
        return -1;
    }

    /** One step from `at` towards `to` as the game moves you: diagonally if free, else along x, else along y; null when blocked. */
    WorldPoint step(WorldPoint at, WorldPoint to)
    {
        int dx = Integer.signum(to.getX() - at.getX()), dy = Integer.signum(to.getY() - at.getY());
        return free(at, dx, dy) ? at.dx(dx).dy(dy) : dx != 0 && free(at, dx, 0) ? at.dx(dx) : dy != 0 && free(at, 0, dy) ? at.dy(dy) : null;
    }

    /** A step the collision flags allow, onto (and diagonally past) no NPC that blocks walking. */
    private boolean free(WorldPoint at, int dx, int dy)
    {
        return open(at.getX() - baseX, at.getY() - baseY, dx, dy) && !blocked(at.dx(dx).dy(dy))
            && (dx == 0 || dy == 0 || !blocked(at.dx(dx)) && !blocked(at.dy(dy)));
    }

    private boolean blocked(WorldPoint p)
    {
        for (WorldArea a : blockers) { if (a.contains(p)) { return true; } }
        return false;
    }

    /** Whether the collision flags allow a step from scene tile (x, y) by (dx, dy); a diagonal also needs both straight steps. */
    private boolean open(int x, int y, int dx, int dy)
    {
        return (flag(x + dx, y + dy) & STOP[3 * dx + dy + 4]) == 0
            && (dx == 0 || dy == 0 || (flag(x + dx, y) & STOP[3 * dx + 4]) == 0 && (flag(x, y + dy) & STOP[dy + 4]) == 0);
    }

    /**
     * The flags of a scene tile; beyond the loaded area the extended view's where known, else every tile is blocked.
     * For a predicted walk (borderless) the loaded area's border takes the extended view's flags too.
     */
    private int flag(int x, int y)
    {
        boolean inner = x >= 0 && y >= 0 && x < flags.length && y < flags[x].length;
        if (inner && !(borderless && ext != null && (x < BORDER || y < BORDER || x >= flags.length - BORDER || y >= flags[x].length - BORDER)))
        { return flags[x][y]; }
        if (ext == null || !borderless && !inner) { return inner ? flags[x][y] : -1; }
        int ex = x + extOffset, ey = y + extOffset;
        if (ex < 0 || ey < 0 || ex >= ext.length || ey >= ext.length) { return -1; }
        int f = ext[ex][ey];
        return f == EXT_UNKNOWN ? -1 : f;
    }

    /** Lines "id=value", maybe followed by " // a comment"; empty when the bundled list cannot be read. */
    private static Map<Integer, Integer> read(String name)
    {
        Map<Integer, Integer> map = new HashMap<>();
        try (BufferedReader in = new BufferedReader(new InputStreamReader(RouteFinder.class.getResourceAsStream(name), StandardCharsets.UTF_8)))
        {
            in.lines().map(line -> line.split("[= ]")).forEach(kv -> map.put(Integer.valueOf(kv[0]), Integer.valueOf(kv[1])));
        }
        catch (IOException | RuntimeException ex)
        {
            map.clear();
        }
        return map;
    }

    /**
     * What a route leads to, from its south-west tile: a tile, an object's footprint with its shape and rotation, or a
     * character's footprint. Made in world coordinates; find moves it into the scene.
     */
    static final class Target
    {
        /** Shapes besides the client's object shapes (0 to 22). */
        static final int TILE = -1, ACTOR = -2;
        /** Per side of a target (west, north, east, south): the wall of a tile on that side that faces the target. */
        private static final int[] FACING = {0x8, 0x20, 0x80, 0x2};
        /** Flags of a blocked tile, which cannot reach along or around a wall. */
        private static final int BLOCKED = 0x12c0100;
        final int x, y, width, height, shape, rotation;
        /** Bit per side (west 1, north 2, east 4, south 8) from which the target cannot be used. */
        final int closedSides;
        /** A character to walk to, which moves. */
        final Actor actor;

        Target(int x, int y, int width, int height, int shape, int rotation, int closedSides, Actor actor)
        {
            this.x = x; this.y = y; this.width = width; this.height = height;
            this.shape = shape; this.rotation = rotation; this.closedSides = closedSides; this.actor = actor;
        }

        static Target tile(WorldPoint p) { return new Target(p.getX(), p.getY(), 1, 1, TILE, 0, 0, null); }

        static Target of(Actor a)
        {
            WorldPoint p = a.getWorldLocation();
            int size = a instanceof NPC ? ((NPC) a).getComposition().getSize() : 1;
            return new Target(p.getX(), p.getY(), size, size, ACTOR, 0, 0, a);
        }

        /** An object with the client's config (shape in bits 0-4, rotation in bits 6-7). */
        static Target object(WorldPoint p, int width, int height, int config, int id)
        {
            int shape = config & 0x1F, rotation = config >> 6 & 3;
            // Only these shapes have sides that cannot be used; the list holds them for rotation 0, which turns with the object.
            int sides = shape == 10 || shape == 11 || shape == 22 ? BLOCKED_SIDES.getOrDefault(id, 0) : 0;
            // Shape 7 is shape 6 seen from the opposite corner.
            return new Target(p.getX(), p.getY(), width, height, shape, shape == 7 ? rotation + 2 & 3 : rotation,
                (sides << rotation + 1 | sides >> 3 - rotation) & 15, null);
        }

        Target shifted(int dx, int dy) { return new Target(x + dx, y + dy, width, height, shape, rotation, closedSides, actor); }

        boolean same(Target o)
        {
            return o != null && x == o.x && y == o.y && width == o.width && height == o.height && shape == o.shape && rotation == o.rotation;
        }

        /** Whether the target can be used from tile (x, y), which has these collision flags, by the client's rules for its kind. */
        boolean reachedFrom(int x, int y, int flags)
        {
            boolean alongX = x >= this.x && x < this.x + width, alongY = y >= this.y && y < this.y + height;
            if (alongX && alongY) { return shape != ACTOR; }
            // The side of the footprint (x, y) lies against: west, north, east or south.
            int side = alongY && x == this.x - 1 ? 0 : alongX && y == this.y + height ? 1 : alongY && x == this.x + width ? 2 : alongX && y == this.y - 1 ? 3 : -1;
            if (side < 0) { return false; }
            // A wall of (x, y) faces the target; for walls also a blocked tile counts. Turn: that side counted from the object's front.
            boolean wall = (flags & FACING[side]) != 0, closed = (flags & (FACING[side] | BLOCKED)) != 0;
            int turn = side - rotation & 3;
            switch (shape)
            {
                // A straight wall: from its front, or along it.
                case 0: return turn == 0 || turn % 2 == 1 && !closed;
                // An L-shaped wall: from its two fronts, or around it.
                case 2: return turn < 2 || !closed;
                // A diagonal wall decoration: from its two open sides.
                case 6: case 7: return turn > 1 && !wall;
                // Footprints: from any side without a wall in between that the object leaves open.
                case 8: case 9: case 10: case 11: case 22: case ACTOR: return !wall && (closedSides >> side & 1) == 0;
                // A tile, and the other shapes: only on it.
                default: return false;
            }
        }
    }
}

package com.hdworldmarkers;

import java.awt.Color;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;

/**
 * The shared scene renderer. Every frame, each tile footprint and model hull
 * is projected to the canvas, given a border of an exact pixel width, and
 * written back into the scene as flat geometry. The GPU rasterizes it at the
 * scene's full resolution, so it is not blurred by the stretched 2D layer.
 *
 * Vertices are unprojected slightly towards the camera along their own view
 * ray. That leaves their screen position unchanged but keeps them above the
 * terrain in depth-tested renderers.
 *
 * All shapes that belong to one tile are merged into a single scene object,
 * whose radius stays inside that tile. The client gives every tile only a few
 * object slots and an object takes one on each tile its radius touches; one
 * object per shape (up to 3x3 tiles each) overflowed them, and the client then
 * dropped a different set of objects every frame.
 */
@Singleton
final class SceneShapeRenderer
{
    private static final int MIN_VERTICES = 64, MIN_FACES = 96, MIN_RADIUS = 256;
    private final Client client;
    private final CarrierModels carriers;
    private final Map<Long, Bucket> buckets = new HashMap<>();
    /** This frame's shapes per bucket key (without part), split over the buckets in rank order in end(). */
    private final Map<Long, Stage> stages = new HashMap<>();
    private final Set<String> appended = new HashSet<>();
    /**
     * Projections per NPC or object (an object's second model part chained, see projection), kept across frames so
     * their arrays are reused. Styles of one NPC share its projection within a frame; static object models keep theirs,
     * silhouette included, while the camera and the object stay where they were.
     */
    private final Map<Object, Projection> projections = new IdentityHashMap<>();
    private int frame;
    /**
     * New outline traces per frame are limited to this much time; the rest move their last trace along (see model). A
     * real NPC model takes about half a millisecond, so a few are traced every frame and a crowd each every few frames.
     */
    private static final long OUTLINE_BUDGET_NANOS = 1_500_000;
    /** Frames an outline's last trace may stand in for a new one over the budget; then it is traced anyway. */
    static final int STALE_OUTLINE_FRAMES = 2;
    private long outlineNanos;

    /** Models no scene object uses now, kept for the next ones: making and uploading a model costs. */
    private final java.util.Deque<Spare> spareCarriers = new ArrayDeque<>();

    /** A model given up by its scene object, with what the next owner must clear of it. */
    private static final class Spare
    {
        final Model model;
        final int radius, usedFaces, usedVertices;
        Spare(Model model, int radius, int usedFaces, int usedVertices)
        { this.model = model; this.radius = radius; this.usedFaces = usedFaces; this.usedVertices = usedVertices; }
    }

    /** Takes the scene object out of the scene and keeps its model as a spare, if there is room. */
    private void retire(Bucket b)
    {
        b.hide();
        Spare spare = b.release();
        if (spare != null && spareCarriers.size() < MAX_SPARES) { spareCarriers.addLast(spare); }
    }
    /** Many tagged NPCs take more objects than 64: after a teleport the rest were all made anew in one frame. */
    private static final int MAX_SPARES = 256;
    /** Spares made ahead while logging in (see prewarm): half for tiles, half for hulls, clickboxes and outlines. */
    private static final int PREWARM = 64;

    /**
     * Makes spare models ahead, in frames that draw nothing yet (logging in), at most budgetNanos per frame: every
     * object of the first frame that drew needed one, all made in that frame. Normals as begin sets them.
     */
    void prewarm(long budgetNanos)
    {
        carriers.nextFrame();
        long start = System.nanoTime();
        while (spareCarriers.size() < PREWARM && System.nanoTime() - start < budgetNanos)
        {
            boolean small = spareCarriers.size() % 2 == 0;
            int radius = small ? MIN_RADIUS : 768;
            Model created = small ? carriers.create(MIN_VERTICES, MIN_FACES, radius) : carriers.create(512, 768, radius);
            if (created == null) { break; }
            FlatModel.normals(created);
            spareCarriers.addLast(new Spare(created, radius, 0, 6));
        }
    }

    /** Frame-local owned data: actor mesh arrays can be overwritten by another getModel(). */
    private static final class Projection
    {
        float[] x = new float[0], y = new float[0], hull;
        int[] a = new int[0], b = new int[0], c = new int[0];
        boolean[] hidden;
        /** Number of faces copied this frame; 0 until an outline needs them. */
        int faces, n;
        float depth;
        boolean outside;
        /** Some vertices were not projected (at or too near the camera): their faces are left out of every shape. */
        boolean partial;
        /** The model's clickbox is its projected bounding box (Model.useBoundingBox), not a union of face rectangles. */
        boolean boundingBox;
        List<float[]> loops;
        /**
         * The last outline traced, for a frame over the outline budget, and the frame and the projected points' bounds it
         * was traced for (centre and size): moved to the bounds of now rather than another shape.
         */
        List<float[]> traced;
        int tracedFrame;
        float tracedCenterX, tracedCenterY, tracedWidth, tracedHeight;
        /** The projected points' bounds: centre and size. */
        float centerX, centerY, width, height2d;
        /** The projected bounding box's convex hull (clickbox bounds), or null; and the clickbox from it. */
        float[] boundsHull;
        List<float[]> clickbox;
        int frame, facesFrame, localX, localY, height, orientation;
        ModelShapes.Camera camera;
        /** The previous projection's points, kept to see whether a new one came out the same (see project). */
        float[] lastX = new float[0], lastY = new float[0];
        /** Hidden faces, summed, and the viewport of the projection: all a clickbox or outline depends on besides points. */
        long hiddenSum;
        int viewport;
        /** The object's model part this is of (null for an NPC); its other part, of walls and decorations, is next. */
        Renderable part;
        Projection next;
    }
    private final Silhouette.Scratch silhouetteScratch = new Silhouette.Scratch();
    private final ScreenOutline outline = new ScreenOutline();
    private final float[] point = new float[3];
    /** Scratch for tiles, model hulls, outlines and clickboxes; ScreenOutline copies what it needs. */
    private float[] px = new float[64], py = new float[64], pd = new float[64];
    private ModelShapes.Camera camera;
    private float pixel = 1;
    /**
     * 117 HD casts a shadow from each face more opaque than its threshold (0.71, or 0.01 with its
     * "shadow transparency"), and floating through-walls marks move with the camera, so their shadows
     * shimmer over the ground. Through-walls faces are drawn at most floatingAlphaCap opaque.
     */
    int floatingAlphaCap = 255;
    /** Shadow transparency off: just under its 0.71 threshold. */
    static final int HD_CAP_OPAQUE_SHADOWS = 180;
    /**
     * 117 HD with its default shading caps the lightness of every coloured face (undoVanillaShading:
     * 127 - 72 * (saturation / 7) ^ 0.05, 55 at full saturation); only grey may be lighter. Light colours,
     * such as pink, would all turn into their pure colour: they are drawn as that colour with white over it.
     */
    boolean hdLightnessCap;
    /** Scratch for FlatModel.layers: {hsl, alpha, white alpha} of border and fill. */
    private final int[] borderLayers = new int[3], fillLayers = new int[3];
    private boolean unavailable;
    private int layer;
    /** Through walls: shapes are pulled towards the camera, gathered in one object where possible. */
    private boolean xray, xrayCameraNear;
    /**
     * Through walls, marks leave out the silhouettes of the local player and the NPCs put In front (set per frame by
     * cutAround): they still show through every wall and object, and those actors stand in front of them. A silhouette is
     * cut out when the client draws, with the camera and pose it draws with, as Improved Tile Indicators clears the player
     * from its overlay; empty for none. The walls and objects that may hide the actors are gathered once for all of them.
     */
    private List<PlayerSilhouette> cuts = Collections.emptyList();
    private final PlayerSilhouette playerShape = new PlayerSilhouette();
    private final Map<NPC, PlayerSilhouette> npcShapes = new IdentityHashMap<>();
    private final PlayerSilhouette.Occluders occluders = new PlayerSilhouette.Occluders();
    /** Actors cut out at most per frame (the player and the NPCs put In front): each costs a trace and more faces under it. */
    static final int MAX_CUTS = 9;
    /**
     * Per shape key, the frame its cut costs were last measured and those costs: measured again every CUT_COSTS_FRAMES
     * frames (staggered), as measuring every shape near a silhouette every frame cost more than the cuts themselves; the
     * room an object keeps (CUT_ROOM, and half as much again per face) covers the frames in between.
     */
    private final Map<String, CutCosts> cutCostCache = new HashMap<>();
    private static final int CUT_COSTS_FRAMES = 4;

    /** A shape's cut costs (ScreenOutline.costs, copied; null for none) and the frame they were measured in. */
    private static final class CutCosts
    {
        int frame;
        int[] costs;
    }
    /** The camera the cached costs were measured from: a camera that jumped since drops them all. */
    private ModelShapes.Camera cutCostCamera;
    /** The actors cut out this frame, which are no occluders of each other, and the objects and tiles looked at for occluders. */
    private final Set<Object> cutActors = Collections.newSetFromMap(new IdentityHashMap<>()), occludersTaken = Collections.newSetFromMap(new IdentityHashMap<>());
    private final Set<Long> occluderTiles = new HashSet<>();
    /**
     * Room a through-walls object keeps besides what its shapes' cuts take as seen now (see split): for faces the player
     * comes over as the camera moves.
     */
    private static final int CUT_ROOM = 600;
    /** Scratch for a shape's cut as it is drawn, which sizes the objects (see cutCosts). */
    private final ScreenOutline sizer = new ScreenOutline();
    /** Per outline face of the shape being appended, what the player's cut makes of it (sizer.before); null for no cut. */
    private int[] shapeCut;
    private LocalPoint xrayAnchor;
    private int xrayLevel, xrayHeight;
    /**
     * Depth of the top layer's through-walls points. 117 HD draws see-through faces without writing depth, sorted by
     * their distance in whole units (ties in face order), and fully opaque faces apart, before them, with depth test
     * and writes. It sorts with the client's whole-unit camera, while the marks follow the exact camera; where faces
     * overlap on the screen they lie on one ray, so that difference moves them alike. Each lower layer sits
     * XRAY_LAYER_DEPTH farther (a light colour's white layer half a step nearer than the colour): a whole unit or more
     * apart they keep the ranking, and in one unit the face order does (lowest rank first, white after its colour). The
     * top layer starts just beyond XRAY_MIN_DEPTH and the layer bias (XRAY_LAYER_SPAN), in the middle of a unit.
     * Whatever is nearer the camera than the marks covers them, such as a wall or object right in front of a low camera
     * (at 200, a quarter of the camera angles around a walled room hid marks), so all layers lie close together.
     */
    private static final float XRAY_DEPTH = 115.5f;
    private static final float XRAY_LAYER_DEPTH = 2, XRAY_TOP_LAYER = 20;
    /**
     * Objects of one bucket key sit at the same place, so the renderer's order among them (by distance to the
     * camera) is undecided: each object with higher ranks after it hangs this much lower, thus farther away. At the
     * camera's height a few units were a tie once 117 HD rounds the camera to whole units.
     */
    private static final int PART_STEP = 32;
    /**
     * Nearest depth of a through-walls vertex. 117 HD clips what is nearer the camera than twice its near plane of 50:
     * its reverse-Z projection (Mat4.perspectiveInfiniteReverseZ) gives clip z 2 x 50 over clip w the depth, so the
     * current and destination tile, pulled to 91 and 97, were not drawn at all. Its camera is the one the marks follow;
     * the GPU plugin, whose own camera may differ slightly, skips a see-through model whole if any vertex is nearer than
     * 50 (ModelUploader.uploadSortedModel).
     */
    private static final float XRAY_MIN_DEPTH = 2 * ModelShapes.NEAR + 10;
    /** Depth taken by the layer bias (0.25 per layer, up to Marker.CURRENT = 18 and a white layer), above XRAY_MIN_DEPTH. */
    private static final float XRAY_LAYER_SPAN = 5;
    /*
     * The GPU plugin draws nothing of a see-through model whose diameter is 6000 or more
     * (ModelUploader.uploadSortedModel; Zone.renderAlpha likewise). Carrier bounds are six extreme
     * vertices at +-radius on each axis, giving a diameter of about 2.83 x radius, so carriers stay
     * within MAX_RADIUS; through-walls points move towards the camera only as far as XRAY_REACH
     * from their object's anchor.
     */
    static final int MAX_RADIUS = 2000, XRAY_REACH = 1900;
    /** Ground points of a shape sharing the through-walls object stay this close to its anchor. */
    private static final int XRAY_SHARED = XRAY_REACH - 300;
    /**
     * With the camera this close (horizontally) to the through-walls anchor, the object hangs at the camera's
     * height and every shape can share it: its points are pulled to at most a few hundred units from the camera.
     */
    private static final int XRAY_CAMERA = XRAY_REACH - 700;
    private float[] tx = new float[64], ty = new float[64], tz = new float[64];
    /**
     * Layers of model marks, each drawn over the one before where they overlap: clickboxes, hulls, outlines. One layer
     * for all three left their order to the renderer's sort, which drew an NPC's outline over its clickbox in one frame
     * and under it in the next.
     */
    static final int CLICKBOX_LAYER = 14, HULL_LAYER = 15, OUTLINE_LAYER = 16;

    @Inject
    SceneShapeRenderer(Client client, CarrierModels carriers) { this.client = client; this.carriers = carriers; }

    /**
     * Starts a frame; canvasPerPixel converts screen pixels to canvas units (1 / stretch scale).
     * Shapes are rebuilt every frame: one that is not appended is simply not drawn. With xrayAnchor set
     * (in the drawn zone nearest the camera), every shape is drawn through walls: each vertex moves along
     * its view ray towards the camera, keeping its screen position and its order relative to other shapes.
     */
    void begin(ModelShapes.Camera camera, float canvasPerPixel, LocalPoint xrayAnchor, int xrayLevel)
    {
        this.xray = xrayAnchor != null;
        this.xrayAnchor = xrayAnchor;
        this.xrayLevel = xrayLevel;
        this.camera = camera;
        pixel = canvasPerPixel;
        appended.clear();
        frame++;
        outlineNanos = 0;
        cuts = Collections.emptyList();
        if (cutCostCamera == null || cutCostCamera.jumpedTo(camera)) { cutCostCache.clear(); cutCostCamera = camera; }
        unavailable = false;
        carriers.nextFrame();
        for (Bucket b : buckets.values()) { b.vertices = 0; b.faces = 0; b.needVertices = 0; b.needFaces = 0; b.keys.clear(); }
        for (Stage s : stages.values()) { s.vertices = 0; s.faces = 0; s.count = 0; }
        if (xray)
        {
            // Renderers sort see-through models by the distance from their position to the camera, farthest
            // first: at the camera's height the shared object comes after everything else in its zone.
            float dx = camera.x - xrayAnchor.getX(), dy = camera.y - xrayAnchor.getY();
            xrayCameraNear = dx * dx + dy * dy <= (float) XRAY_CAMERA * XRAY_CAMERA;
            xrayHeight = xrayCameraNear ? Math.round(camera.z)
                : Terrain.heightOnLevel(client.getTopLevelWorldView(), xrayAnchor.getX(), xrayAnchor.getY(), xrayLevel);
        }
    }

    /** Draws a tile footprint; returns whether it is in the scene this frame. */
    boolean tile(Marker m)
    {
        WorldView wv = client.getTopLevelWorldView();
        if (unavailable || m.point.getWorldView() != wv.getId()) { return false; }
        if ((m.borderWidth <= 0 || m.color.getAlpha() == 0) && m.fill.getAlpha() == 0) { return culled(m.key); }
        layer = m.layer;
        LocalPoint at = m.point;
        int level = Terrain.level(wv, at.getSceneX(), at.getSceneY(), m.plane);
        int height = Terrain.heightOnLevel(wv, at.getX(), at.getY(), level);
        if (m.dot || m.offX != null) { return facing(m, at, level, height); }
        if (m.edge >= 0) { return line(m, at, level, height); }
        int w = m.width, h = m.height, n = 2 * (w + h);
        ensure(n);
        int x0 = at.getX() - w * 64, y0 = at.getY() - h * 64, k = 0;
        // Walk the perimeter counterclockwise, sampling height at every tile boundary.
        for (int i = 0; i < w; i++) { k = sample(wv, level, x0 + i * 128, y0, k); }
        for (int j = 0; j < h; j++) { k = sample(wv, level, x0 + w * 128, y0 + j * 128, k); }
        for (int i = w; i > 0; i--) { k = sample(wv, level, x0 + i * 128, y0 + h * 128, k); }
        for (int j = h; j > 0; j--) { k = sample(wv, level, x0, y0 + j * 128, k); }
        if (k < 0)
        {
            // Wholly behind the camera: RuneLite's 2D tile is nothing either, so the overlay need not try it every frame.
            camera.project(at.getX(), at.getY(), height, point);
            return point[2] < ModelShapes.NEAR - 64 * (w + h) - 1024 ? culled(m.key) : false;
        }
        // Off screen by its corners alone (a tile's border and mitres stay within a few widths of them): not built.
        if (beside(n, 4 * width(m.borderWidth) + 2)) { return culled(m.key); }
        boolean built = around(at, height, n, m.borderWidth);
        if (m.cornerDivisor <= 0) { return shape(m, at, level, built, m.fill); }
        if (!built || oversized()) { return false; }
        if (offscreen()) { return culled(m.key); }
        // Corners only: the fill covers the whole footprint, the border only its corners.
        if (m.fill.getAlpha() > 0) { draw(m.key, at, level, m.color, m.fill, false); }
        if (m.borderWidth > 0) { corners(m, at, w, h, level); }
        return true;
    }

    /** Per side of a tile (HdWorldMarkersConfig.Edge order: west, east, south, north), its two corners from the tile's south-west corner. */
    static final int[][] SIDES = {{0, 0, 0, 128}, {128, 0, 128, 128}, {0, 0, 128, 0}, {0, 128, 128, 128}};

    /** A line along one side of the tile, as wide as its border: a strip between the side's corners on the ground. */
    private boolean line(Marker m, LocalPoint at, int level, int height)
    {
        WorldView wv = client.getTopLevelWorldView();
        int[] side = SIDES[Math.min(m.edge, SIDES.length - 1)];
        int x0 = at.getX() - 64, y0 = at.getY() - 64;
        ensure(2);
        int k = sample(wv, level, x0 + side[0], y0 + side[1], 0);
        k = sample(wv, level, x0 + side[2], y0 + side[3], k);
        if (k < 0)
        {
            camera.project(at.getX(), at.getY(), height, point);
            return point[2] < ModelShapes.NEAR - 1024 ? culled(m.key) : false;
        }
        if (beside(2, 4 * width(m.borderWidth) + 2)) { return culled(m.key); }
        return shape(m, at, level, outline.buildStrip(px, py, pd, 2, width(m.borderWidth)), Marker.NO_FILL);
    }

    /**
     * The four corner lines of a footprint, each 1/divisor of its side along the
     * projected perimeter, as Corner Tile Indicators' renderPolygonCorners
     * does on screen.
     */
    private void corners(Marker m, LocalPoint at, int w, int h, int level)
    {
        // Perimeter indices of the four corners: south-west, south-east, north-east, north-west.
        int[] ends = {0, w, w + h, 2 * w + h};
        float[] sx = new float[3], sy = new float[3], sd = new float[3];
        for (int k = 0; k < 4; k++)
        {
            int corner = ends[k], next = ends[(k + 1) % 4], prev = ends[(k + 3) % 4];
            float t = 1f / m.cornerDivisor;
            sx[0] = lerp(px[corner], px[prev], t); sy[0] = lerp(py[corner], py[prev], t); sd[0] = lerp(pd[corner], pd[prev], t);
            sx[1] = px[corner]; sy[1] = py[corner]; sd[1] = pd[corner];
            sx[2] = lerp(px[corner], px[next], t); sy[2] = lerp(py[corner], py[next], t); sd[2] = lerp(pd[corner], pd[next], t);
            if (outline.buildStrip(sx, sy, sd, 3, width(m.borderWidth)))
            {
                draw(m.key, at, level, m.color, Marker.NO_FILL, true);
            }
        }
    }

    private static float lerp(float a, float b, float t) { return a + (b - a) * t; }

    /** A border width in canvas units: at least a hundredth, so a zero width still builds. */
    private float width(float borderWidth) { return Math.max(0.01f, borderWidth * pixel); }

    /** Builds the n points in px, py and pd around their centre at the given height; false when it lies too near. */
    private boolean around(LocalPoint at, int height, int n, float borderWidth)
    {
        camera.project(at.getX(), at.getY(), height, point);
        return point[2] >= PARTIAL_NEAR && outline.build(px, py, pd, n, point[0], point[1], point[2], width(borderWidth));
    }

    /** Draws the tile shape just built (not when it could not be, or is oversized); off screen it is culled. */
    private boolean shape(Marker m, LocalPoint at, int level, boolean built, Color fill)
    {
        if (!built || oversized()) { return false; }
        if (offscreen()) { return culled(m.key); }
        return draw(m.key, at, level, m.color, fill, m.borderWidth > 0);
    }

    /** Path Marker's dot style: an 8 pixel circle. */
    static final float[] DOT_X = new float[16], DOT_Y = new float[16];
    static { for (int i = 0; i < 16; i++) { DOT_X[i] = (float) Math.cos(i * Math.PI / 8) * 4; DOT_Y[i] = (float) Math.sin(i * Math.PI / 8) * 4; } }

    /** The dot around the tile's centre, its size in screen pixels. */
    /**
     * A shape standing towards the camera around where the marker's point projects: Path Marker's dot in pixels, or a
     * timer pie (Marker.offX) in local units, scaled by the camera at its depth.
     */
    private boolean facing(Marker m, LocalPoint at, int level, int height)
    {
        float[] ox = m.offX != null ? m.offX : DOT_X, oy = m.offX != null ? m.offY : DOT_Y;
        int n = ox.length;
        ensure(n);
        camera.project(at.getX(), at.getY(), height - m.lift, point);
        if (!(point[2] >= PARTIAL_NEAR)) { return false; }
        float scale = m.offX != null ? camera.scale / point[2] : pixel;
        for (int i = 0; i < n; i++) { px[i] = point[0] + ox[i] * scale; py[i] = point[1] + oy[i] * scale; pd[i] = point[2]; }
        return shape(m, at, level, outline.buildPolygon(px, py, pd, n, width(m.borderWidth), false), m.fill);
    }

    private int sample(WorldView wv, int level, int x, int y, int k)
    {
        if (k < 0) { return k; }
        // Corners on the far scene edge belong to the last tile (heightOnLevel clamps).
        camera.project(x, y, Terrain.heightOnLevel(wv, x, y, level), point);
        if (!(point[2] >= PARTIAL_NEAR)) { return -1; }
        px[k] = point[0]; py[k] = point[1]; pd[k] = point[2];
        return k + 1;
    }

    /** Draws a model's hull, clickbox or outline; returns whether it is in the scene this frame. */
    boolean model(ModelTarget t)
    {
        layer = t.outline ? OUTLINE_LAYER : t.clickbox ? CLICKBOX_LAYER : HULL_LAYER;
        LocalPoint location = t.location();
        if (unavailable || location == null || location.getWorldView() != client.getTopLevelWorldView().getId())
        { return false; }
        int height = t.height(client);
        if (t.npc == null && t.renderable == null) { return false; }
        Projection projected = projection(t);
        if (projected.frame != frame && !unchanged(t, projected, location, height))
        {
            Mesh<?> mesh = t.mesh();
            if (mesh == null) { return false; }
            project(t, mesh, projected, location, height);
        }
        projected.frame = frame;
        float depth = projected.depth;
        // Nothing of it projects (all at or behind the camera): RuneLite draws nothing of it either, so no 2D shape.
        // Off screen (not for clickboxes) it is handled by the scene route: do not repeat this work in the 2D fallback.
        if (Float.isNaN(depth) || projected.outside && !t.clickbox) { return culled(t.key); }
        int level = Terrain.level(client.getTopLevelWorldView(), location.getSceneX(), location.getSceneY(), t.plane());
        boolean asHull = false;
        if (t.outline && projected.loops == null)
        {
            // Over this frame's budget: the outline traced last, moved to where the model is now, rather than a hull border
            // for a frame (outlines flipped between the two in a crowd); a hull border only before the first trace. At
            // most a few frames old: past that it is traced anyway, or the farthest outlines would never be traced again.
            boolean over = outlineNanos > OUTLINE_BUDGET_NANOS;
            if (over && projected.traced != null && frame - projected.tracedFrame <= STALE_OUTLINE_FRAMES)
            {
                projected.loops = moved(projected.traced, projected.tracedCenterX, projected.tracedCenterY, projected.tracedWidth,
                    projected.tracedHeight, projected.centerX, projected.centerY, projected.width, projected.height2d);
            }
            else
            {
                asHull = over && projected.traced == null || !faces(t, projected);
                if (!asHull)
                {
                    long start = System.nanoTime();
                    projected.loops = projected.traced = Silhouette.trace(projected.x, projected.y, projected.a, projected.b,
                        projected.c, projected.faces, projected.hidden, silhouetteScratch);
                    projected.tracedFrame = frame;
                    projected.tracedCenterX = projected.centerX; projected.tracedCenterY = projected.centerY;
                    projected.tracedWidth = projected.width; projected.tracedHeight = projected.height2d;
                    outlineNanos += System.nanoTime() - start;
                }
            }
        }
        if (t.outline && !asHull || t.clickbox)
        {
            // A clickbox is RuneLite's, computed the same way from the float projection (FloatClickbox): RuneLite rounds
            // every face's rectangle to whole pixels, so its edge wobbled as the camera moved. Kept for static objects
            // while the camera stands still. Only when it cannot be made (off screen, behind the camera) RuneLite's own
            // is drawn.
            List<float[]> polygons = t.outline ? projected.loops : twoModels(t.object) ? null : clickbox(t, projected);
            if (polygons == null)
            {
                java.awt.Shape shape = t.shape();
                polygons = shape == null ? Collections.emptyList() : polygons(shape);
            }
            // A union of rectangles can enclose holes, wound the other way round; RuneLite leaves them unfilled
            // (even-odd), so they get their border only instead of being filled again over the rest. An outline is
            // all border, outside the silhouette.
            double outer = polygons.isEmpty() ? 0 : Math.signum(FloatClickbox.area(largest(polygons)));
            boolean any = false;
            for (float[] full : polygons)
            {
                boolean hole = polygons.size() > 1 && Math.signum(FloatClickbox.area(full)) != outer;
                int h = load(fit(full), depth);
                if (outline.buildPolygon(px, py, pd, h, width(t.borderWidth), t.outline) && !offscreen())
                {
                    draw(t.key, location, level, t.color, hole ? Marker.NO_FILL : t.fill, t.borderWidth > 0);
                    any = true;
                }
            }
            // Close to the camera the faces left out can leave nothing to trace: then no shape this frame rather than
            // RuneLite's 2D one, which flickered in and out as the camera moved.
            return any || projected.partial && culled(t.key);
        }
        if (projected.hull == null) { projected.hull = ModelShapes.convexHull(projected.x, projected.y, projected.n); }
        if (projected.hull == null) { return projected.partial && culled(t.key); }
        int h = load(projected.hull, depth);
        float cx = 0, cy = 0;
        for (int i = 0; i < h; i++) { cx += px[i]; cy += py[i]; }
        // Just in front of the nearest vertex, so the shape covers the model like the 2D overlay does.
        if (!outline.build(px, py, pd, h, cx / h, cy / h, depth, width(t.borderWidth))) { return false; }
        if (offscreen()) { return culled(t.key); }
        return draw(t.key, location, level, t.color, asHull ? Marker.NO_FILL : t.fill, t.borderWidth > 0);
    }

    /**
     * Loops traced for one projection, moved and scaled from its bounds (centre and size) to another's: where a model
     * that walked, or that the camera turned or zoomed on, is now.
     */
    static List<float[]> moved(List<float[]> loops, float fromX, float fromY, float fromWidth, float fromHeight,
        float toX, float toY, float toWidth, float toHeight)
    {
        float sx = fromWidth > 0 && toWidth > 0 ? toWidth / fromWidth : 1, sy = fromHeight > 0 && toHeight > 0 ? toHeight / fromHeight : 1;
        List<float[]> out = new ArrayList<>(loops.size());
        for (float[] loop : loops)
        {
            float[] m = new float[loop.length];
            for (int i = 0; i < loop.length; i += 2)
            {
                m[i] = toX + (loop[i] - fromX) * sx;
                m[i + 1] = toY + (loop[i + 1] - fromY) * sy;
            }
            out.add(m);
        }
        return out;
    }

    /** Copies a polygon {x0, y0, ...} into px, py and pd at the given depth; returns its number of points. */
    private int load(float[] polygon, float depth)
    {
        int h = polygon.length / 2;
        ensure(h);
        for (int i = 0; i < h; i++) { px[i] = polygon[i * 2]; py[i] = polygon[i * 2 + 1]; pd[i] = depth; }
        return h;
    }

    /**
     * The projection of a target's model part, shared by its styles: per NPC, or per object and renderable. Not per
     * renderable alone: the client gives identical objects one static model, and every copy then got the first one's
     * projection, drawn in its place.
     */
    private Projection projection(ModelTarget t)
    {
        Object owner = t.npc != null ? t.npc : t.object;
        Projection first = projections.get(owner), p = first;
        while (p != null && p.part != t.renderable) { p = p.next; }
        if (p == null)
        {
            p = new Projection();
            p.part = t.renderable;
            p.next = first;
            projections.put(owner, p);
        }
        return p;
    }

    /** The projections of a chain that were used this frame, still chained, or null when none was. */
    private Projection usedThisFrame(Projection p)
    {
        if (p == null) { return null; }
        Projection next = usedThisFrame(p.next);
        if (p.frame != frame) { return next; }
        p.next = next;
        return p;
    }

    /**
     * A static object model (not an actor, not animated) whose camera, place and rotation are
     * those of its last projection: its projection and silhouette still hold.
     */
    private boolean unchanged(ModelTarget t, Projection p, LocalPoint location, int height)
    {
        return t.npc == null && t.renderable instanceof Mesh
            && p.camera != null && p.camera.same(camera) && p.localX == location.getX() && p.localY == location.getY()
            && p.height == height && p.orientation == t.orientation() && p.frame == frame - 1;
    }

    /**
     * Points nearer the camera than this (about one tile) are left out of hulls, outlines and clickboxes, and a tile,
     * path or line with such a point is not drawn: they project to huge canvas positions, which drew a screen-wide
     * shape for a frame when the camera passed an object or came in close at login.
     */
    static final float PARTIAL_NEAR = 150;

    private void project(ModelTarget t, Mesh<?> mesh, Projection p, LocalPoint location, int height)
    {
        int n = mesh.getVerticesCount();
        // The last projection's points and shapes, to keep when this one comes out the same: an NPC standing still,
        // or its animation between two of its frames, while the camera does not move. Its clickbox and outline were
        // made again every frame, the largest part of the scene's time.
        int lastN = p.n, lastFaces = p.faces, lastViewport = p.viewport;
        long lastHidden = p.hiddenSum;
        List<float[]> lastClickbox = p.clickbox, lastLoops = p.loops;
        float[] lastHull = p.hull, swapX = p.lastX, swapY = p.lastY;
        p.lastX = p.x; p.lastY = p.y;
        p.x = swapX; p.y = swapY;
        if (p.x.length < n) { p.x = new float[n]; p.y = new float[n]; }
        p.n = n;
        p.hull = null;
        p.loops = null;
        p.clickbox = null;
        // Every projection gets the clickbox bounds from the mesh at hand (one pass over the vertices, eight projections),
        // whichever style made it: fetching the mesh again for a clickbox rebuilt an NPC's animated model a second time.
        p.boundsHull = boundsHull(mesh, n, location.getX(), location.getY(), height, t.orientation());
        p.facesFrame = 0;
        p.faces = 0;
        p.camera = camera; p.localX = location.getX(); p.localY = location.getY(); p.height = height; p.orientation = t.orientation();
        p.boundingBox = mesh instanceof Model && ((Model) mesh).useBoundingBox();
        // A model partly at or behind the camera keeps its other vertices, as RuneLite's clickbox and hull skip such
        // faces.
        p.depth = ModelShapes.projectModel(camera, mesh.getVerticesX(), mesh.getVerticesY(), mesh.getVerticesZ(),
            n, location.getX(), location.getY(), height, t.orientation(), p.x, p.y);
        float minX = Float.POSITIVE_INFINITY, minY = minX, maxX = Float.NEGATIVE_INFINITY, maxY = maxX;
        p.partial = false;
        for (int i = 0; i < n; i++)
        {
            if (Float.isNaN(p.x[i])) { p.partial = true; continue; }
            minX = Math.min(minX, p.x[i]); maxX = Math.max(maxX, p.x[i]);
            minY = Math.min(minY, p.y[i]); maxY = Math.max(maxY, p.y[i]);
        }
        p.centerX = (minX + maxX) / 2; p.centerY = (minY + maxY) / 2; p.width = maxX - minX; p.height2d = maxY - minY;
        // Conservative margin includes the widest supported border and its mitres.
        float margin = 64 * pixel;
        int vx = client.getViewportXOffset(), vy = client.getViewportYOffset();
        int vw = client.getViewportWidth(), vh = client.getViewportHeight();
        p.viewport = Objects.hash(vx, vy, vw, vh);
        p.outside = maxX + margin < vx || maxY + margin < vy
            || minX - margin > vx + vw || minY - margin > vy + vh;
        // Actor models live in a shared client buffer: copy their faces now, into reused arrays, in case
        // another style of this NPC needs them after another actor's getModel(). Objects only for outlines.
        if (t.outline || t.npc != null) { copyFaces(mesh, p); }
        if (n == lastN && p.faces == lastFaces && p.faces > 0 && p.hiddenSum == lastHidden && p.viewport == lastViewport
            && Arrays.equals(p.x, 0, n, p.lastX, 0, n) && Arrays.equals(p.y, 0, n, p.lastY, 0, n))
        {
            p.clickbox = lastClickbox; p.loops = lastLoops; p.hull = lastHull;
        }
    }

    /**
     * Face topology for outlines, copied once per projection. NPCs copy it when projected; a static
     * object's hull projection gets it here when its outline follows.
     */
    private boolean faces(ModelTarget t, Projection p)
    {
        // Copied faces stay valid until the next projection; one copy attempt per frame otherwise.
        if (p.faces > 0) { return true; }
        if (p.facesFrame == frame) { return false; }
        Mesh<?> mesh = t.mesh();
        if (mesh == null || mesh.getVerticesCount() != p.n) { return false; }
        copyFaces(mesh, p);
        return p.faces > 0;
    }

    private void copyFaces(Mesh<?> mesh, Projection p)
    {
        p.facesFrame = frame;
        p.faces = 0;
        int faces = mesh.getFaceCount();
        if (p.outside || Float.isNaN(p.depth) || faces <= 0) { return; }
        if (p.a.length < faces) { p.a = new int[faces]; p.b = new int[faces]; p.c = new int[faces]; }
        System.arraycopy(mesh.getFaceIndices1(), 0, p.a, 0, faces);
        System.arraycopy(mesh.getFaceIndices2(), 0, p.b, 0, faces);
        System.arraycopy(mesh.getFaceIndices3(), 0, p.c, 0, faces);
        for (int f = 0; f < faces; f++)
        {
            // Topology that does not fit the projected vertices is not traced.
            if (p.a[f] < 0 || p.b[f] < 0 || p.c[f] < 0 || p.a[f] >= p.n || p.b[f] >= p.n || p.c[f] >= p.n) { return; }
        }
        int[] colors = mesh instanceof Model ? ((Model) mesh).getFaceColors3() : null;
        if (colors == null) { p.hidden = null; }
        else
        {
            if (p.hidden == null || p.hidden.length < faces) { p.hidden = new boolean[faces]; }
            for (int f = 0; f < faces; f++) { p.hidden[f] = f < colors.length && colors[f] == -2; }
        }
        long hiddenSum = 0;
        if (p.hidden != null) { for (int f = 0; f < faces; f++) { if (p.hidden[f]) { hiddenSum += f * 31L + 1; } } }
        p.hiddenSum = hiddenSum;
        p.faces = faces;
    }

    /** Whether every point of the current shape lies within reach of the given anchor. */
    private boolean within(float x, float y, float height, float reach)
    {
        for (int i = 0; i < outline.vertices; i++)
        {
            float dx = tx[i] - x, dy = ty[i] - y, dz = tz[i] - height;
            if (dx * dx + dy * dy + dz * dz > reach * reach) { return false; }
        }
        return true;
    }

    /**
     * Appends the current outline to the stage of the anchor's tile, in world coordinates. The stages are split
     * over scene objects in rank order and written once per object in end().
     */
    private boolean draw(String key, LocalPoint anchor, int level, Color border, Color fill, boolean hasBorder)
    {
        // Through walls applies to every shape, tiles as well as hulls, clickboxes and outlines: all of them
        // then sit at the same place in front of the camera, so lighting renderers (117 HD: shadows, fog,
        // lights) shade them all alike.
        // World points of the shape: on the ground for through walls (moved to the camera at draw time),
        // else just above it towards the camera. Later layers slightly nearer, so shapes never z-fight.
        place(xray, false);
        WorldView top = client.getTopLevelWorldView();
        boolean shared = xray && (xrayCameraNear || within(xrayAnchor.getX(), xrayAnchor.getY(), xrayHeight, XRAY_SHARED));
        if (shared)
        {
            // One object in the drawn zone nearest the camera: a tile hidden behind a wall may not be drawn
            // by the client. Shapes too far from it for one model get a through-walls object on their own tile.
            anchor = xrayAnchor;
            level = xrayLevel;
        }
        // Shapes beyond the loaded area hang on the nearest edge tile; the client only places objects inside it.
        int tileX = Math.max(0, Math.min(top.getSizeX() - 1, anchor.getX() >> 7));
        int tileY = Math.max(0, Math.min(top.getSizeY() - 1, anchor.getY() >> 7));
        // Floating marks under 117 HD stay under its shadow threshold.
        int cap = xray ? floatingAlphaCap : 255;
        // The cap applies to the colour as a whole, before it is split into layers that blend to it.
        layers(border, Math.min(cap, hasBorder ? border.getAlpha() : 0), borderLayers);
        layers(fill, Math.min(cap, fill.getAlpha()), fillLayers);
        int borderHsl = borderLayers[0], borderAlpha = borderLayers[1], borderWhite = borderLayers[2];
        int fillHsl = fillLayers[0], fillAlpha = fillLayers[1], fillWhite = fillLayers[2];
        // The white layer: a second copy of the outline, just nearer the camera so it is drawn over the colour.
        boolean white = borderWhite > 0 || fillWhite > 0;
        // A single shape too large for any scene object is left out; a bucket past the carrier limits fails the whole frame.
        int addVertices = outline.vertices * (white ? 2 : 1), addFaces = outline.faces * (white ? 2 : 1);
        if (!carriers.fits(addVertices, addFaces, 2)) { return false; }
        if (!shared && !within(tileX * 128 + 64, tileY * 128 + 64, Terrain.heightOnLevel(top, tileX * 128 + 64, tileY * 128 + 64, level),
                xray ? XRAY_REACH - 200 : MAX_RADIUS - 300)) { return false; }
        // Through-walls shapes get their own buckets: they are moved to the camera, others are not.
        long base = ((long) level << 32) | ((long) tileX << 16) | tileY | (xray ? 1L << 40 : 0) | (shared ? 1L << 39 : 0);
        Stage st = stages.get(base);
        if (st == null) { st = new Stage(tileX, tileY, level, anchor.getWorldView()); stages.put(base, st); }
        st.ensure(st.vertices + addVertices, st.faces + addFaces);
        st.xray = xray;
        st.shared = shared;
        st.begin(layer, key);
        shapeCut = xray ? cutCosts(key) : null;
        append(st, layer, borderHsl, borderAlpha, fillHsl, fillAlpha);
        if (white)
        {
            if (!xray) { place(false, true); }
            append(st, layer + 0.5f, FlatModel.WHITE, borderWhite, FlatModel.WHITE, fillWhite);
        }
        st.end();
        appended.add(key);
        return true;
    }

    /** FlatModel.layers per colour, alpha and lightness cap: a colour's HSL takes powers, for every shape every frame. */
    private final Map<Long, int[]> layerCache = new HashMap<>();

    private void layers(Color color, int alpha, int[] out)
    {
        long key = (long) color.getRGB() << 9 | alpha << 1 | (hdLightnessCap ? 1 : 0);
        int[] known = layerCache.get(key);
        if (known == null)
        {
            if (layerCache.size() > 1024) { layerCache.clear(); }
            known = new int[3];
            FlatModel.layers(color, alpha, hdLightnessCap, known);
            layerCache.put(key, known);
        }
        System.arraycopy(known, 0, out, 0, 3);
    }

    /** The camera the client draws with now; the last one again while it has not changed (getModel asks per object). */
    private volatile ModelShapes.Camera lastDrawCamera;

    private ModelShapes.Camera drawCamera()
    {
        ModelShapes.Camera last = lastDrawCamera, now = ModelShapes.Camera.of(client, last);
        if (now != last) { lastDrawCamera = now; }
        return now;
    }

    /**
     * World points (tx, ty, tz) of the outline: on the ground for through walls (moved to the camera at draw time),
     * else just above it towards the camera, later layers slightly nearer so shapes never z-fight. The white layer
     * of a light colour is always a little nearer than its colour layer, also where the layer offset bottoms out.
     */
    private void place(boolean throughWalls, boolean white)
    {
        if (tx.length < outline.vertices) { tx = new float[outline.vertices * 2]; ty = new float[outline.vertices * 2]; tz = new float[outline.vertices * 2]; }
        float layerBias = layer * 0.001f;
        for (int i = 0; i < outline.vertices; i++)
        {
            float d = outline.depth[i];
            float at = throughWalls ? d : d - Math.max(4, d * 0.01f) - Math.max(1, d * layerBias) - (white ? Math.max(0.5f, d * 0.0005f) : 0);
            camera.unproject(outline.x[i], outline.y[i], at, point);
            tx[i] = point[0]; ty[i] = point[1]; tz[i] = point[2];
        }
    }

    /** Adds the outline's vertices (tx, ty, tz) and its visible faces to the stage. */
    private void append(Stage b, float vertexLayer, int borderHsl, int borderAlpha, int fillHsl, int fillAlpha)
    {
        int first = b.vertices;
        for (int i = 0; i < outline.vertices; i++)
        {
            b.layer[first + i] = vertexLayer;
            b.wx[first + i] = tx[i]; b.wy[first + i] = ty[i]; b.wz[first + i] = tz[i];
        }
        b.vertices += outline.vertices;
        for (int f = 0; f < outline.faces; f++)
        {
            boolean isBorder = f < outline.borderFaces;
            int alpha = isBorder ? borderAlpha : fillAlpha;
            if (alpha <= 0) { continue; }
            int k = b.faces++;
            b.fa[k] = first + outline.a[f]; b.fb[k] = first + outline.b[f]; b.fc[k] = first + outline.c[f];
            b.color[k] = isBorder ? borderHsl : fillHsl;
            b.alpha[k] = alpha;
            // What the player's cut makes of the face, with half as much again to grow as the camera moves.
            int points = shapeCut == null ? 0 : shapeCut[2 * f + 2] - shapeCut[2 * f];
            int pieces = shapeCut == null ? 1 : shapeCut[2 * f + 3] - shapeCut[2 * f + 1];
            b.cutVertices[k] = points + points / 2;
            b.cutFaces[k] = pieces <= 1 ? 1 : pieces + pieces / 2;
        }
    }

    /**
     * The actors' cuts of the outline as seen now, per face (ScreenOutline.costs): what the objects holding the shape
     * need room for. Null when no silhouette comes near the shape.
     */
    private int[] cutCosts(String key)
    {
        if (cuts.isEmpty()) { return null; }
        // Measured this frame for a quarter of the shapes, the rest keep their last measure while its face count holds.
        CutCosts cached = cutCostCache.get(key);
        int length = 2 * outline.faces + 2;
        boolean due = cached == null || frame - cached.frame >= CUT_COSTS_FRAMES || cached.costs != null && cached.costs.length != length;
        if (!due && (frame + key.hashCode()) % CUT_COSTS_FRAMES != 0) { return cached.costs; }
        if (cached == null) { cached = new CutCosts(); cutCostCache.put(key, cached); }
        int[] costs = measureCutCosts();
        cached.frame = frame;
        if (costs == null) { cached.costs = null; }
        else
        {
            if (cached.costs == null || cached.costs.length != length) { cached.costs = new int[length]; }
            System.arraycopy(costs, 0, cached.costs, 0, length);
        }
        return cached.costs;
    }

    private int[] measureCutCosts()
    {
        boolean loaded = false;
        for (PlayerSilhouette s : cuts)
        {
            PlayerCut around = s.estimate(camera);
            if (around == null || around.maxX < outline.minX || around.minX > outline.maxX || around.maxY < outline.minY
                || around.minY > outline.maxY) { continue; }
            if (!loaded) { sizer.load(outline.x, outline.y, outline.depth, outline.vertices, outline.a, outline.b, outline.c, outline.faces); loaded = true; }
            sizer.cutOut(around, Integer.MAX_VALUE, Integer.MAX_VALUE);
        }
        return loaded ? sizer.costs(outline.vertices, outline.faces) : null;
    }

    /**
     * Walls and decorations with a second model: RuneLite's clickbox covers both, the float clickbox only the first,
     * so RuneLite's own is drawn for them.
     */
    private static boolean twoModels(TileObject object)
    {
        return object instanceof WallObject && ((WallObject) object).getRenderable2() != null
            || object instanceof DecorativeObject && ((DecorativeObject) object).getRenderable2() != null;
    }

    /**
     * The clickbox polygons from the projection: the bounding box hull for bounding-box models, else RuneLite's union of
     * face rectangles clipped to it (FloatClickbox). Null without face topology.
     */
    private List<float[]> clickbox(ModelTarget t, Projection p)
    {
        if (p.clickbox != null) { return p.clickbox; }
        if (p.boundingBox) { return p.boundsHull == null ? null : (p.clickbox = Collections.singletonList(p.boundsHull)); }
        if (!faces(t, p)) { return null; }
        int vx = client.getViewportXOffset();
        // As calculate2DBounds, which takes the viewport's x offset for its top edge too.
        return p.clickbox = FloatClickbox.of(p.x, p.y, p.a, p.b, p.c, p.faces, p.hidden, p.boundsHull,
            vx, vx, vx + client.getViewportWidth(), vx + client.getViewportHeight());
    }

    /**
     * The convex hull {x0, y0, ...} of the model's bounding box on the canvas (Perspective.calculateAABB), or null:
     * Model.getAABB as RuneLite takes it, or for unlit ModelData (no getAABB) the box of its vertices.
     */
    private float[] boundsHull(Mesh<?> mesh, int n, int localX, int localY, int height, int orientation)
    {
        if (n <= 0) { return null; }
        float x1, x2, y1, y2, z1, z2;
        AABB box = mesh instanceof Model ? ((Model) mesh).getAABB(orientation) : null;
        if (box != null)
        {
            // RuneLite's own box (Perspective.calculateAABB): it can be larger than the vertices, and a bounding-box
            // model's clickbox is exactly this box.
            x1 = box.getCenterX() - box.getExtremeX(); x2 = box.getCenterX() + box.getExtremeX();
            y1 = box.getCenterY() - box.getExtremeY(); y2 = box.getCenterY() + box.getExtremeY();
            z1 = box.getCenterZ() - box.getExtremeZ(); z2 = box.getCenterZ() + box.getExtremeZ();
        }
        else
        {
            // Unlit ModelData has no getAABB: the box of its vertices turned as ModelShapes.projectModel turns them.
            float[] vx = mesh.getVerticesX(), vy = mesh.getVerticesY(), vz = mesh.getVerticesZ();
            double angle = (orientation & 2047) * Math.PI / 1024;
            float sin = (float) Math.sin(angle), cos = (float) Math.cos(angle);
            x1 = Float.MAX_VALUE; x2 = -Float.MAX_VALUE; y1 = x1; y2 = x2; z1 = x1; z2 = x2;
            for (int i = 0; i < n; i++)
            {
                float rx = vz[i] * sin + vx[i] * cos, rz = vz[i] * cos - vx[i] * sin;
                x1 = Math.min(x1, rx); x2 = Math.max(x2, rx);
                y1 = Math.min(y1, vy[i]); y2 = Math.max(y2, vy[i]);
                z1 = Math.min(z1, rz); z2 = Math.max(z2, rz);
            }
        }
        float[] bx = {x1, x2, x1, x2, x1, x2, x1, x2}, by = {y1, y1, y1, y1, y2, y2, y2, y2}, bz = {z1, z1, z2, z2, z1, z1, z2, z2};
        float[] cx = new float[8], cy = new float[8];
        // Corners at or behind the camera are left out, as the model's own vertices.
        if (Float.isNaN(ModelShapes.projectModel(camera, bx, by, bz, 8, localX, localY, height, 0, cx, cy)))
        { return null; }
        return ModelShapes.convexHull(cx, cy, 8);
    }

    /** Points a drawn polygon keeps at most: its border and fill then always fit one scene object (see fit). */
    static final int MAX_POINTS = 256;

    /**
     * The polygon with at most MAX_POINTS points: simplified (Douglas-Peucker) with the smallest tolerance from half a
     * pixel up, doubling, that gets there. Close to the camera a clickbox or outline is large on screen and has
     * thousands of points; its border and fill then outgrew a scene object, the mark was left out and RuneLite's own
     * 2D shape was drawn instead. At that size a pixel or two is not visible. Unchanged when small enough.
     */
    static float[] fit(float[] p)
    {
        float[] out = p;
        for (double tolerance = 0.5; out.length / 2 > MAX_POINTS && tolerance <= 128; tolerance *= 2) { out = Silhouette.simplify(p, tolerance); }
        return out;
    }

    private static float[] largest(List<float[]> polygons)
    {
        float[] best = polygons.get(0);
        for (float[] p : polygons) { if (Math.abs(FloatClickbox.area(p)) > Math.abs(FloatClickbox.area(best))) { best = p; } }
        return best;
    }

    /** The closed polygons of a canvas shape, as {x0, y0, x1, y1, ...}, without a repeated closing point. */
    static java.util.List<float[]> polygons(java.awt.Shape shape)
    {
        java.util.List<float[]> result = new ArrayList<>();
        float[] coords = new float[6];
        float[] current = new float[64];
        int size = 0;
        for (java.awt.geom.PathIterator it = shape.getPathIterator(null, 0.5); !it.isDone(); it.next())
        {
            int type = it.currentSegment(coords);
            if (type == java.awt.geom.PathIterator.SEG_MOVETO)
            {
                if (size >= 6) { result.add(Arrays.copyOf(current, size)); }
                size = 0;
            }
            if (type == java.awt.geom.PathIterator.SEG_MOVETO || type == java.awt.geom.PathIterator.SEG_LINETO)
            {
                if (size >= 2 && current[size - 2] == coords[0] && current[size - 1] == coords[1]) { continue; }
                if (size + 2 > current.length) { current = Arrays.copyOf(current, current.length * 2); }
                current[size++] = coords[0];
                current[size++] = coords[1];
            }
            if (type == java.awt.geom.PathIterator.SEG_CLOSE)
            {
                if (size >= 4 && current[0] == current[size - 2] && current[1] == current[size - 1]) { size -= 2; }
                if (size >= 6) { result.add(Arrays.copyOf(current, size)); }
                size = 0;
            }
        }
        if (size >= 6) { result.add(Arrays.copyOf(current, size)); }
        result.replaceAll(FloatClickbox::despur);
        result.removeIf(Objects::isNull);
        return result;
    }

    /** Whether the first n points in px and py lie this far (canvas units) or farther outside the viewport. */
    private boolean beside(int n, float margin)
    {
        float minX = Float.MAX_VALUE, minY = Float.MAX_VALUE, maxX = -Float.MAX_VALUE, maxY = -Float.MAX_VALUE;
        for (int i = 0; i < n; i++) { minX = Math.min(minX, px[i]); maxX = Math.max(maxX, px[i]); minY = Math.min(minY, py[i]); maxY = Math.max(maxY, py[i]); }
        int vx = client.getViewportXOffset(), vy = client.getViewportYOffset();
        return maxX + margin < vx || maxY + margin < vy || minX - margin > vx + client.getViewportWidth() || minY - margin > vy + client.getViewportHeight();
    }

    private boolean offscreen()
    {
        int vx = client.getViewportXOffset(), vy = client.getViewportYOffset();
        return outline.maxX < vx || outline.maxY < vy
            || outline.minX > vx + client.getViewportWidth() || outline.minY > vy + client.getViewportHeight();
    }

    /**
     * A tile, path or line shape larger than three viewports: none is, unless a point lies right at the camera (a
     * screen-wide square flashed at login). Such a shape is not drawn. Hulls and clickboxes of a building close by can
     * be that large, so they are not checked.
     */
    private boolean oversized()
    {
        return outline.maxX - outline.minX > 3 * client.getViewportWidth() || outline.maxY - outline.minY > 3 * client.getViewportHeight();
    }

    private void ensure(int n)
    {
        if (px.length < n) { px = new float[n * 2]; py = new float[n * 2]; pd = new float[n * 2]; }
    }

    private boolean culled(String key)
    {
        appended.add(key);
        return false;
    }

    /** Ends a frame: writes one scene object per tile. Returns false if no carrier model could be made. */
    boolean end()
    {
        for (Map.Entry<Long, Stage> e : stages.entrySet()) { split(e.getKey(), e.getValue()); }
        stages.values().removeIf(st -> st.count == 0);
        Iterator<Map.Entry<Long, Bucket>> it = buckets.entrySet().iterator();
        while (it.hasNext())
        {
            Bucket b = it.next().getValue();
            if (unavailable || b.faces == 0)
            {
                if (unavailable) { b.hide(); } else { retire(b); }
                it.remove();
            }
        }
        // Projections of models not drawn this frame are dropped, and cut costs of shapes gone for a while.
        if (frame % 64 == 0) { cutCostCache.values().removeIf(c -> frame - c.frame > 64); }
        projections.replaceAll((owner, p) -> usedThisFrame(p));
        projections.values().removeIf(Objects::isNull);
        // Reclaim vacated tiles before allocating models for newly occupied tiles. An object that cannot be made leaves only
        // its own marks to their 2D fallback.
        int written = 0, lost = 0;
        for (Iterator<Bucket> made = buckets.values().iterator(); made.hasNext(); )
        {
            Bucket b = made.next();
            if (write(b)) { written++; continue; }
            appended.removeAll(b.keys);
            retire(b);
            made.remove();
            lost++;
        }
        // None at all (the models are not loaded yet after logging in): the scene is unavailable this frame.
        if (lost > 0 && written == 0) { unavailable = true; }
        if (unavailable) { clear(); }
        return !unavailable;
    }

    /**
     * Moves a stage's shapes into its buckets, lowest rank first and in drawn order within a rank, so the faces of
     * every object, and the objects of the key one after another, run from the bottom rank to the top one. A full
     * bucket continues in the next object on the same tile, so no model exceeds the renderer's limits.
     */
    private void split(long base, Stage st)
    {
        if (st.count == 0) { return; }
        int[] order = st.byRank();
        int part = 0;
        Bucket b = part(base, 0, st);
        for (int k = 0; k < st.count; k++)
        {
            int s = order[k] * Stage.FIELDS;
            int firstVertex = st.shapes[s + 1], nv = st.shapes[s + 2], firstFace = st.shapes[s + 3], nf = st.shapes[s + 4];
            // Filled to the largest carrier: a second object at the same place is ordered by its anchor alone. Through
            // walls with room for the player's cut: what it makes of the shape as seen now, and more as the camera moves.
            int room = st.xray && !cuts.isEmpty() ? CUT_ROOM : 0, needVertices = nv, needFaces = 0;
            for (int f = firstFace; f < firstFace + nf; f++) { needVertices += st.cutVertices[f]; needFaces += st.cutFaces[f]; }
            if (b.faces > 0 && !carriers.fits(b.needVertices + needVertices + room, b.needFaces + needFaces + room, 1)) { b = part(base, ++part, st); }
            String key = st.keys[order[k]];
            b.keys.add(key);
            if (!carriers.fits(needVertices + room, needFaces + room, 1))
            {
                // Larger than any carrier: face by face, with own vertices.
                for (int f = firstFace; f < firstFace + nf; f++)
                {
                    int fv = 3 + st.cutVertices[f], ff = st.cutFaces[f];
                    if (b.faces > 0 && !carriers.fits(b.needVertices + fv + room, b.needFaces + ff + room, 1)) { b = part(base, ++part, st); b.keys.add(key); }
                    b.ensure(b.vertices + 3, b.faces + 1);
                    int to = b.faces++;
                    b.fa[to] = copy(st, st.fa[f], b); b.fb[to] = copy(st, st.fb[f], b); b.fc[to] = copy(st, st.fc[f], b);
                    b.color[to] = st.color[f]; b.alpha[to] = st.alpha[f];
                    b.needVertices += fv;
                    b.needFaces += ff;
                }
                continue;
            }
            b.needVertices += needVertices;
            b.needFaces += needFaces;
            b.ensure(b.vertices + nv, b.faces + nf);
            int shift = b.vertices - firstVertex;
            System.arraycopy(st.wx, firstVertex, b.wx, b.vertices, nv); System.arraycopy(st.wy, firstVertex, b.wy, b.vertices, nv);
            System.arraycopy(st.wz, firstVertex, b.wz, b.vertices, nv); System.arraycopy(st.layer, firstVertex, b.layer, b.vertices, nv);
            for (int f = firstFace; f < firstFace + nf; f++)
            {
                int to = b.faces++;
                b.fa[to] = st.fa[f] + shift; b.fb[to] = st.fb[f] + shift; b.fc[to] = st.fc[f] + shift;
                b.color[to] = st.color[f]; b.alpha[to] = st.alpha[f];
            }
            b.vertices += nv;
        }
        for (int p = 0; p <= part; p++) { buckets.get(base | ((long) p << 41)).partsAfter = part - p; }
    }

    /** Copies vertex v of the stage to the end of bucket b (which has room); returns its index there. */
    private static int copy(Stage st, int v, Bucket b)
    {
        int i = b.vertices++;
        b.wx[i] = st.wx[v]; b.wy[i] = st.wy[v]; b.wz[i] = st.wz[v]; b.layer[i] = st.layer[v];
        return i;
    }

    private Bucket part(long base, int part, Stage st)
    {
        long id = base | ((long) part << 41);
        Bucket b = buckets.get(id);
        if (b == null) { b = new Bucket(st.tileX, st.tileY, st.level, st.worldView); buckets.put(id, b); }
        b.xray = st.xray;
        b.shared = st.shared;
        return b;
    }

    private boolean write(Bucket b)
    {
        int anchorX = b.tileX * 128 + 64, anchorY = b.tileY * 128 + 64, anchorZ;
        if (b.shared)
        {
            anchorX = Math.max(b.tileX * 128, Math.min(b.tileX * 128 + 127, xrayAnchor.getX()));
            anchorY = Math.max(b.tileY * 128, Math.min(b.tileY * 128 + 127, xrayAnchor.getY()));
            anchorZ = xrayHeight;
        }
        else
        {
            float z = 0;
            for (int i = 0; i < b.vertices; i++) { z += b.wz[i]; }
            anchorZ = Math.round(z / b.vertices);
        }
        // Below the objects with higher ranks at the same place (the camera is above): farther, so drawn before them.
        anchorZ += b.partsAfter * PART_STEP;
        // Through walls: the geometry is pulled towards the camera, at most XRAY_REACH from the anchor.
        float extent = b.xray ? XRAY_REACH + 16 : 0;
        for (int i = 0; i < b.vertices && !b.xray; i++)
        {
            float dx = b.wx[i] - anchorX, dy = b.wy[i] - anchorY, dz = b.wz[i] - anchorZ;
            extent = Math.max(extent, Math.max((float) Math.sqrt((double) dx * dx + (double) dy * dy), Math.abs(dz)));
        }
        // Through walls, room for the player's silhouette cut out (see Bucket.pullToCamera) as split measured it; never more
        // than a carrier holds (one face larger than that stays whole), or making the object fails and with it the frame.
        int vertices = b.vertices, faces = b.faces;
        if (b.xray && !cuts.isEmpty() && carriers.fits(b.needVertices + CUT_ROOM, b.needFaces + CUT_ROOM, 1))
        {
            vertices = b.needVertices + CUT_ROOM;
            faces = b.needFaces + CUT_ROOM;
        }
        if (b.model == null || b.model.getVerticesCount() < vertices || b.model.getFaceCount() < faces || extent > b.radius)
        {
            // The model it had goes back to the spares for smaller objects.
            retire(b);
            // The smallest spare with room to grow, so the next frame's slightly larger shape still fits and a small
            // object does not take a large model, whose unused capacity is walked every frame.
            float wantRadius = b.xray ? extent : Math.min(MAX_RADIUS, extent * 1.25f);
            int wantVertices = (int) Math.ceil(vertices * 1.25f), wantFaces = (int) Math.ceil(faces * 1.25f);
            Spare spare = spare(wantRadius, wantVertices, wantFaces);
            // Filled close to the largest carrier (see split), no model has room to grow: one that fits will do.
            if (spare == null) { spare = spare(wantRadius, vertices, faces); }
            if (spare != null)
            {
                spareCarriers.remove(spare);
                b.adopt(spare);
            }
            else
            {
                int radius = b.xray ? MAX_RADIUS : Math.min(MAX_RADIUS, Math.max(MIN_RADIUS, (int) Math.ceil(extent * 1.5f)));
                // Twice the room where that fits a carrier; an object filled past that (see split) gets what it holds.
                boolean roomy = carriers.fits(vertices, faces, 2);
                Model created = carriers.create(Math.max(MIN_VERTICES, roomy ? vertices * 2 : vertices),
                    Math.max(MIN_FACES, roomy ? faces * 2 : faces), radius);
                if (created == null) { return false; }
                // Normals point straight up (model y is down): 117 HD, which uses them because faces are not
                // marked flat (see FlatModel.paint), then lights every mark like flat ground seen from above.
                FlatModel.normals(created);
                // Carriers start with six extreme vertices from fixing their bounds.
                b.adopt(new Spare(created, radius, 0, 6));
            }
        }
        Model m = b.model;
        if (b.xray)
        {
            // Through walls, getModel writes the vertices and faces with the camera the client draws with (pullToCamera):
            // every vertex (unused ones onto a used one, so none passes through the origin, which the renderer may read
            // meanwhile; all go back to the origin on the next write). Pulling here as well was thrown away whenever the
            // camera moved.
            b.freeze(anchorX, anchorY, anchorZ, cuts);
            b.usedVertices = m.getVerticesCount();
        }
        else
        {
            // Unused vertices at the origin, inside the fixed bounds.
            float[] vx = m.getVerticesX(), vy = m.getVerticesY(), vz = m.getVerticesZ();
            for (int i = b.vertices; i < b.usedVertices; i++) { vx[i] = 0; vy[i] = 0; vz[i] = 0; }
            for (int i = 0; i < b.vertices; i++)
            {
                vx[i] = b.wx[i] - anchorX;
                vy[i] = b.wz[i] - anchorZ;
                vz[i] = b.wy[i] - anchorY;
            }
            b.usedVertices = b.vertices;
            b.writeFaces(m, b.faces, b.fa, b.fb, b.fc, null, b.color, b.alpha);
            FlatModel.bounds(m);
        }
        b.object.setLocation(new LocalPoint(anchorX, anchorY, b.worldView), b.level);
        b.object.setZ(anchorZ);
        // Orientation 0 and the default radius 60 (tile centre +- 60) keep the footprint on its own tile; the model's
        // own fixed bounds cover the geometry.
        if (!client.isRuneLiteObjectRegistered(b.object)) { client.registerRuneLiteObject(b.object); }
        return true;
    }

    /** The spare with the fewest vertices that has this radius and room, or null. */
    private Spare spare(float radius, int vertices, int faces)
    {
        Spare best = null;
        for (Spare s : spareCarriers)
        {
            if (s.radius >= radius && s.model.getVerticesCount() >= vertices && s.model.getFaceCount() >= faces
                && (best == null || s.model.getVerticesCount() < best.model.getVerticesCount())) { best = s; }
        }
        return best;
    }

    /**
     * The actors this frame whose silhouettes marks through walls leave out (see cuts): the local player (null for not)
     * and the NPCs put In front, at most MAX_CUTS of them together, the first ones of the list.
     */
    void cutAround(Player p, List<NPC> npcs)
    {
        cuts = Collections.emptyList();
        if (!xray || unavailable) { npcShapes.clear(); return; }
        WorldView top = client.getTopLevelWorldView();
        List<Actor> actors = new ArrayList<>();
        // On a boat an actor's location is in the boat's world view, not the one projected here.
        if (p != null && p.getWorldView() == top && p.getLocalLocation() != null) { actors.add(p); }
        for (NPC n : npcs)
        {
            if (actors.size() >= MAX_CUTS) { break; }
            if (n != null && n.getWorldView() == top && n.getLocalLocation() != null) { actors.add(n); }
        }
        // Where a wall or object nearer the camera covers an actor, it is not seen there and the marks are not cut. Taken
        // before the actors' models, which can share their arrays with the objects' models.
        occluders.clear();
        cutActors.clear(); occludersTaken.clear(); occluderTiles.clear();
        cutActors.addAll(actors);
        for (Actor a : actors) { occluders(a, a.getLocalLocation()); ground(a, a.getLocalLocation()); }
        List<PlayerSilhouette> taken = new ArrayList<>(actors.size());
        Set<NPC> kept = Collections.newSetFromMap(new IdentityHashMap<>());
        for (Actor a : actors)
        {
            LocalPoint at = a.getLocalLocation();
            // As the client places an actor: on its footprint's height, raised by its animation.
            int height = Perspective.getFootprintTileHeight(client, at, a.getWorldView().getPlane(), a.getFootprintSize()) - a.getAnimationHeightOffset();
            PlayerSilhouette s = a == p ? playerShape : npcShapes.computeIfAbsent((NPC) a, n -> new PlayerSilhouette());
            if (a != p) { kept.add((NPC) a); }
            Model model = a.getModel();
            if (model != null && s.take(model, at.getX(), at.getY(), height, a.getCurrentOrientation(), occluders)) { taken.add(s); }
        }
        // An NPC no longer In front, or gone: its silhouette and arrays with it.
        npcShapes.keySet().retainAll(kept);
        cuts = taken;
    }

    /**
     * The walls and objects that may stand between the camera and an actor (and the other actors the client keeps as
     * objects on their tiles): those on the tiles along the way from the camera to the actor and beside them.
     */
    private void occluders(Actor a, LocalPoint at)
    {
        int plane = a.getWorldView().getPlane();
        Scene scene = client.getTopLevelWorldView().getScene();
        Tile[][][] levels = scene == null ? null : scene.getTiles();
        if (levels == null || plane < 0 || plane >= levels.length) { return; }
        Tile[][] tiles = levels[plane];
        float dx = at.getX() - camera.x, dy = at.getY() - camera.y;
        int steps = (int) (Math.hypot(dx, dy) / 64) + 1;
        for (int i = 0; i <= steps; i++)
        {
            int cx = (int) (camera.x + dx * i / steps) >> 7, cy = (int) (camera.y + dy * i / steps) >> 7;
            for (int tx = cx - 1; tx <= cx + 1; tx++)
            {
                for (int ty = cy - 1; ty <= cy + 1; ty++)
                {
                    if (tx < 0 || ty < 0 || tx >= tiles.length || ty >= tiles[tx].length || tiles[tx][ty] == null || !occluderTiles.add((long) tx << 32 | ty)) { continue; }
                    Tile t = tiles[tx][ty];
                    WallObject w = t.getWallObject();
                    if (w != null && occludersTaken.add(w)) { occluder(w.getRenderable1(), 0, w); occluder(w.getRenderable2(), 0, w); }
                    for (GameObject o : t.getGameObjects()) { if (o != null && occludersTaken.add(o)) { occluder(o.getRenderable(), o.getModelOrientation(), o); } }
                }
            }
        }
    }

    /** Scratch for ground: the tiles around an actor as faces. */
    private float[] gx = new float[0], gy = new float[0], gz = new float[0];
    private int[] ga = new int[0], gb = new int[0], gc = new int[0];

    /**
     * The ground around an actor as an occluder: what lies under it (a model's soles sit a few units below the ground;
     * on a slope more of it) is hidden by the terrain, so the marks are not cut there.
     */
    private void ground(Actor a, LocalPoint at)
    {
        WorldView wv = client.getTopLevelWorldView();
        int level = Terrain.level(wv, at.getSceneX(), at.getSceneY(), a.getWorldView().getPlane());
        int size = Math.max(1, a.getFootprintSize()), r = size / 2 + 1;
        int x0 = (at.getX() >> 7) - r, y0 = (at.getY() >> 7) - r, side = 2 * r + 1, points = (side + 1) * (side + 1), faces = side * side * 2;
        if (gx.length < points) { gx = new float[points]; gy = new float[points]; gz = new float[points]; }
        if (ga.length < faces) { ga = new int[faces]; gb = new int[faces]; gc = new int[faces]; }
        for (int j = 0; j <= side; j++)
        {
            for (int i = 0; i <= side; i++)
            {
                int x = (x0 + i) * 128, y = (y0 + j) * 128, k = j * (side + 1) + i;
                gx[k] = x; gz[k] = y; gy[k] = Terrain.heightOnLevel(wv, x, y, level);
            }
        }
        int f = 0;
        for (int j = 0; j < side; j++)
        {
            for (int i = 0; i < side; i++)
            {
                int k = j * (side + 1) + i;
                ga[f] = k; gb[f] = k + 1; gc[f] = k + side + 2; f++;
                ga[f] = k; gb[f] = k + side + 2; gc[f] = k + side + 1; f++;
            }
        }
        occluders.addGround(gx, gy, gz, points, ga, gb, gc, faces);
    }

    /** A wall's or object's model as an occluder; the actors cut out are none for each other. */
    private void occluder(Renderable r, int orientation, TileObject o)
    {
        if (r == null || cutActors.contains(r)) { return; }
        Model m = r instanceof Model ? (Model) r : r.getModel();
        LocalPoint at = o.getLocalLocation();
        if (m != null && at != null) { occluders.add(m, at.getX(), at.getY(), o.getZ(), orientation); }
    }

    /** Whether the shape with this key is in the scene this frame. */
    boolean drawn(String key) { return !unavailable && appended.contains(key); }

    /** Takes every shape out of the scene; their models stay as spares for the next frames. */
    void clear()
    {
        for (Bucket b : buckets.values()) { retire(b); }
        buckets.clear();
        stages.clear();
        silhouetteScratch.bits = new long[0];
        projections.clear();
        appended.clear();
    }

    /** As clear, and the models are dropped too. */
    void reset() { clear(); spareCarriers.clear(); carriers.reset(); }

    /** Shapes of one tile and level in world points with their layer, and faces with colour and alpha. */
    private static class Geometry
    {
        final int tileX, tileY, level, worldView;
        float[] wx = new float[64], wy = new float[64], wz = new float[64], layer = new float[64];
        int[] fa = new int[96], fb = new int[96], fc = new int[96], color = new int[96], alpha = new int[96];
        int vertices, faces;
        boolean xray, shared;

        Geometry(int tileX, int tileY, int level, int worldView)
        { this.tileX = tileX; this.tileY = tileY; this.level = level; this.worldView = worldView; }

        void ensure(int vertexCount, int faceCount)
        {
            if (wx.length < vertexCount)
            {
                int n = vertexCount * 2;
                wx = Arrays.copyOf(wx, n); wy = Arrays.copyOf(wy, n); wz = Arrays.copyOf(wz, n);
                layer = Arrays.copyOf(layer, n);
            }
            if (fa.length < faceCount)
            {
                int n = faceCount * 2;
                fa = Arrays.copyOf(fa, n); fb = Arrays.copyOf(fb, n); fc = Arrays.copyOf(fc, n);
                color = Arrays.copyOf(color, n); alpha = Arrays.copyOf(alpha, n);
            }
        }
    }

    /** One frame's shapes of a bucket key as they are drawn, each shape a block of vertices and faces with its rank. */
    private static final class Stage extends Geometry
    {
        /** Per shape: rank, first vertex, vertices, first face, faces. */
        static final int FIELDS = 5;
        /** Ranks are layers, counted into this many slots; anything outside goes to the nearest one. */
        private static final int RANKS = 64;
        int count;
        int[] shapes = new int[FIELDS * 16];
        private int[] order = new int[16];
        private final int[] slots = new int[RANKS + 1];
        /** Per face, the points it adds and the faces it becomes when the player's cut is made, with room to grow (append). */
        int[] cutVertices = new int[96], cutFaces = new int[96];
        /** Per shape, the key of the mark it draws. */
        String[] keys = new String[16];

        Stage(int tileX, int tileY, int level, int worldView) { super(tileX, tileY, level, worldView); }

        @Override void ensure(int vertexCount, int faceCount)
        {
            super.ensure(vertexCount, faceCount);
            if (cutVertices.length < fa.length) { cutVertices = Arrays.copyOf(cutVertices, fa.length); cutFaces = Arrays.copyOf(cutFaces, fa.length); }
        }

        /** Starts a shape of the given layer: what is appended until end() belongs to it. */
        void begin(int rank, String key)
        {
            if (shapes.length < (count + 1) * FIELDS) { shapes = Arrays.copyOf(shapes, shapes.length * 2); }
            if (keys.length <= count) { keys = Arrays.copyOf(keys, keys.length * 2); }
            keys[count] = key;
            int s = count * FIELDS;
            shapes[s] = Math.max(0, Math.min(RANKS - 1, rank));
            shapes[s + 1] = vertices;
            shapes[s + 3] = faces;
        }

        void end()
        {
            int s = count * FIELDS;
            shapes[s + 2] = vertices - shapes[s + 1];
            shapes[s + 4] = faces - shapes[s + 3];
            count++;
        }

        /** Shape indices by rank, in drawn order within a rank (a counting sort: stable, no garbage). */
        int[] byRank()
        {
            if (order.length < count) { order = new int[count * 2]; }
            Arrays.fill(slots, 0);
            for (int k = 0; k < count; k++) { slots[shapes[k * FIELDS] + 1]++; }
            for (int r = 0; r < RANKS; r++) { slots[r + 1] += slots[r]; }
            for (int k = 0; k < count; k++) { order[slots[shapes[k * FIELDS]]++] = k; }
            return order;
        }
    }

    /** All shapes of one tile and level, merged into one scene object. */
    private final class Bucket extends Geometry
    {
        final RuneLiteObjectController object = new RuneLiteObjectController()
        {
            @Override public Model getModel() { return Bucket.this.getModel(); }
        };
        Model model;
        int radius, usedFaces, usedVertices;
        /** Objects after this one with the same bucket key, holding higher ranks (see split). */
        int partsAfter;
        /** The points and faces its shapes take with the player's cut made, and room to grow (see split). */
        int needVertices, needFaces;
        /** The keys of the marks it holds (part of), which fall back to 2D should it not be made. */
        final List<String> keys = new ArrayList<>();

        /**
         * What the renderer may read while HD World Markers writes the next frame: getModel() can run
         * on another thread, so it works on this copy, taken when the frame is written.
         */
        private Model frozenModel;
        private float[] fx = new float[0], fy = fx, fz = fx;
        private float[] fl = new float[0];
        private int frozenVertices, fAnchorX, fAnchorY, fAnchorZ;
        /** The faces written with them (vertex indices, colour, alpha), and the actors whose silhouettes they leave out. */
        private int[] ffa = new int[0], ffb = ffa, ffc = ffa, fColor = ffa, fAlpha = ffa;
        private int frozenFaces;
        private List<PlayerSilhouette> frozenCuts = Collections.emptyList();
        /** Scratch for cut: the geometry as seen from a camera, cut around the player; points on the canvas, layers. */
        private final ScreenOutline cutter = new ScreenOutline();
        private float[] sx = new float[0], sy = sx, sd = sx, sl = sx;
        /** The camera of the last pull in getModel; null after freeze (a new frame), so the next call pulls. */
        private ModelShapes.Camera pulled;

        /** Whether the last pull was with this camera; remembers it. */
        private synchronized boolean pulledWith(ModelShapes.Camera cam)
        {
            if (cam.same(pulled)) { return true; }
            pulled = cam;
            return false;
        }

        /** Scratch for pullToCamera, which is synchronized. */
        private final float[] pullPoint = new float[3], pullGround = new float[3], pullReach = new float[2];

        synchronized void freeze(int anchorX, int anchorY, int anchorZ, List<PlayerSilhouette> cuts)
        {
            if (fx.length < vertices) { fx = new float[wx.length]; fy = new float[wx.length]; fz = new float[wx.length]; fl = new float[wx.length]; }
            System.arraycopy(wx, 0, fx, 0, vertices); System.arraycopy(wy, 0, fy, 0, vertices);
            System.arraycopy(wz, 0, fz, 0, vertices); System.arraycopy(layer, 0, fl, 0, vertices);
            if (ffa.length < faces) { ffa = new int[fa.length]; ffb = new int[fa.length]; ffc = new int[fa.length]; fColor = new int[fa.length]; fAlpha = new int[fa.length]; }
            System.arraycopy(fa, 0, ffa, 0, faces); System.arraycopy(fb, 0, ffb, 0, faces); System.arraycopy(fc, 0, ffc, 0, faces);
            System.arraycopy(color, 0, fColor, 0, faces); System.arraycopy(alpha, 0, fAlpha, 0, faces);
            frozenModel = model; frozenVertices = vertices; frozenFaces = faces; frozenCuts = cuts;
            pulled = null;
            fAnchorX = anchorX; fAnchorY = anchorY; fAnchorZ = anchorZ;
        }

        /**
         * Moves every vertex along its view ray to just in front of the camera, keeping its screen position: one depth
         * per layer, higher layers in front (see XRAY_DEPTH). The actors' silhouettes as seen from this camera are cut out
         * of the faces first, one after another, so the player and the NPCs put In front stand in front of the marks.
         */
        synchronized void pullToCamera(ModelShapes.Camera cam)
        {
            Model m = frozenModel;
            if (m == null || frozenVertices > m.getVerticesCount()) { return; }
            // Within what the model holds: should the camera have moved far since the frame was made, a face past that
            // stays whole this frame.
            int n = frozenVertices;
            if (sx.length < n) { sx = new float[n * 2]; sy = new float[n * 2]; sd = new float[n * 2]; }
            float[] q = pullPoint;
            for (int i = 0; i < n; i++) { cam.project(fx[i], fy[i], fz[i], q); sx[i] = q[0]; sy[i] = q[1]; sd[i] = q[2]; }
            ScreenOutline o = cutter;
            o.load(sx, sy, sd, n, ffa, ffb, ffc, frozenFaces);
            for (PlayerSilhouette s : frozenCuts)
            {
                PlayerCut around = s.cut(cam);
                if (around != null) { o.cutOut(around, m.getVerticesCount(), m.getFaceCount()); }
            }
            // The layer of every point: that of the face it was cut from.
            if (sl.length < o.vertices) { sl = new float[o.vertices * 2]; }
            System.arraycopy(fl, 0, sl, 0, frozenVertices);
            for (int f = 0; f < o.faces; f++) { float l = fl[ffa[o.source[f]]]; sl[o.a[f]] = l; sl[o.b[f]] = l; sl[o.c[f]] = l; }
            float[] vx = m.getVerticesX(), vy = m.getVerticesY(), vz = m.getVerticesZ();
            float[] p = pullPoint, g = pullGround;
            // One depth per layer for every point, higher layers nearer (see XRAY_DEPTH): the ranking, not the ground,
            // decides. With the anchor far from the camera (no tile near it to hang on, as in a building) the points
            // cannot come that near: then the layers lie farther, where every point's ray is within reach, still one depth
            // each. Stopping each point at its own reach left one layer at many depths, and the renderer's depth sort
            // drew an NPC's marks over and under each other in turn as they moved.
            reach(cam, o, g, pullReach);
            float lo = pullReach[0], hi = pullReach[1];
            float top = lo <= XRAY_DEPTH ? XRAY_DEPTH : (float) Math.floor(lo) + 1.5f, step = XRAY_LAYER_DEPTH;
            // An even whole step keeps every layer, and a white layer half a step up, in the middle of a whole unit.
            if (top + XRAY_TOP_LAYER * step > hi) { step = 2 * (float) Math.floor((hi - top) / XRAY_TOP_LAYER / 2); }
            boolean planes = lo <= hi && step >= 2;
            for (int i = 0; i < o.vertices; i++)
            {
                float bias = sl[i] * 0.25f;
                // The floor keeps the layer order (and the white layer in front) where the depth is clamped.
                float floor = XRAY_MIN_DEPTH + XRAY_LAYER_SPAN - bias;
                float rank = Math.max(0, Math.min(XRAY_TOP_LAYER, sl[i]));
                float at;
                if (planes) { at = Math.max(floor, top + (XRAY_TOP_LAYER - rank) * step); }
                else
                {
                    // No depth within reach of every point (a shape spread wide around a far anchor): each point as near
                    // as its own reach lets it.
                    at = Math.max(floor, withinReach(cam, o.x[i], o.y[i], o.depth[i], g, XRAY_DEPTH + (XRAY_TOP_LAYER - rank) * XRAY_LAYER_DEPTH, bias));
                }
                cam.unproject(o.x[i], o.y[i], at, p);
                vx[i] = p[0] - fAnchorX;
                vy[i] = p[2] - fAnchorZ;
                vz[i] = p[1] - fAnchorY;
            }
            // The GPU plugin skips a see-through model whole if any vertex, used or not, is nearer the camera
            // than 50 (ModelUploader.uploadSortedModel). The anchor, where unused vertices would sit, can be at
            // the camera itself: they sit on the first vertex, which is surely in front of it.
            if (o.vertices > 0)
            {
                for (int i = o.vertices; i < m.getVerticesCount(); i++) { vx[i] = vx[0]; vy[i] = vy[0]; vz[i] = vz[0]; }
            }
            writeFaces(m, o.faces, o.a, o.b, o.c, o.source, fColor, fAlpha);
        }

        /** Writes nf faces (vertex indices, with the colour and alpha of their source face or their own) and hides the rest. */
        void writeFaces(Model m, int nf, int[] a, int[] b, int[] c, int[] source, int[] colors, int[] alphas)
        {
            int[] i1 = m.getFaceIndices1(), i2 = m.getFaceIndices2(), i3 = m.getFaceIndices3();
            for (int f = 0; f < nf; f++)
            {
                int s = source == null ? f : source[f];
                i1[f] = a[f]; i2[f] = b[f]; i3[f] = c[f];
                FlatModel.paint(m, f, colors[s], alphas[s]);
            }
            for (int f = nf; f < usedFaces; f++) { FlatModel.hide(m, f); }
            usedFaces = nf;
        }

        /**
         * The depths at which the rays from the camera through all points of o are within XRAY_REACH of the anchor: out
         * {nearest, farthest}, nearest beyond farthest when no one depth is within reach on every ray.
         */
        private void reach(ModelShapes.Camera cam, ScreenOutline o, float[] g, float[] out)
        {
            float lo = 0, hi = Float.MAX_VALUE;
            double[] span = pullSpan;
            for (int i = 0; i < o.vertices && lo <= hi; i++)
            {
                float dg = o.depth[i];
                if (!(dg > 0) || !ray(cam, o.x[i], o.y[i], dg, g, span)) { lo = Float.MAX_VALUE; break; }
                lo = Math.max(lo, (float) (span[0] * dg));
                hi = Math.min(hi, (float) (span[1] * dg));
            }
            out[0] = lo; out[1] = hi;
        }

        /** Scratch for ray. */
        private final double[] pullSpan = new double[2];

        /**
         * Where the ray from the camera through canvas point (sx, sy), to its ground point at depth dg (g: scratch), is
         * within XRAY_REACH of the anchor: out {enters, leaves} as multiples of dg. False when it never is.
         */
        private boolean ray(ModelShapes.Camera cam, float sx, float sy, float dg, float[] g, double[] out)
        {
            cam.unproject(sx, sy, dg, g);
            // Points on the ray: camera + (g - camera) * s, where s = depth / dg.
            float ux = cam.x - fAnchorX, uy = cam.y - fAnchorY, uz = cam.z - fAnchorZ;
            float vx = g[0] - cam.x, vy = g[1] - cam.y, vz = g[2] - cam.z;
            double a = vx * vx + vy * vy + vz * vz, b = 2.0 * (ux * vx + uy * vy + uz * vz);
            double c = ux * ux + uy * uy + uz * uz - (double) XRAY_REACH * XRAY_REACH, disc = b * b - 4 * a * c;
            if (a <= 0 || disc < 0) { return false; }
            double root = Math.sqrt(disc);
            out[0] = (-b - root) / (2 * a);
            out[1] = (-b + root) / (2 * a);
            return true;
        }

        /**
         * The depth to use on the ray from the camera through canvas point (sx, sy), whose ground point lies at depth dg:
         * the wanted depth, or, when that lies farther than XRAY_REACH from the anchor, the nearest depth within it.
         */
        private float withinReach(ModelShapes.Camera cam, float sx, float sy, float dg, float[] g, float wanted, float bias)
        {
            if (!(dg > 0)) { return wanted; }
            double[] span = pullSpan;
            if (!ray(cam, sx, sy, dg, g, span)) { return dg; }
            double enter = span[0], exit = span[1], s = wanted / dg;
            // A camera inside the reach: far points could be wanted beyond it.
            if (s > exit) { return (float) Math.max(XRAY_MIN_DEPTH, exit * dg - bias); }
            if (s >= enter) { return wanted; }
            // Clamped: keep the layer order among shapes at the same place.
            return (float) Math.min(dg, enter * dg) - bias;
        }

        Bucket(int tileX, int tileY, int level, int worldView) { super(tileX, tileY, level, worldView); }

        void hide() { if (client.isRuneLiteObjectRegistered(object)) { client.removeRuneLiteObject(object); } }

        /**
         * Gives up the model (null without one): a renderer thread still holding this object then finds no model to
         * pull, so it never writes into a model another object took over.
         */
        synchronized Spare release()
        {
            Spare spare = model == null ? null : new Spare(model, radius, usedFaces, usedVertices);
            model = null;
            frozenModel = null;
            return spare;
        }

        synchronized void adopt(Spare s)
        {
            model = s.model; radius = s.radius; usedFaces = s.usedFaces; usedVertices = s.usedVertices;
        }

        Model getModel()
        {
            Model model = this.model;
            if (model == null) { return null; }
            ModelShapes.Camera now = drawCamera();
            // Borders are as wide as wanted for the camera the frame was built with. When the client draws with one
            // that jumped (at login the frame's camera was not set yet, or a teleport), they became a screen-wide
            // flash of colour for a frame: nothing is drawn until the next frame is built with the new camera.
            ModelShapes.Camera built = camera;
            if (built != null && built.jumpedTo(now)) { return null; }
            // Near the camera, a camera that moved since the frame began is off by many pixels:
            // follow the camera the renderer is drawing with right now.
            // The renderer may ask several times per frame (117 HD: shadows, scene): pull again only when the camera
            // moved or the frame was rewritten since the last pull.
            if (xray && !pulledWith(now))
            {
                pullToCamera(now);
                FlatModel.bounds(model);
            }
            return model;
        }
    }
}

package com.hdworldmarkers;

import java.util.List;

/**
 * Border and fill triangles for a closed canvas polygon, with a depth per
 * vertex. Arrays are reused between builds to avoid per-frame garbage.
 *
 * Vertices: outer ring 0..n-1, inner ring n..2n-1, center 2n. Faces
 * [0, borderFaces) are the border; the rest fan the inner ring to the center.
 * The polygon must be star-shaped around the center, which holds for convex
 * hulls and for projected tile footprints.
 */
final class ScreenOutline
{
    float[] x = new float[0], y = new float[0], depth = new float[0];
    int[] a = new int[0], b = new int[0], c = new int[0];
    int vertices, faces, borderFaces;
    float minX, minY, maxX, maxY;

    /**
     * Returns false for fewer than three points. The input may wind either
     * way; the border is centered on the edges with the given canvas width.
     */
    boolean build(float[] px, float[] py, float[] pd, int n, float cx, float cy, float cd, float width)
    {
        if (n < 3 || !(width > 0)) { return false; }
        ring(px, py, pd, n, width, true, false);
        vertices = 2 * n + 1;
        x[2 * n] = cx; y[2 * n] = cy; depth[2 * n] = cd;
        faces = borderFaces;
        for (int i = 0; i < n; i++) { faces = face(faces, n + i, n + (i + 1) % n, 2 * n); }
        return true;
    }

    /**
     * Border and fill for any simple polygon, such as RuneLite's rectilinear
     * clickboxes. The border ring is centred on the edges like build(); the fill
     * is an ear-clipping triangulation of the inner ring, so it needs no centre.
     * Vertices: outer ring 0..n-1, inner ring n..2n-1. Outside puts the whole
     * border outside the polygon, as RuneLite's outlines.
     */
    boolean buildPolygon(float[] px, float[] py, float[] pd, int n, float width, boolean outside)
    {
        if (n < 3 || !(width > 0)) { return false; }
        float sign = ring(px, py, pd, n, width, true, outside);
        vertices = 2 * n;
        faces = earClip(n, sign, borderFaces);
        return true;
    }

    /**
     * The border: outer points 0..n-1 and inner points n..2n-1, mitred (limited so sharp corners do not spike), with
     * their faces and bounds. Closed, it runs round the polygon (either winding), centred on the edges or with outside
     * all outside them; open, it is a strip with square ends. Returns the winding sign.
     */
    private float ring(float[] px, float[] py, float[] pd, int n, float width, boolean closed, boolean outside)
    {
        if (x.length < 2 * n + 1) { x = new float[(2 * n + 1) * 2]; y = new float[(2 * n + 1) * 2]; depth = new float[(2 * n + 1) * 2]; }
        if (a.length < 3 * n) { a = new int[6 * n]; b = new int[6 * n]; c = new int[6 * n]; }
        double area = 0;
        for (int i = 0; closed && i < n; i++) { int j = (i + 1) % n; area += px[i] * py[j] - px[j] * py[i]; }
        // With a positive signed area the outward normal of edge (dx, dy) is (dy, -dx).
        float sign = area >= 0 ? 1 : -1, half = width / 2f;
        minX = minY = Float.MAX_VALUE;
        maxX = maxY = -Float.MAX_VALUE;
        for (int i = 0; i < n; i++)
        {
            // An open strip's ends have no edge before or after them.
            int prev = closed ? (i + n - 1) % n : Math.max(0, i - 1), next = closed ? (i + 1) % n : Math.min(n - 1, i + 1);
            float n0x = sign * (py[i] - py[prev]), n0y = -sign * (px[i] - px[prev]);
            float n1x = sign * (py[next] - py[i]), n1y = -sign * (px[next] - px[i]);
            float l0 = (float) Math.sqrt(n0x * n0x + n0y * n0y), l1 = (float) Math.sqrt(n1x * n1x + n1y * n1y);
            if (l0 > 0) { n0x /= l0; n0y /= l0; }
            if (l1 > 0) { n1x /= l1; n1y /= l1; }
            float mx = n0x + n1x, my = n0y + n1y, ml = (float) Math.sqrt(mx * mx + my * my), offset = 0;
            if (ml > 1e-4f)
            {
                mx /= ml; my /= ml;
                offset = half / Math.max(0.25f, l1 > 0 ? mx * n1x + my * n1y : mx * n0x + my * n0y);
            }
            float outer = outside ? 2 * offset : offset, inner = outside ? 0 : offset;
            x[i] = px[i] + mx * outer; y[i] = py[i] + my * outer;
            x[n + i] = px[i] - mx * inner; y[n + i] = py[i] - my * inner;
            depth[i] = depth[n + i] = pd[i];
            minX = Math.min(minX, Math.min(x[i], x[n + i])); maxX = Math.max(maxX, Math.max(x[i], x[n + i]));
            minY = Math.min(minY, Math.min(y[i], y[n + i])); maxY = Math.max(maxY, Math.max(y[i], y[n + i]));
        }
        int f = 0;
        for (int i = 0; i < (closed ? n : n - 1); i++)
        {
            int j = (i + 1) % n;
            f = face(f, i, j, n + j);
            f = face(f, i, n + j, n + i);
        }
        borderFaces = f;
        return sign;
    }

    /** Ear clipping of the inner ring (vertices n..2n-1), which winds with the given sign. */
    private int earClip(int n, float sign, int f)
    {
        int[] ring = new int[n];
        for (int i = 0; i < n; i++) { ring[i] = n + i; }
        int count = n, guard = 0;
        while (count > 3 && guard++ < n * n)
        {
            boolean clipped = false;
            for (int i = 0; i < count; i++)
            {
                int p = ring[(i + count - 1) % count], q = ring[i], r = ring[(i + 1) % count];
                float turn = (x[q] - x[p]) * (y[r] - y[p]) - (y[q] - y[p]) * (x[r] - x[p]);
                if (turn * sign <= 0) { continue; }
                boolean inside = false;
                for (int k = 0; k < count && !inside; k++)
                {
                    int v = ring[k];
                    if (v == p || v == q || v == r) { continue; }
                    inside = inTriangle(x[v], y[v], p, q, r);
                }
                if (inside) { continue; }
                f = face(f, p, q, r);
                System.arraycopy(ring, i + 1, ring, i, count - i - 1);
                count--;
                clipped = true;
                break;
            }
            // Degenerate input (collinear or self-touching): stop rather than loop.
            if (!clipped) { break; }
        }
        if (count == 3) { f = face(f, ring[0], ring[1], ring[2]); }
        return f;
    }

    private boolean inTriangle(float px, float py, int p, int q, int r)
    {
        float d1 = (px - x[q]) * (y[p] - y[q]) - (x[p] - x[q]) * (py - y[q]);
        float d2 = (px - x[r]) * (y[q] - y[r]) - (x[q] - x[r]) * (py - y[r]);
        float d3 = (px - x[p]) * (y[r] - y[p]) - (x[r] - x[p]) * (py - y[p]);
        boolean neg = d1 < 0 || d2 < 0 || d3 < 0, pos = d1 > 0 || d2 > 0 || d3 > 0;
        return !(neg && pos);
    }

    /**
     * An open polyline of the given canvas width: border faces only, for tile
     * corners. Ends are square; inner vertices are mitred.
     */
    boolean buildStrip(float[] px, float[] py, float[] pd, int n, float width)
    {
        if (n < 2 || !(width > 0)) { return false; }
        ring(px, py, pd, n, width, false, false);
        vertices = 2 * n;
        faces = borderFaces;
        return true;
    }

    private int face(int f, int v1, int v2, int v3)
    {
        // The client draws a face when (a - b) x (c - b) > 0 in canvas space.
        float cross = (x[v1] - x[v2]) * (y[v3] - y[v2]) - (y[v1] - y[v2]) * (x[v3] - x[v2]);
        a[f] = v1;
        if (cross >= 0) { b[f] = v2; c[f] = v3; }
        else { b[f] = v3; c[f] = v2; }
        return f + 1;
    }

    /** Scratch for cutOut: the piece being split and its two halves, as x, y, depth per point. */
    private float[] piece = new float[3 * 64], inside = new float[3 * 64], outside = new float[3 * 64], part = new float[3 * 64];
    /** Per face, the face of the geometry before cutOut it comes from (see load); and the one being cut. */
    int[] source = new int[0];
    private int current;
    /** The points made for the face being cut, by place (to 1/64 pixel): its pieces share their corners. */
    private final java.util.Map<Long, Integer> made = new java.util.HashMap<>();
    private int[] oa = new int[0], ob = oa, oc = oa, os = oa;
    private int[] corners = new int[16];

    /** Takes these points {x, y, depth} and faces as they are, each face its own source, with their bounds. */
    void load(float[] px, float[] py, float[] pd, int n, int[] fa, int[] fb, int[] fc, int nf)
    {
        if (x.length < n) { x = new float[n * 2]; y = new float[n * 2]; depth = new float[n * 2]; }
        System.arraycopy(px, 0, x, 0, n); System.arraycopy(py, 0, y, 0, n); System.arraycopy(pd, 0, depth, 0, n);
        vertices = n;
        faces = 0;
        borderFaces = 0;
        growFaces(nf);
        System.arraycopy(fa, 0, a, 0, nf); System.arraycopy(fb, 0, b, 0, nf); System.arraycopy(fc, 0, c, 0, nf);
        for (int f = 0; f < nf; f++) { source[f] = f; }
        faces = nf;
        minX = minY = Float.MAX_VALUE;
        maxX = maxY = -Float.MAX_VALUE;
        for (int i = 0; i < n; i++)
        {
            minX = Math.min(minX, px[i]); maxX = Math.max(maxX, px[i]);
            minY = Math.min(minY, py[i]); maxY = Math.max(maxY, py[i]);
        }
    }

    /** After a cutOut: per face f, the points and faces made before it at 2f and 2f + 1; after the last face, the totals. */
    int[] before = new int[0];
    private int[] owner = new int[0], costVertices = new int[0], costFaces = new int[0];

    /**
     * As before, after one or more cutOuts of geometry loaded with originalVertices points and originalFaces faces: per
     * original face, the points made for it (each new point counted for the first face it serves) and the faces it became.
     */
    int[] costs(int originalVertices, int originalFaces)
    {
        if (before.length < 2 * originalFaces + 2) { before = new int[4 * originalFaces + 4]; }
        if (costVertices.length < originalFaces) { costVertices = new int[originalFaces * 2]; costFaces = new int[originalFaces * 2]; }
        if (owner.length < vertices) { owner = new int[vertices * 2]; }
        java.util.Arrays.fill(costVertices, 0, originalFaces, 0);
        java.util.Arrays.fill(costFaces, 0, originalFaces, 0);
        java.util.Arrays.fill(owner, 0, vertices, -1);
        for (int f = 0; f < faces; f++)
        {
            int src = source[f];
            costFaces[src]++;
            int v1 = a[f], v2 = b[f], v3 = c[f];
            if (v1 >= originalVertices && owner[v1] < 0) { owner[v1] = src; costVertices[src]++; }
            if (v2 >= originalVertices && owner[v2] < 0) { owner[v2] = src; costVertices[src]++; }
            if (v3 >= originalVertices && owner[v3] < 0) { owner[v3] = src; costVertices[src]++; }
        }
        int points = 0, made = 0;
        for (int f = 0; f < originalFaces; f++)
        {
            before[2 * f] = points; before[2 * f + 1] = made;
            points += costVertices[f]; made += costFaces[f];
        }
        before[2 * originalFaces] = points; before[2 * originalFaces + 1] = made;
        return before;
    }

    /**
     * Leaves the player uncovered: of every face, what lies outside the cut's box is kept, and inside it only what
     * lies in its pieces (the box minus the player's silhouette). A face whose pieces would take more than maxVertices
     * points, or leave fewer than maxFaces faces for the faces after it, stays whole. Returns whether the box meets the
     * geometry at all.
     */
    boolean cutOut(PlayerCut keep, int maxVertices, int maxFaces)
    {
        if (keep.maxX < minX || keep.minX > maxX || keep.maxY < minY || keep.minY > maxY) { return false; }
        // The box, clockwise on the canvas (y down): positive area in these coordinates.
        float[] hx = {keep.minX, keep.maxX, keep.maxX, keep.minX}, hy = {keep.minY, keep.minY, keep.maxY, keep.maxY};
        if (oa.length < faces) { oa = new int[a.length]; ob = new int[a.length]; oc = new int[a.length]; os = new int[a.length]; }
        System.arraycopy(a, 0, oa, 0, faces); System.arraycopy(b, 0, ob, 0, faces); System.arraycopy(c, 0, oc, 0, faces);
        System.arraycopy(source, 0, os, 0, faces);
        int oldFaces = faces, oldBorder = borderFaces;
        if (before.length < 2 * oldFaces + 2) { before = new int[4 * oldFaces + 4]; }
        faces = 0;
        for (int f = 0; f < oldFaces; f++)
        {
            if (f == oldBorder) { borderFaces = faces; }
            before[2 * f] = vertices;
            before[2 * f + 1] = faces;
            current = os[f];
            cut(keep, hx, hy, oa[f], ob[f], oc[f]);
            if (vertices > maxVertices || faces + oldFaces - 1 - f > maxFaces)
            {
                vertices = before[2 * f];
                faces = before[2 * f + 1];
                keep(oa[f], ob[f], oc[f]);
            }
        }
        before[2 * oldFaces] = vertices;
        before[2 * oldFaces + 1] = faces;
        if (oldBorder >= oldFaces) { borderFaces = faces; }
        return true;
    }

    /** Cuts one face (points v1, v2, v3): what lies outside the box (hx, hy), and inside it what lies in the pieces. */
    private void cut(PlayerCut keep, float[] hx, float[] hy, int v1, int v2, int v3)
    {
        made.clear();
        float fMinX = Math.min(x[v1], Math.min(x[v2], x[v3])), fMaxX = Math.max(x[v1], Math.max(x[v2], x[v3]));
        float fMinY = Math.min(y[v1], Math.min(y[v2], y[v3])), fMaxY = Math.max(y[v1], Math.max(y[v2], y[v3]));
        if (fMaxX <= keep.minX || fMinX >= keep.maxX || fMaxY <= keep.minY || fMinY >= keep.maxY) { keep(v1, v2, v3); return; }
        int count = 3;
        ensureScratch(count + 6);
        put(piece, 0, v1); put(piece, 1, v2); put(piece, 2, v3);
        for (int e = 0; e < 4 && count >= 3; e++)
        {
            // The part outside this edge is outside the box: kept. The rest goes on to the next edge.
            int out = split(piece, count, hx[e], hy[e], hx[(e + 1) % 4], hy[(e + 1) % 4]);
            if (out >= 3) { emit(outside, out); }
            float[] swap = piece; piece = inside; inside = swap;
            count = splitInside;
        }
        if (count < 3) { return; }
        // Inside the box: only the parts in the pieces around the silhouette.
        float pMinX = Float.MAX_VALUE, pMaxX = -Float.MAX_VALUE, pMinY = Float.MAX_VALUE, pMaxY = -Float.MAX_VALUE;
        for (int k = 0; k < count; k++)
        {
            pMinX = Math.min(pMinX, piece[k * 3]); pMaxX = Math.max(pMaxX, piece[k * 3]);
            pMinY = Math.min(pMinY, piece[k * 3 + 1]); pMaxY = Math.max(pMaxY, piece[k * 3 + 1]);
        }
        // Only the pieces of the part's rows: from the first that reaches below its top, to the first that starts below its bottom.
        List<float[]> pieces = keep.pieces;
        for (int i = keep.firstBelow(pMinY), n = pieces.size(); i < n; i++)
        {
            float[] q = pieces.get(i);
            if (q[1] >= pMaxY) { break; }
            if (q[5] <= pMinY || q[8] >= pMaxX || q[9] <= pMinX) { continue; }
            System.arraycopy(piece, 0, part, 0, count * 3);
            int m = count;
            for (int e = 0; e < 4 && m >= 3; e++)
            {
                int ex = e * 2, nx = ((e + 1) % 4) * 2;
                // The trapezoid runs clockwise on the canvas (y down): positive area in these coordinates.
                split(part, m, q[ex], q[ex + 1], q[nx], q[nx + 1]);
                float[] swap = part; part = inside; inside = swap;
                m = splitInside;
            }
            if (m >= 3) { emit(part, m); }
        }
    }

    /** Points of the last split's inside part (in inside); the outside part is in outside, its count returned. */
    private int splitInside;

    /** Splits the polygon src (count points) by the line from (ex, ey) to (fx, fy): inside is left of it for sign 1. */
    private int split(float[] src, int count, float ex, float ey, float fx, float fy)
    {
        float dx = fx - ex, dy = fy - ey;
        int in = 0, out = 0;
        for (int k = 0; k < count; k++)
        {
            int l = (k + 1) % count;
            float sk = dx * (src[k * 3 + 1] - ey) - dy * (src[k * 3] - ex);
            float sl = dx * (src[l * 3 + 1] - ey) - dy * (src[l * 3] - ex);
            if (sk >= 0) { copy(src, k, inside, in++); } else { copy(src, k, outside, out++); }
            if ((sk >= 0) != (sl >= 0))
            {
                float t = sk / (sk - sl);
                float d0 = src[k * 3 + 2], d1 = src[l * 3 + 2];
                float px = src[k * 3] + (src[l * 3] - src[k * 3]) * t;
                float py = src[k * 3 + 1] + (src[l * 3 + 1] - src[k * 3 + 1]) * t;
                float pd = 1f / (1f / d0 + (1f / d1 - 1f / d0) * t);
                set(inside, in++, px, py, pd);
                set(outside, out++, px, py, pd);
            }
        }
        splitInside = in;
        return out;
    }

    /** Room for polygons of up to points points in every scratch array. */
    private void ensureScratch(int points)
    {
        int room = (points + 8) * 3;
        if (piece.length < room) { piece = java.util.Arrays.copyOf(piece, room * 2); }
        if (inside.length < room) { inside = new float[room * 2]; }
        if (outside.length < room) { outside = new float[room * 2]; }
        if (part.length < room) { part = new float[room * 2]; }
    }

    private void put(float[] to, int k, int v)
    {
        to[k * 3] = x[v]; to[k * 3 + 1] = y[v]; to[k * 3 + 2] = depth[v];
    }

    private static void copy(float[] from, int k, float[] to, int l)
    {
        to[l * 3] = from[k * 3]; to[l * 3 + 1] = from[k * 3 + 1]; to[l * 3 + 2] = from[k * 3 + 2];
    }

    private static void set(float[] to, int l, float px, float py, float pd)
    {
        to[l * 3] = px; to[l * 3 + 1] = py; to[l * 3 + 2] = pd;
    }

    private void keep(int v1, int v2, int v3)
    {
        growFaces(faces + 1);
        a[faces] = v1; b[faces] = v2; c[faces] = v3; source[faces] = current;
        faces++;
    }

    /** A convex piece as a fan, on the points made for the face it is cut from where they lie (shared with its other pieces). */
    private void emit(float[] p, int count)
    {
        if (x.length < vertices + count)
        {
            int size = (vertices + count) * 2;
            x = java.util.Arrays.copyOf(x, size); y = java.util.Arrays.copyOf(y, size); depth = java.util.Arrays.copyOf(depth, size);
        }
        if (corners.length < count) { corners = new int[count * 2]; }
        for (int k = 0; k < count; k++)
        {
            long key = (long) Math.round(p[k * 3] * 64) << 32 ^ (Math.round(p[k * 3 + 1] * 64) & 0xffffffffL);
            Integer at = made.get(key);
            if (at == null)
            {
                at = vertices;
                x[vertices] = p[k * 3]; y[vertices] = p[k * 3 + 1]; depth[vertices] = p[k * 3 + 2]; vertices++;
                made.put(key, at);
            }
            corners[k] = at;
        }
        growFaces(faces + count - 2);
        for (int k = 1; k < count - 1; k++) { source[faces] = current; faces = face(faces, corners[0], corners[k], corners[k + 1]); }
    }

    private void growFaces(int n)
    {
        if (a.length < n)
        {
            int size = n * 2;
            a = java.util.Arrays.copyOf(a, size); b = java.util.Arrays.copyOf(b, size); c = java.util.Arrays.copyOf(c, size);
        }
        if (source.length < a.length) { source = java.util.Arrays.copyOf(source, a.length); }
    }
}

package com.hdworldmarkers;

import java.util.*;

/**
 * The on-screen silhouette of a projected model, as closed polygons in canvas
 * coordinates. Faces are rasterized onto a grid finer than a pixel and the
 * boundary between covered and empty cells is traced into loops. Each step of
 * a loop is then placed where the faces' own edges cross it, in floats, so the
 * outline lies on the model's exact edge and moves smoothly with it instead of
 * jumping from cell to cell (as the float clickbox does for RuneLite's
 * whole-pixel one). Used for outlines, which RuneLite otherwise draws pixel by
 * pixel in 2D.
 */
final class Silhouette
{
    /** The most grid cells a trace takes; the grid has a cell per canvas pixel, fewer for a shape larger than that. */
    static final int MAX_CELLS = 1 << 20;
    private static final long MAX_RASTER_WORK = 8L * MAX_CELLS;

    private Silhouette() { }

    static final class Scratch
    {
        /** The raster, one bit per cell, rows of (w + 63) / 64 words. */
        long[] bits = new long[0];
        /** Per lattice corner, the corners its boundary edges lead to (-1: none); all -1 between traces. */
        int[] out0 = new int[0], out1 = new int[0], loop = new int[64];
        final float[] intersections = new float[3];
        /** The cells with an edge (row * w + column, ascending), and where the faces' edges leave them: west, east, top, bottom. */
        int[] cells = new int[64];
        /** Per cell (row * w + column), its place in cells, or -1; only the cells with an edge are set, and reset after. */
        int[] index = new int[0];
        /** The cells with an edge, a bit per cell in rows of words as the raster: faces with none in their box are skipped. */
        long[] edges = new long[0];
        /** Per cell, where the faces' spans along its row start (when they start in it) and end: filled with the raster. */
        float[] rowStart = new float[0], rowEnd = new float[0];
        float[] west = new float[64], east = new float[64], top = new float[64], bottom = new float[64];
        int cellCount;
        /** Spans between two cell centres (covering neither): line (row or column, negative for columns), start and end. */
        int[] gapLine = new int[64];
        float[] gapLo = new float[64], gapHi = new float[64];
        int gapCount;
    }

    /**
     * The outline, its points on the exact edge. x, y: projected vertices (NaN: not projected); faces a/b/c index them;
     * hidden[f] skips a face.
     */
    static List<float[]> trace(float[] x, float[] y, int[] a, int[] b, int[] c, int faces, boolean[] hidden, Scratch scratch)
    {
        return trace(x, y, a, b, c, faces, hidden, scratch, true);
    }

    /**
     * As trace; without exact, the cell staircase simplified (the player's cut, made every frame, where a cell of precision
     * does not show).
     */
    static List<float[]> trace(float[] x, float[] y, int[] a, int[] b, int[] c, int faces, boolean[] hidden, Scratch scratch, boolean exact)
    {
        return trace(x, y, a, b, c, faces, hidden, scratch, exact, null);
    }

    /** Leaves cells out of a filled raster before it is traced: cell (i, j) covers canvas ox + i / scale to ox + (i + 1) / scale. */
    interface Mask
    {
        void apply(long[] bits, int words, int w, int h, float ox, float oy, float scale);
    }

    /** As trace, the mask applied to the raster first (only without exact, whose edges come from the faces). */
    static List<float[]> trace(float[] x, float[] y, int[] a, int[] b, int[] c, int faces, boolean[] hidden, Scratch scratch, boolean exact,
        Mask mask)
    {
        float minX = Float.MAX_VALUE, minY = Float.MAX_VALUE, maxX = -Float.MAX_VALUE, maxY = -Float.MAX_VALUE;
        for (int f = 0; f < faces; f++)
        {
            if (hidden != null && hidden[f]) { continue; }
            int i = a[f], j = b[f], k = c[f];
            // Faces with a vertex that was not projected (at or behind the camera) are left out, as RuneLite does.
            if (unprojected(x, i, j, k)) { continue; }
            minX = Math.min(minX, Math.min(x[i], Math.min(x[j], x[k])));
            maxX = Math.max(maxX, Math.max(x[i], Math.max(x[j], x[k])));
            minY = Math.min(minY, Math.min(y[i], Math.min(y[j], y[k])));
            maxY = Math.max(maxY, Math.max(y[i], Math.max(y[j], y[k])));
        }
        if (minX > maxX) { return Collections.emptyList(); }
        double width = (double) maxX - minX, height = (double) maxY - minY;
        // A cell per pixel; coarser for very large shapes, to bound the work per frame.
        float scale = 1;
        while (paddedCells(width, height, scale) > MAX_CELLS && scale > 0.25f) { scale /= 2; }
        // Oversized/elongated projections use the source's 2D outline instead. Check the
        // padded dimensions before narrowing to ints or allocating any raster memory.
        if (paddedCells(width, height, scale) > MAX_CELLS) { return Collections.emptyList(); }
        // One empty cell of padding on every side, so every loop is closed. The cells lie on a grid fixed to the canvas,
        // not to the shape, so a shape that moves keeps its cells where it does not change.
        int x0 = (int) Math.floor(minX * scale) - 1, y0 = (int) Math.floor(minY * scale) - 1;
        int w = (int) Math.ceil(maxX * scale) + 2 - x0, h = (int) Math.ceil(maxY * scale) + 2 - y0;
        float ox = x0 / scale, oy = y0 / scale;
        // Repeated overlapping faces must not multiply raster work without a limit.
        double work = 0;
        for (int f = 0; f < faces; f++)
        {
            if (hidden != null && hidden[f]) { continue; }
            int i = a[f], j = b[f], k = c[f];
            if (unprojected(x, i, j, k)) { continue; }
            double fw = (double) Math.max(x[i], Math.max(x[j], x[k])) - Math.min(x[i], Math.min(x[j], x[k]));
            double fh = (double) Math.max(y[i], Math.max(y[j], y[k])) - Math.min(y[i], Math.min(y[j], y[k]));
            work += paddedCells(fw, fh, scale);
            if (work > MAX_RASTER_WORK) { return Collections.emptyList(); }
        }
        // The raster as bits, 64 cells a word: filling, and finding the edges, work a word at a time.
        int words = (w + 63) >>> 6, total = Math.multiplyExact(words, h);
        if (scratch.bits.length < total) { scratch.bits = new long[total]; }
        else { Arrays.fill(scratch.bits, 0, total, 0); }
        long[] grid = scratch.bits;
        int cells = w * h;
        if (exact && scratch.rowStart.length < cells) { scratch.rowStart = new float[cells]; scratch.rowEnd = new float[cells]; }
        if (exact)
        {
            Arrays.fill(scratch.rowStart, 0, cells, Float.POSITIVE_INFINITY);
            Arrays.fill(scratch.rowEnd, 0, cells, Float.NEGATIVE_INFINITY);
        }
        scratch.gapCount = 0;
        for (int f = 0; f < faces; f++)
        {
            if (hidden != null && hidden[f] || unprojected(x, a[f], b[f], c[f])) { continue; }
            fill(grid, words, w, h, (x[a[f]] - ox) * scale, (y[a[f]] - oy) * scale, (x[b[f]] - ox) * scale, (y[b[f]] - oy) * scale,
                (x[c[f]] - ox) * scale, (y[c[f]] - oy) * scale, scratch, exact);
        }
        if (mask != null && !exact) { mask.apply(grid, words, w, h, ox, oy, scale); }
        List<int[]> corners = boundaries(grid, words, w, h, scratch);
        if (exact)
        {
            exact(x, y, a, b, c, faces, hidden, ox, oy, scale, w, h, scratch);
            extend(scratch, w);
        }
        List<float[]> loops = new ArrayList<>();
        for (int[] loop : corners)
        {
            float[] canvas;
            if (exact) { canvas = place(loop, w, scratch); }
            else { canvas = new float[loop.length]; for (int i = 0; i < loop.length; i++) { canvas[i] = loop[i]; } }
            for (int i = 0; i < canvas.length; i += 2) { canvas[i] = ox + canvas[i] / scale; canvas[i + 1] = oy + canvas[i + 1] / scale; }
            // Exact points need half a cell of tolerance to merge straight runs; a staircase one cell.
            float[] simple = simplify(canvas, (exact ? 0.5 : 1) / scale);
            if (simple.length >= 6) { loops.add(simple); }
        }
        // The index is left all -1 for the next trace.
        for (int i = 0; i < scratch.cellCount; i++) { scratch.index[scratch.cells[i]] = -1; }
        return loops;
    }

    /**
     * Where the faces' edges leave each cell with an edge (grid coordinates): along its row (west, east) and its column
     * (top, bottom). A cell whose neighbour is empty is covered only by faces whose span ends within that cell, so the
     * extreme end of those spans is where the silhouette crosses between the two cell centres; spans that fit between
     * two centres (thin slivers along the edge) extend it where they touch. Only faces with a cell with an edge in their
     * box are looked at: the many small faces inside a model made most of the work.
     */
    private static void exact(float[] x, float[] y, int[] a, int[] b, int[] c, int faces, boolean[] hidden, float ox, float oy, float scale,
        int w, int h, Scratch scratch)
    {
        int n = scratch.cellCount;
        Arrays.fill(scratch.west, 0, n, Float.NaN);
        Arrays.fill(scratch.east, 0, n, Float.NaN);
        Arrays.fill(scratch.top, 0, n, Float.NaN);
        Arrays.fill(scratch.bottom, 0, n, Float.NaN);
        float[] xs = scratch.intersections;
        // Along the rows, from the raster.
        for (int i = 0; i < n; i++)
        {
            int cell = scratch.cells[i];
            float start = scratch.rowStart[cell], end = scratch.rowEnd[cell];
            if (start != Float.POSITIVE_INFINITY) { scratch.west[i] = start; }
            if (end != Float.NEGATIVE_INFINITY) { scratch.east[i] = end; }
        }
        int words = (w + 63) >>> 6;
        if (scratch.edges.length < words * h) { scratch.edges = new long[words * h]; }
        else { Arrays.fill(scratch.edges, 0, words * h, 0); }
        for (int i = 0; i < n; i++) { int cell = scratch.cells[i], col = cell % w; scratch.edges[cell / w * words + (col >>> 6)] |= 1L << (col & 63); }
        for (int f = 0; f < faces; f++)
        {
            if (hidden != null && hidden[f] || unprojected(x, a[f], b[f], c[f])) { continue; }
            float ax = (x[a[f]] - ox) * scale, ay = (y[a[f]] - oy) * scale, bx = (x[b[f]] - ox) * scale, by = (y[b[f]] - oy) * scale;
            float cx = (x[c[f]] - ox) * scale, cy = (y[c[f]] - oy) * scale;
            if (!nearEdge(scratch.edges, words, w, h, Math.min(ax, Math.min(bx, cx)), Math.min(ay, Math.min(by, cy)),
                Math.max(ax, Math.max(bx, cx)), Math.max(ay, Math.max(by, cy)))) { continue; }
            int first, last;
            // Columns: the span at each column centre.
            first = Math.max(0, (int) Math.floor(Math.min(ax, Math.min(bx, cx)) - 0.5f));
            last = Math.min(w - 1, (int) Math.ceil(Math.max(ax, Math.max(bx, cx)) - 0.5f));
            for (int col = first; col <= last; col++)
            {
                float s = col + 0.5f;
                // The same crossing with x and y swapped: where the edges meet the column centre.
                int k = cross(ay, ax, by, bx, s, xs, cross(by, bx, cy, cx, s, xs, cross(cy, cx, ay, ax, s, xs, 0)));
                if (k < 2) { continue; }
                float lo = Math.min(xs[0], xs[1]), hi = Math.max(xs[0], xs[1]);
                if (k == 3) { lo = Math.min(lo, xs[2]); hi = Math.max(hi, xs[2]); }
                int from = (int) Math.ceil(lo - 0.5f), to = (int) Math.floor(hi - 0.5f);
                if (from > to)
                {
                    if (to >= 0 && find(scratch, to * w + col) >= 0 || from < h && find(scratch, from * w + col) >= 0) { gap(scratch, -1 - col, lo, hi); }
                    continue;
                }
                if (to < 0 || from >= h) { continue; }
                int i = find(scratch, Math.max(0, from) * w + col);
                if (i >= 0) { scratch.top[i] = Float.isNaN(scratch.top[i]) ? lo : Math.min(scratch.top[i], lo); }
                i = find(scratch, Math.min(h - 1, to) * w + col);
                if (i >= 0) { scratch.bottom[i] = Float.isNaN(scratch.bottom[i]) ? hi : Math.max(scratch.bottom[i], hi); }
            }
        }
    }

    /**
     * Whether a cell with an edge lies in the cells of this box (grid coordinates): those around the centres it spans, the
     * only cells a face so placed can set a crossing of or lie beside.
     */
    private static boolean nearEdge(long[] edges, int words, int w, int h, float minX, float minY, float maxX, float maxY)
    {
        int c0 = Math.max(0, (int) Math.floor(minX - 0.5f)), c1 = Math.min(w - 1, (int) Math.ceil(maxX - 0.5f));
        int r0 = Math.max(0, (int) Math.floor(minY - 0.5f)), r1 = Math.min(h - 1, (int) Math.ceil(maxY - 0.5f));
        if (c0 > c1) { return false; }
        int w0 = c0 >>> 6, w1 = c1 >>> 6;
        long first = -1L << (c0 & 63), last = -1L >>> (63 - (c1 & 63));
        for (int r = r0; r <= r1; r++)
        {
            int base = r * words;
            if (w0 == w1) { if ((edges[base + w0] & first & last) != 0) { return true; } continue; }
            if ((edges[base + w0] & first) != 0 || (edges[base + w1] & last) != 0) { return true; }
            for (int i = w0 + 1; i < w1; i++) { if (edges[base + i] != 0) { return true; } }
        }
        return false;
    }

    private static int find(Scratch scratch, int cell) { return cell < 0 || cell >= scratch.index.length ? -1 : scratch.index[cell]; }

    private static void gap(Scratch scratch, int line, float lo, float hi)
    {
        int n = scratch.gapCount;
        if (n == scratch.gapLine.length)
        {
            scratch.gapLine = Arrays.copyOf(scratch.gapLine, n * 2);
            scratch.gapLo = Arrays.copyOf(scratch.gapLo, n * 2);
            scratch.gapHi = Arrays.copyOf(scratch.gapHi, n * 2);
        }
        scratch.gapLine[n] = line; scratch.gapLo[n] = lo; scratch.gapHi[n] = hi;
        scratch.gapCount = n + 1;
    }

    /** Edges of adjacent faces, computed from either face, can differ by rounding. */
    private static final float TOUCH = 1e-3f;

    /**
     * Spans between two cell centres extend the crossing of the covered cell beside them where they touch it; a few
     * passes for slivers touching each other.
     */
    private static void extend(Scratch scratch, int w)
    {
        for (int pass = 0; pass < 4; pass++)
        {
            boolean changed = false;
            for (int g = 0; g < scratch.gapCount; g++)
            {
                int line = scratch.gapLine[g];
                float lo = scratch.gapLo[g], hi = scratch.gapHi[g];
                // The centres it lies between: before (on its low side) and after.
                int before = (int) Math.floor(hi - 0.5f), after = before + 1;
                boolean row = line >= 0;
                int i = find(scratch, row ? line * w + before : before * w + (-1 - line));
                float[] high = row ? scratch.east : scratch.bottom, low = row ? scratch.west : scratch.top;
                if (i >= 0 && !Float.isNaN(high[i]) && lo <= high[i] + TOUCH && hi > high[i]) { high[i] = hi; changed = true; }
                i = find(scratch, row ? line * w + after : after * w + (-1 - line));
                if (i >= 0 && !Float.isNaN(low[i]) && hi >= low[i] - TOUCH && lo < low[i]) { low[i] = lo; changed = true; }
            }
            if (!changed) { return; }
        }
    }

    /**
     * A traced loop (lattice corners {x0, y0, ...}) as points on the silhouette (grid coordinates): one per step, where
     * the silhouette crosses between the covered cell beside that step and the empty one across it; the step's middle
     * when no face edge was found there.
     */
    private static float[] place(int[] loop, int w, Scratch scratch)
    {
        int n = loop.length / 2;
        float[] out = new float[loop.length];
        for (int i = 0; i < n; i++)
        {
            int cx = loop[i * 2], cy = loop[i * 2 + 1], nx = loop[(i + 1) % n * 2], ny = loop[(i + 1) % n * 2 + 1];
            float px = (cx + nx) / 2f, py = (cy + ny) / 2f, v;
            if (nx > cx) { v = value(scratch, scratch.top, cy * w + cx); if (!Float.isNaN(v)) { px = cx + 0.5f; py = v; } }
            else if (ny > cy) { v = value(scratch, scratch.east, cy * w + cx - 1); if (!Float.isNaN(v)) { px = v; py = cy + 0.5f; } }
            else if (nx < cx) { v = value(scratch, scratch.bottom, (cy - 1) * w + cx - 1); if (!Float.isNaN(v)) { px = cx - 0.5f; py = v; } }
            else { v = value(scratch, scratch.west, (cy - 1) * w + cx); if (!Float.isNaN(v)) { px = v; py = cy - 0.5f; } }
            out[i * 2] = px;
            out[i * 2 + 1] = py;
        }
        return out;
    }

    private static float value(Scratch scratch, float[] values, int cell)
    {
        int i = find(scratch, cell);
        return i < 0 ? Float.NaN : values[i];
    }

    private static boolean unprojected(float[] x, int i, int j, int k)
    {
        return Float.isNaN(x[i]) || Float.isNaN(x[j]) || Float.isNaN(x[k]);
    }

    private static double paddedCells(double width, double height, float scale)
    {
        return (Math.ceil(width * scale) + 2) * (Math.ceil(height * scale) + 2);
    }

    /**
     * Marks cells whose centres lie inside the triangle (grid coordinates), and keeps where its span starts and ends in
     * the first and last cell of each row (and spans between two centres), for exact.
     */
    private static void fill(long[] grid, int words, int w, int h, float x0, float y0, float x1, float y1, float x2, float y2, Scratch scratch,
        boolean exact)
    {
        float[] xs = scratch.intersections;
        int top = Math.max(0, (int) Math.floor(Math.min(y0, Math.min(y1, y2)) - 0.5f));
        int bottom = Math.min(h - 1, (int) Math.ceil(Math.max(y0, Math.max(y1, y2)) - 0.5f));
        for (int row = top; row <= bottom; row++)
        {
            float sy = row + 0.5f;
            int k = 0;
            k = cross(x0, y0, x1, y1, sy, xs, k);
            k = cross(x1, y1, x2, y2, sy, xs, k);
            k = cross(x2, y2, x0, y0, sy, xs, k);
            if (k < 2) { continue; }
            float left = Math.min(xs[0], xs[1]), right = Math.max(xs[0], xs[1]);
            if (k == 3) { left = Math.min(left, xs[2]); right = Math.max(right, xs[2]); }
            int from = Math.max(0, (int) Math.ceil(left - 0.5f)), to = Math.min(w - 1, (int) Math.floor(right - 0.5f));
            if (from <= to)
            {
                setRange(grid, row * words, from, to);
                if (!exact) { continue; }
                int base = row * w;
                scratch.rowStart[base + from] = Math.min(scratch.rowStart[base + from], left);
                scratch.rowEnd[base + to] = Math.max(scratch.rowEnd[base + to], right);
            }
            else if (exact) { gap(scratch, row, left, right); }
        }
    }

    private static int cross(float xa, float ya, float xb, float yb, float sy, float[] xs, int k)
    {
        if ((ya <= sy && yb > sy) || (yb <= sy && ya > sy))
        {
            xs[k++] = xa + (sy - ya) / (yb - ya) * (xb - xa);
        }
        return k;
    }

    /** Sets the bits of columns from..to (inclusive) in the row starting at word base. */
    private static void setRange(long[] grid, int base, int from, int to)
    {
        int fw = from >>> 6, tw = to >>> 6;
        long fm = -1L << (from & 63), tm = -1L >>> (63 - (to & 63));
        if (fw == tw) { grid[base + fw] |= fm & tm; return; }
        grid[base + fw] |= fm;
        for (int i = fw + 1; i < tw; i++) { grid[base + i] = -1L; }
        grid[base + tw] |= tm;
    }

    /** Word i of a row shifted so each column holds its left (col - 1) neighbour; nothing enters at column 0. */
    private static long left(long[] g, int base, int i) { return g[base + i] << 1 | (i > 0 ? g[base + i - 1] >>> 63 : 0); }

    /** Word i of a row shifted so each column holds its right (col + 1) neighbour; the row's end brings nothing. */
    private static long right(long[] g, int base, int i, int words) { return g[base + i] >>> 1 | (i < words - 1 ? g[base + i + 1] << 63 : 0); }

    /**
     * Loops along cell edges between covered and empty cells, as lattice corner coordinates {x0, y0, x1, y1, ...}.
     * Each directed edge keeps the covered cell on the same side, so edges chain into closed loops. Only words with an
     * edge are visited; edges are kept per start corner in two flat arrays (a corner starts two at a diagonal touch),
     * without allocating per edge.
     */
    private static List<int[]> boundaries(long[] grid, int words, int w, int h, Scratch scratch)
    {
        int cw = w + 1, corners = cw * (h + 1);
        if (scratch.out0.length < corners)
        {
            scratch.out0 = new int[corners + corners / 2];
            scratch.out1 = new int[corners + corners / 2];
            Arrays.fill(scratch.out0, -1);
            Arrays.fill(scratch.out1, -1);
        }
        int[] out0 = scratch.out0, out1 = scratch.out1;
        int edges = 0;
        scratch.cellCount = 0;
        if (scratch.index.length < w * h)
        {
            scratch.index = new int[w * h + w * h / 2];
            Arrays.fill(scratch.index, -1);
        }
        for (int row = 0; row < h; row++)
        {
            int base = row * words;
            for (int i = 0; i < words; i++)
            {
                long cur = grid[base + i];
                if (cur == 0) { continue; }
                long up = row > 0 ? grid[base - words + i] : 0, down = row < h - 1 ? grid[base + words + i] : 0;
                long top = cur & ~up, bottom = cur & ~down, west = cur & ~left(grid, base, i), east = cur & ~right(grid, base, i, words);
                for (long any = top | bottom | west | east; any != 0; any &= any - 1)
                {
                    int bit = Long.numberOfTrailingZeros(any);
                    long m = 1L << bit;
                    int c = row * cw + (i << 6) + bit;
                    // The cell, in ascending order (rows, then columns), for exact.
                    if (scratch.cellCount == scratch.cells.length)
                    {
                        int size = scratch.cells.length * 2;
                        scratch.cells = Arrays.copyOf(scratch.cells, size);
                        scratch.west = new float[size]; scratch.east = new float[size]; scratch.top = new float[size]; scratch.bottom = new float[size];
                    }
                    scratch.index[row * w + (i << 6) + bit] = scratch.cellCount;
                    scratch.cells[scratch.cellCount++] = row * w + (i << 6) + bit;
                    // Per cell in the same order as before: top, right, bottom, left.
                    if ((top & m) != 0) { edges += add(out0, out1, c, c + 1); }
                    if ((east & m) != 0) { edges += add(out0, out1, c + 1, c + 1 + cw); }
                    if ((bottom & m) != 0) { edges += add(out0, out1, c + 1 + cw, c + cw); }
                    if ((west & m) != 0) { edges += add(out0, out1, c + cw, c); }
                }
            }
        }
        List<int[]> loops = new ArrayList<>();
        int scan = 0;
        while (edges > 0)
        {
            while (out0[scan] < 0 && out1[scan] < 0) { scan++; }
            int start = scan, from = start;
            int[] loop = scratch.loop;
            int size = 0;
            while (true)
            {
                int to = take(out0, out1, from);
                edges--;
                if (size + 2 > loop.length) { loop = scratch.loop = Arrays.copyOf(loop, loop.length * 2); }
                loop[size++] = from % cw;
                loop[size++] = from / cw;
                if (to == start || out0[to] < 0 && out1[to] < 0) { break; }
                from = to;
            }
            if (size >= 6) { loops.add(Arrays.copyOf(loop, size)); }
        }
        return loops;
    }

    private static int add(int[] out0, int[] out1, int from, int to)
    {
        if (out0[from] < 0) { out0[from] = to; }
        else { out1[from] = to; }
        return 1;
    }

    /** An edge from this corner, the one added last first. */
    private static int take(int[] out0, int[] out1, int from)
    {
        int to;
        if (out1[from] >= 0) { to = out1[from]; out1[from] = -1; }
        else { to = out0[from]; out0[from] = -1; }
        return to;
    }

    /** Douglas-Peucker on a closed polygon {x0, y0, ...}, tolerance in its own units. */
    static float[] simplify(float[] loop, double tolerance)
    {
        int n = loop.length / 2;
        // Split the loop at its first point and the one farthest from it, and simplify both halves.
        int far = 0;
        double best = -1;
        for (int i = 1; i < n; i++)
        {
            double dx = loop[i * 2] - loop[0], dy = loop[i * 2 + 1] - loop[1], d = dx * dx + dy * dy;
            if (d > best) { best = d; far = i; }
        }
        boolean[] keep = new boolean[n];
        keep[0] = true;
        keep[far] = true;
        mark(loop, 0, far, tolerance, keep);
        mark(loop, far, n, tolerance, keep);
        // The two split points are always kept; drop them too when they lie on a straight edge.
        for (int pass = 0; pass < 2; pass++)
        {
            for (int i : new int[]{0, far})
            {
                if (!keep[i]) { continue; }
                int prev = i, next = i;
                do { prev = (prev + n - 1) % n; } while (!keep[prev] && prev != i);
                do { next = (next + 1) % n; } while (!keep[next] && next != i);
                if (prev == i || next == i || prev == next) { continue; }
                if (distance(loop, i, prev, next) <= tolerance) { keep[i] = false; }
            }
        }
        int count = 0;
        for (boolean k : keep) { if (k) { count++; } }
        float[] out = new float[count * 2];
        int j = 0;
        for (int i = 0; i < n; i++)
        {
            if (keep[i]) { out[j++] = loop[i * 2]; out[j++] = loop[i * 2 + 1]; }
        }
        return out;
    }

    /** The distance of point i from the line through points a and b (from a when they coincide). */
    static double distance(float[] loop, int i, int a, int b)
    {
        double ax = loop[a * 2], ay = loop[a * 2 + 1], dx = loop[b * 2] - ax, dy = loop[b * 2 + 1] - ay;
        double px = loop[i * 2] - ax, py = loop[i * 2 + 1] - ay, length = Math.sqrt(dx * dx + dy * dy);
        return length > 0 ? Math.abs(px * dy - py * dx) / length : Math.sqrt(px * px + py * py);
    }

    /** Keeps points between from and to (to == n wraps to 0) farther than tolerance from the chord. */
    private static void mark(float[] loop, int from, int to, double tolerance, boolean[] keep)
    {
        // The chord once, not per point: this ran for every point at every level of the split.
        int end = to % (loop.length / 2);
        double ax = loop[from * 2], ay = loop[from * 2 + 1], dx = loop[end * 2] - ax, dy = loop[end * 2 + 1] - ay;
        double length = Math.sqrt(dx * dx + dy * dy);
        int index = -1;
        double max = tolerance;
        for (int i = from + 1; i < to; i++)
        {
            double px = loop[i * 2] - ax, py = loop[i * 2 + 1] - ay;
            double d = length > 0 ? Math.abs(px * dy - py * dx) / length : Math.sqrt(px * px + py * py);
            if (d > max) { max = d; index = i; }
        }
        if (index < 0) { return; }
        keep[index] = true;
        mark(loop, from, index, tolerance, keep);
        mark(loop, index, to, tolerance, keep);
    }
}

